/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20241125-5","meetingId":"r06-cm11","date":"2024年11月25日","dateIso":"2024-11-25","committee":"総務委員会","time":"午前１０時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 (2)第９２号議案、中原保育園および中原児童センター改築電気設備工事請負契約の変更","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 (2)第９２号議案、中原保育園および中原児童センター改築電気設備工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"今回インフレスライドという形で、仕方ないなと、このような情勢ですから。ただ、タイミング的に、この見直しを図るときのタイミングはいつ頃なのかということを教えていただきたいと思います。","respondent":"佐藤経理課長","answer":"既に工事中のところは所管課からも個別にお知らせしますけれども、それを受けまして、事業者のほうでこのインフレスライド条項を適用するかということをまず検討いたしまして、その上で区のほうに申請いただく。その後調整を図った上で契約変更を図る。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"だから現場とのずれというものがどれぐらいあって、請負業者との、結構やりにくいというか、やはりタイミング的に、スムーズな契約変更というものは必要かなと思うのですけれども、そこは今の流れは大丈夫なのですか。そこのずれの補正などはどのような形でやっているのか教えてください。","respondent":"佐藤経理課長","answer":"一方では、何％の範囲でそれを許すかというところは、他区の事例を見ても、それぞれの議会でご議論いただいて設定いただいているということかと思いますので、今後については、そういった事業者からの訴え等も踏まえて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そこの調整というものが、結構現場サイドと、それから算定する時期などというものが、それほど時期的に変わらないのですよというのであれば、現場の負担が少なくて済むかもしれないのですけれども、それが、例えば１年ずれてくるなどとなってしまうと、工事の遅れであったり、いろいろなことが影響してくるのではないかなと思うのですが、そこの時間軸というか、そのような観点は大丈夫なのでしょうか。","respondent":"佐藤経理課長","answer":"人件費でいきますと、この間設計労務単価というところでは、１０年以上継続的に上昇しているという状況でありまして、それに合わせてインフレスライド条項の適用についても図っているというところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問","question":"すみません。ちょっと素人のような質問なのですけれども、例えば入札というか、これ１億円だとすると、１億円に対してこれぐらいでいけますという入札が入りますよね。でも今、この時期は、インフレスライド条項で金額が上がっていくと。今答弁を聞いていると、インフレスライド条項を適用するかということも、話合いで決めるから、そのようなことは絶対にないのか、その辺を詳しく教えてください。","respondent":"佐藤経理課長","answer":"入札の際にインフレスライドを見込んで、低い金額で入れるということがあるかどうかというところかと思いますけれども、前提といたしまして、工事の予定価格を出しますが、それについては、その時点での最新の人件費や資材費を基にして設計しておりますので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問","question":"そうしたら、インフレスライド条項を適用するか決めるといった部分で、適用されないこともあるのですか。大体が適用されるのか、適用されないとこれは本当に死活問題で、大変なことになってしまうのかなと思ったのですけれども、その辺をお願いします。","respondent":"佐藤経理課長","answer":"制度的にインフレスライドを適用しますということで宣言していますので、というのは、人件費、あるいは資材費が急激に高騰した場合にこの制度を設定するということになりますので、それに基づいて、協議というものは計算をするわけなのですけれども。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"ですから、このような法律があるということでインフレスライドをやるのですけれども、前も申し上げましたが、民間にはこのようなことがないので、本当に公共工事に対する業者には、ある程度値段が高い安いはあるかと思うのですけれども、私は恩恵だと思います。これに対して異議はありません。そのときには何か補完する設備というのですか、そのようなものはあるのですか。分かる範囲で教えてください。","respondent":"長尾施設整備課長","answer":"停電時に太陽光パネルに代わる照明用やコンセント用の発電をするものということでいうと、現施設については、蓄電設備はありますので、そこで蓄電した分については、天気の悪いときをカバーするような形で使う想定になっております。","voiceIndex":16,"id":"exchange-006"}]},{"id":"topic-02","title":"第９４号議案、勝島地区雨水管整備工事請負契約","agenda":"第９４号議案、勝島地区雨水管整備工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"２番と３番は辞退になっていて、理由が書いてあるのですけれども、いつもの理由なのですが、少し不思議だったのは、２番は千代田区の会社です。３番は中央区です。そこで何か、規制はかけていないとは思いますけれども、そのようになってくると、利用できるパイというのですか、利用できる範囲を狭めているということも考えられなくはないのかなと思うのですが、そのような考えはいかがでしょうか。","respondent":"北原河川下水道課長、佐藤経理課長","answer":"本事業の財源という、１点目のご質問についてお答えします。入札の仕組みといたしまして、最初にどういった工事かという概要をお示しして、それに対して参加するかどうかということを手を挙げていただいて、それに対して。","voiceIndex":32,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"都からの補助金は分かりました。１０分の１０、１００％来るという形で、ありがとうあります。入札もしっかりされているのだろうと思います。いずれにしてもしっかりやっていただくということが基本ですので、それは信頼していきたいなと思います。決して安かろう悪かろうではなくて、それなりの金額の中でしっかり達成していただきたいという思いがありますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいことは、共同企業体に入る会社が、今回辞退した会社が２つあるということですが、都内に会社がこれしかないのですか。このような専門的な下水道工事、雨水管整備工事をやるわけですが、これしかないのでこれしか参加できないということですか。都内はそのように専門性の高い、技術のある会社が少ないということで、これしか参加してないということなのですか。そこだけ教えてください。","respondent":"佐藤経理課長","answer":"入札の参加要件のことかと思いますので、私からご答弁申し上げますが、工事発注する際は、一定の事業者が参加できるという前提をこちらとしても確保するということを考えておりますので、電子入札で品川区の工事に参加するかどうかということを事業者が選ぶところがあります。","voiceIndex":36,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"電子入札ということで、多くの事業者が参加しやすい状況をつくられていることは分かるのですが、品川区は支払いも別に悪いという話も聞いていない中で、このような状況ということは品川区は嫌われているのですか。もっと、品川区の工事をやりたい、支払いもいいし、事前に前渡し金も出てくる、様々いいはずなのに。何か評判が悪いのですか。教えてください。","respondent":"佐藤経理課長","answer":"工事に限らず、いろいろな案件、入札をかけていますけれども、やはり参加しやすい、例えば委託など、そういったものについては十何者を応札しているという状況もありますので、それぞれの工事の性格によって参加できる事業者。","voiceIndex":38,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ多くの事業者が参加できるような努力を、経理課としても私はしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"今もお話があったように、予定価格があって、ほぼ予定価格で落札しているというところと、１者は辞退、積算価格が予定価格を超過したためというところで、３分の２が辞退して、結果的に１者入札というものは課題だというところで、今いろいろお話があったとおり、いろいろ幅広く取りながら、そうならないようにという工夫というか、課題をなくしていくというところなのかなと思うのですけれども。","respondent":"佐藤経理課長、北原河川下水道課長","answer":"私からは入札に関わるところで、今回ほぼ予定価格で落札されているというところ、また、札を入れたものが１者になっているという部分についてお答えをいたします。私からは、２つ目の今回の工事、都からの受託工事ということで、予定価格の決め方というご質問についてお答えいたします。","voiceIndex":41,"id":"exchange-012"},{"speaker":"大倉委員","kind":"確認","question":"ご説明ありがとうございました。予定価格については、都からの受託事業であれ、区の事業であれ、区で決めていくという、積算基準、様々なところから取って、ないものについては見積りということだったので、そのようなところでいうと、どちらも品川区がする工事等の予定価格については区で決めていくということでいいのかということを、改めて確認させてください。","respondent":"北原河川下水道課長","answer":"東京都からの受託事業であっても、区でやる事業であっても、両方とも区で価格を決めているという意味です。","voiceIndex":44,"id":"exchange-013"}]},{"id":"topic-03","title":"第９５号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約の変更","agenda":"第９５号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"施工方法が変わったということが、今回とても大きかったのかなと思うのです。ですから、このようなことがあり得るものか、なぜこのようなことが起きたのかということ。それで、増額が２６.２％ということは、かなり大きいですよね。あまり実務のところには触れませんけれども、このようなことは今後あり得るのですか。今回のこの件に関していうと。いかがでしょうか。","respondent":"北原河川下水道課長","answer":"施工方法が変わったという内容についてですけれども、こちらについては、目黒川に下水道から出る雨水を流すためのはけ口を設置する工事において、仮設の方法を少し見直しまして、河川の断面を阻害しないようにする工夫や、より安全にできるように止水性を高める工夫などを。","voiceIndex":59,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"だからこれ、今後この割合等を考えたときに、どう考えたらいいのですか。だから１つの工事に対して、このような審議をして決めていくということは当然必要なことだと思っているのですけれども、今のこの物価高の状況を考えていくと、これから、見通しも含めると、それをプラスアルファ考えておかなければいけないという、そのような範囲などというものはある程度考えられているのでしょうか。","respondent":"佐藤経理課長","answer":"資材等が高騰している中で、予定価格をどう考えるかということで、基本的には、区役所の予算については年度ごとで管理するというところがありますし、契約に関しても、発注に関してはその時点での単価、人件費もそうですし、資材費もそうですが。","voiceIndex":61,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"そのときに、ではこのような契約案件を考えたときに、例えば１年後には変動見直しをしようとか、このような状況になったら、やはり今の契約の状況では賄えられないよねというような、目安というものは、庁舎の中ではある程度決められているのか、予測値というか、そのようなものはあるのでしょうか。","respondent":"佐藤経理課長","answer":"これまでの例でいきますと、東京都、あるいは品川区を含めた自治体についても、それを見ながら適用しているところですので、明確に、例えば何％というような基準はございませんが、著しい物価、人件費の高騰があるという状況であれば適用されるというように認識しております。","voiceIndex":63,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"国や東京都からの受託という形であれば、それは保証されてきますから、要は品川区の懐は痛まないと思うのです。十分に庁舎の中では検討されていることだとは思いますけれども、ぜひ、これから１年、２年だけではなくて、ある程度の中期的な予測も立てながら、財政の編成なども考えてほしいなと、そのことを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-017"}]},{"id":"topic-04","title":"第９３号議案、西五反田公園改修工事請負契約の変更","agenda":"第９３号議案、西五反田公園改修工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"当初が２億７,６６２万円余ですよね。第１回変更、今回２回目ということで、これ１回目のときは専決処分だった。今回はさらに追加された分だけだとすると４.９％増だから、専決処分でやれたのではないですか。すみません。考え方を教えてください。","respondent":"佐藤経理課長","answer":"今回２回目の変更でございまして、委員ご指摘のとおり、１回目の変更の金額からは５％以内の変更となりますけれども、令和４年度に５％以内の契約変更については専決処分で報告するという取決めになりましたが、この変更に関しては、あくまで当初の契約から考えるというところで。","voiceIndex":80,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"とすると、当初予算から、変更が何回かあったとしても、５％以上になった場合は、専決処分ではなくて議決が必要という形なのですね。それで、今回の変更が幾つかあるのですけれども、工事のこの１回目と２回目というものが、全然変更の内容が違うという理解でいいのですか。どのような、これにお金がどのぐらいかかっているからというような、そこを教えてほしいのですけれども。","respondent":"大友公園課長","answer":"第１回目と第２回目の変更内容は異なるものでございまして、第１回目の変更は、第１回目の変更があったときまでに発生したものです。第２回目の変更は、第１回目の変更後に起きたものに対して変更を行ったものという形になってあります。","voiceIndex":82,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"１回目と２回目の変更の内容が、変更概要の中に入っているものですよという理解でよろしいでしょうか。そうすると、この（１）（２）（３）とあるのですけれども、どのぐらいの割合になっているのですか。要は、工事の変更の部分とインフレスライド条項で、どのぐらいの割合になっているのか教えてください。","respondent":"大友公園課長","answer":"第２回の変更概要が、今回記載させていただいてあります変更概要という認識で、そのとおりです。割合についてなのですけれども、この第２回の変更の半分以上、６割程度がインフレスライド条項の適用になってあります。","voiceIndex":84,"id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"舗装復旧面積の変更など、１回目ではそこまでこれが必要ではなくて、２回目で必要になったというところの、バリアフリー施設はちょっと何だか分からないので、教えてほしいということと、休憩施設がもう少しあったほうがいいよねということは後から出たということだったと思うのですけれども、そうなった理由を教えていただけますか。","respondent":"大友公園課長","answer":"１点目、舗装復旧面積の変更なのですけれども、こちら設計時に想定した面積はあるのですが、まず机上で水道局等と撤去管の発生する面積を想定していたのですけれども、工事時の立会いの下に、もう少し詳細で、現地立会いの下で変更が生じたというところで。","voiceIndex":87,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"４月２２日に専決処分して、７か月ちょっとですか、同じ年度で二度やるということですよね。本来はインフレスライドというものは年度末に決めて、それで変動していくというようなお話を聞いていたのですが、もうその都度、年に２回でも３回でも、このようにあるのかなということを教えてください。教えてください。","respondent":"大友公園課長","answer":"インフレスライドの適用時期なのですけれども、賃金水準および物価水準の変動が生じたというところにおきまして、事業者から、変わってきているのでインフレスライドの適用をお願いしますという形での申請があって、その申請があったところから。","voiceIndex":90,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"人件費等が上がったということもあると思うのですが、そのようなものも、工事に今入っているわけですから、その中で職人は、その期間はある程度待機しているということもあるし、同一場所で工事をするならば、私はそれほど金額的に膨らまないのかなと思いました。私もそのように思いました。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"追認というものは、何でしょうか、認証されていたものに対して、追加でということですよね。これは２つとも議題に上がったことはないのです。追認という形でこれが上程されたことが、１１月６日の総務委員会のときにあまり意識がなかったのですけれども、改めて調べ直すと、追認ということはふさわしくないのではないかなと思うのですけれども、その辺をまずお聞きしたいのですが。","respondent":"佐藤経理課長","answer":"議会に事後的に追認の議決をいただければ、議決を欠いたことの、いわゆる法律上の瑕疵というように申し上げますけれども、こちらの瑕疵は治癒されるということで説明されているところです。","voiceIndex":107,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"このようなケースにおいて追認という形で議会に上程することは法的な根拠もあるという意味ですか、今おっしゃっているのは。そこを教えてください。","respondent":"佐藤経理課長","answer":"そのようなことによって、遡ってという形になりますけれども、その当時契約したこの案件について、時間はたちましたが、法律上の手続を経たという形になりまして、遡って有効になる、このような手続です。","voiceIndex":109,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、役所としてはこのようなデジタルというものに対してどのような考えで扱っていくのかということは見直しを図っていかなければいけないし、国の動きが何かしら示されているのだったら、それも示していただきたいと思うのですけれども、そのようなことが不思議です。そうしたら、ほかのところは図書費が入っていないのですかという話になってしまうのです。以上、それをまずお願いしたいと思います。","respondent":"佐藤経理課長、柏木学務課長","answer":"その中では、今回別途ご提案しております、工事に関しては１件１億８,０００万円以上の工事、動産あるいは不動産の買入れの部分については、動産は予定価格１件４,０００万以上の動産の買入れ。教科書を買うときに学校図書館分等を購入する場合はありますが、それを合わせたとしても、今回の令和２年度以外で４,０００万円を超えているものはないです。","voiceIndex":111,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"これ区で考えないのですか。決まりがないということですから。そこの考えをもう少し深く教えていただきたいということと、それから図書も入っているということなのですけれども、なぜ図書費なのですか、今回。入れる必要はなかったのではないですか。こればらばらではないですか。ですから、まとめているものとまとめていないものと、それと各学校での契約の合算額が何点も書いてあるのです。教えてください。","respondent":"佐藤経理課長、柏木学務課長","answer":"私から、先ほどのライセンス契約、非常に大きくなるので議決が必要なのではないかということについてお答えいたします。特に教科書採択のときになりますと、４月当初では下巻はまだ発売されておりませんので、４月当初には契約ができないと。ですから、発売された６月下旬から７月等に改めて契約をするという形を取ってあります。","voiceIndex":114,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今はその根拠になるものがないので、議会に上程するということはないのかもしれませんけれども、ただ、それでいいのかということです。大きな金額が動いているわけですから。だから、定例会の中で、議案が出てきてそこで審議をする、補正予算が来たら補正予算の審議をするというものを私たちはチェックしているわけではないですか。別々だったら、この７２万円ですか。そこを教えてください。","respondent":"佐藤経理課長","answer":"したがいまして、今回のこの件についても同様とお考えいただければと思います。","voiceIndex":117,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"そのような理論でいったならば、ここの１１月６日の資料でいう、各学校での契約の合算額というものがあるではないですか。これ合算で４,０００万円以上のところがあるのです。合算のときはいいのですか。これちょっとよく分からないのです。","respondent":"柏木学務課長","answer":"それを一覧にしますと、膨大な量になりますので、各学校分については、それをある意味、年額全部まとめてこちらに掲載をしていると。そのようなことなので、内容としては各学校の校長の契約権限の中で各契約がされているというものになります。","voiceIndex":119,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"まとめていきますが、ライセンス契約については、今後行政として全体で見直しを図っていただきたいと強く要望したいと思います。どうしても逃げになってしまうのではないですか。扱っているわけですから、やはり慎重に、しっかり議論をして、必要なのかどうかも含めて議会の中で議論するという、そのようなことはぜひやっていただきたいと思います。これは強く強く要望して、終わりたいと思います。","respondent":"久保田企画経営部長","answer":"この契約の関連にしましても、今経理課長からもご説明をさせていただきましたけれども、条例で定める一定の契約は地方公共団体の大きな財政負担となりますので、条例で決めた金額以上のものについては。","voiceIndex":121,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"一応賛成いたしますが、先ほど部長からもいろいろありましたけれども、根拠がないことは分かったではないですか。ライセンス契約については。だけれども、それでいいのですかと言っているにすぎないのです。ですから、そうしないと議会軽視と言われても仕方ないですよということが私の意見です。委員会いらないではないですか、そうしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-031"}]},{"id":"topic-05","title":"第８８号議案、品川区公契約条例","agenda":"第８８号議案、品川区公契約条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、実効性があるものにしていくというところで質問していきたいと思うのですけれども、この条例の検討のところで、検討組織が立ち上がって、検討事項もア、イ、ウ、エとありますが、この対象の契約についてということで、条例の概要でいうと、適用される公契約の範囲というところでは、工事の１億８,０００万円以上の契約とあるのですけれども。","respondent":"佐藤経理課長","answer":"ただいま公契約条例の対象となる契約の範囲という部分について、２点ご質問いただいたかと思います。１点目、工事の範囲として１億８,０００万円以上というように規定しましたが、その理由と検討委員会での意見ということかと思います。","voiceIndex":146,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、検討委員会のほうで当事者の皆さんの意見も聴いてというところで、小さい事業者だと様々大変な部分も出てくるというところでの了承があったのかなということは分かるのですけれども、やはりここが高いと、入り口なので、狭まってしまうのかなということは思ったので、これはやっていく中でブラッシュアップというのですか。","respondent":"佐藤経理課長","answer":"今後審議会を設置しますけれども、基本的には区長の諮問を受けたことについて検討いただいて答申をするという機関になりますが、そこでは様々なご意見が出るかと思いますので、そういったものを踏まえて、改正の是非については検討していくということになろうかと思います。","voiceIndex":148,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"確認","question":"分かりました。ですから、そういったことが検討されているのかということが１つと、指定管理も入れているということで、やはり賃金を上回る下限額になるというところでは、指定管理も入ったということはよかったなと思っているのですけれども、この指定管理者、全部入れていくということの理解でいいのか伺いたいと思います。","respondent":"佐藤経理課長","answer":"もう１点、指定管理につきましては、指定管理者が入っております部分については、基本的には対象にするということを考えておりますが、規則で決めることになりますので、今後、年度末に向けて調整を図っていくところです。","voiceIndex":150,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、目的のところに地域経済の活性化、条例の目的の第１条のところの最後のほうに、地域経済の活性化というように書かれているのですけれども、これがいわゆる、具体的にどのような、区内事業者の受注が広がり、そして雇用を守り、そしてその人たちが適正な賃金を得ることで、それがまた地域でものを買うという地域経済につながって回っていくという、そのような理解でいいのか。","respondent":"佐藤経理課長","answer":"地域経済の活性化を目的といたしましたのは、そもそも公契約に関しては、区内の事業者が受注できるものについては区内の事業者に対して発注するというところを原則にしておりますので、その点、また、今回労働者の方の労働環境についても確保するという役割も持っておりますので。","voiceIndex":152,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"先ほど検討委員会のお話があったかと思うのですけれども、石田ちひろ委員から、やはり対象となる契約の金額が高いのではないか、もう少し低くてもいいのではないかということで、これは検討委員会の中でというような話もあったかと思うのです。これはやはり公開したほうがよかったのではないかと思うのですが、この点はいかがでしょうか。","respondent":"佐藤経理課長","answer":"今回の条例の検討委員会の議事概要の公開のお話ということですけれども、今回条例を検討するに当たっては、いわゆる労使という、大きく見ると利害が異なる立場の方に入っていただいて、率直な意見をいただきたいという趣旨で会議自体も非公表といたしましたし。","voiceIndex":155,"id":"exchange-036"},{"speaker":"松本委員","kind":"質問","question":"恐らくここがすごく大事だろうと思うことが、別表の５に当たります区長への報告に関する事項です。本区の場合に、そこまでかなり詳しめにやろうと思われているのか、あるいは、申し訳ないですけれども、ほぼ形骸化しているチェックリスト方式のレベルでとどまるのか、この辺りのお考えはいかがでしょうか。","respondent":"佐藤経理課長","answer":"２３区においては１４区制定というところで、いわゆる半分を超えたというところもありまして、当初は事業者の負担というところがかなり課題ではないかという認識ではございましたが、運用していく他の自治体の事例などを見ますと、対応できるのではないかということもありまして。","voiceIndex":157,"id":"exchange-037"},{"speaker":"松本委員","kind":"質問・要望","question":"そうすると、やはりこれは戻って、労働者側からの申告がどこまできちんとされるかというところが大事なのかなというところで、そうなると、先ほど石田ちひろ委員がおっしゃられていた、労働者側が自分の時給が今下回っているのかどうなのかということを知る機会がどこまで確保できるのか、周知できるのかというところかと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、ここは削除を求めたいと思っています。分からないではないのですけれども、今回の学識経験者３人、労働者、事業者、２人ということなのですが、名前などはもう、どこの団体かということもおっしゃれないのですか。どこまで、審議会ですか、立ち上がるということなのですけれども、議会に対する、何かそのような説明というものはしていただけるものなのかもお答えいただきたいと思います。","respondent":"佐藤経理課長","answer":"議会への説明については、他の案件と同様、重要なものについては、常任委員会をはじめといたしましてご説明しておりますので、その中で考えていきたいと考えております。","voiceIndex":161,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"見直しをしてほしいと要望したいと思います。この公契約条例の中でも必要なところ、労務単価もそうなのですけれども、そのようなものがここではこうなっています、ああなっていますというようなものがあると検討しやすいかなと思っていますので、それも含めて、今後議会への説明、それから区民への説明、それも少し考えていただきたいなということを意見として言わせていただきたいと思います。","respondent":"佐藤経理課長","answer":"議会でのチェックの部分についてですけれども、先ほどのとおりではありますが、重要な案件につきましては、各常任委員会等でご報告しているところでありますので、もちろんそれ以外にも、予算特別委員会。","voiceIndex":163,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、かなり実態と違ってしまうのではないかと思うのですが、その辺はどうなのでしょうか。何か問題があったら是正勧告をして、契約の解除を求めるという話ですけれども、実際途中まで仕事をしていて、その事業を、ではやめてくださいと、やめられるわけにいかないし、そこで引き継げるかといったら引き継げないではないですか、現実論。そのようなことは実際どうなのですか。","respondent":"佐藤経理課長","answer":"２点目ですけれども、いわゆる工事の中で、多重構造、先ほどご説明しましたが、そういった中では管理が大変ということのご指摘かと思います。我々としても、そこのところは非常に課題であるというように認識しております。","voiceIndex":166,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"勤務実態などはいくらでも変えられるということは私たちは何度も聞いているので、勤務実態も、それから払う払わないということもたくさん聞いているので、ただ実際やっていくのには、本来なら、このようなことはしたくないけれども、区の職員が実際抜き打ち検査でもしない限りは、したとしても、いくらでも巧妙に、今まで下請が苦労されて対応しているわけですから、私は難しいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-042"},{"speaker":"大倉委員","kind":"質問・要望","question":"条例のところの適用される公契約の範囲というところで、１１件というお話が先ほどあったかと思っていて、これ１１件というところは、全体の先ほどのお話の中でも、事務の負担や、行政側もそうですし、事業者からも、孫請の方たちなどもそうだというところで、一定のこの額で考えてきたということで、よく分かりましたというところと、そのイやウのところもそうなのですけれども。","respondent":"佐藤経理課長","answer":"工事については１億８,０００万円以上ということで、実数を申し上げて、契約数としては少ないというご指摘かと思いますけれども、ただ、契約金額で考えますと、いわゆる区の発注する工事の半数は超えるということで認識しておりますので、契約金額が多いということは。","voiceIndex":170,"id":"exchange-043"},{"speaker":"大倉委員","kind":"質問・要望","question":"工事のところは分かりました。次に、審議会についても、設置がされてよかったなです。ほかだと二、三回など、そのような形なのかなというように認識しているのですけれども、特に今回公契約条例が制定されて、これから、今もお話があったように運用が進んでいくというところでは、回数を少し多めに実施していくとか、少し慎重に進めていっていただきたいなと思うのですが、いかがでしょうか。","respondent":"佐藤経理課長","answer":"予算編成が終わって、どういった形になったかということで、報告するということで１回ということで、合計３回程度予定しています。","voiceIndex":172,"id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"それで少しご質問させていただいたのですが、積算の方法については、改めて区のほうで一定、これはいろいろな基準などを基に進めていくというところであると聞いているのですけれども、その中で公契約として進めていく中で、先ほどもそうでしたが、辞退者があったり、予定価格ぎりぎりだったりというところで。","respondent":"佐藤経理課長","answer":"１つ目は審議会の回数についてですけれども、基本的には区長が諮問したことについて検討いただくということで、労働報酬下限額については、先ほど申し上げたとおり、予算を前提として、その前に２回程度と考えておりますが、今後。","voiceIndex":174,"id":"exchange-045"},{"speaker":"大倉委員","kind":"意見","question":"区長の諮問に沿ってというところで、回数等、また、様々な懸案についてされるということで、分かりました。様々、いろいろな事情に応じて、ぜひ柔軟に対応していっていただいて、公契約条例の運用が始まったばかりですので、しっかりとこの目的に合った公契約条例になるように、ぜひ進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-046"},{"speaker":"まつざわ委員","kind":"質問","question":"私自身３０年前に土木をやっていたときは、１日１０時間ぐらい働かされて５,０００円しかもらえなかったのです。それも親方からすると、教えてやっているのだからそのようなものだと言われていて、ああそのようなものかなと。区としてどこまでこのようなものを介入していく、何というのですか、覚悟というか、意気込みというか、があるのか、それだけ教えてください。","respondent":"佐藤経理課長","answer":"そういった動きを見ながら、今回制定を提案しております公契約条例でも、例えば労働者側からの申出がしやすいような形で、もちろん契約上も位置づけておりますけれども、区の受入れとしましても、申出がしやすいような形で検討していきたいと考えております。","voiceIndex":178,"id":"exchange-047"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"簡潔に伺いたいと思います。今後、また審議会ができるということなのですが、同じ学識者、また労働者、事業者というようになっていると思うのですけれども、同じ方が引き続き審議会メンバーになるのかというところを１点、確認させてください。これをつくったことでの職員の負担や、事業者等の負担にならないようなところは、どこで担保されるのかというところをお聞かせいただきたいと思います。","respondent":"佐藤経理課長","answer":"３点ご質問かと思います。１点目は、今年度開催いたしました検討委員会についてですけれども、副委員長ご指摘のとおり、労使と対立する側で出ていただきましたが、非常に建設的なご意見をいただいて、非常にいい雰囲気だったということは、担当の課長として認識しております。","voiceIndex":180,"id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"ちょっと１点だけ、先ほど目的のところが出たので、そこだけはっきりしておかないといけないと思うのですけれども、条例案の目的と説明資料の目的はやはり違うというところで、条例案は他の自治体の条例を見ていただけると分かると思うのですが、持続可能も、地域経済の活性化も、区民の福祉増進も一応よくある、持続可能は最近よく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-049"},{"speaker":"西本委員","kind":"意見","question":"賛成いたしますが、やはり目的のところは私も考え方がありまして、意見をいろいろ言わせていただきましたので、それはそれとして、今後も変えていくべきところはしっかり変えていく、趣旨をとらまえるところはしっかりとらまえていくという形でしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-050"}]},{"id":"topic-06","title":"はじめに(1)専決処分の報告","agenda":"はじめに(1)専決処分の報告","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"ここはしっかりと議会に報告をしていただくということはもう第一義的にあるので、少し矛盾したような言い方になりますけれども、この５％以内で専決処分が現状足りているのかどうかというところの認識といいますか、区の受け止めを教えていただきたいなと思います。","respondent":"佐藤経理課長","answer":"したがいまして、５％が高いのか低いのかというところは、それぞれの契約の中であろうかと思いますが、全体としましては、経費は上昇傾向にあるということですので、本日も午前中ご審議いただいた中でも、契約変更に係る部分でご審議いただいた部分。","voiceIndex":198,"id":"exchange-051"},{"speaker":"新妻副委員長","kind":"意見","question":"すぐにここを変えるなどということではなく、いろいろな動向が、また変動が激しくあるご時世かと思います。事業者のお声も聴いていただきながら、適正な判断をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"これはもう今回見直しを図られたということで、それは理解はあるのですけれども、この差額というものは、今後どこに入ってくる、これ決算でないと分からないということなのですか。今回の補正予算などには入っていないと思うのですけれども、どこでこれが表現されてくるのかなと思うのですが、そこを教えてください。","respondent":"佐藤経理課長","answer":"今回の増額に係る予算ですけれども、第３回定例会に提案しました補正予算で計上しておりまして、その部分について契約の変更を図るというものです。","voiceIndex":206,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"そうすると、補正でやっていたら結局は決算という形で、令和６年度の決算のときに、この数値も入れた形で全体が見えるという形ですか。何を言いたいかというと、今回も専決処分が多いなと思っているのです。ごめんなさい、全体の補正のときにきちんと覚えていないのですけれども、例えば基金から出してくるのか、どこから持ってくるのですか、途中でこのような形で。","respondent":"加島財政課長","answer":"補正予算全般に関してのお話にもなろうかと思うのですけれども、特定財源の使えるものは、都補助金や国補助金という形で歳入に表しています。ただ、一般財源で持ち出さなければいけないものにつきましては、年度途中は財政調整基金から転用させていただいているところです。","voiceIndex":208,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"今年度においては、このような形で出ていますけれども、今のところ財政調整基金などで賄っているから大丈夫ですよという認識でよろしいですか。","respondent":"加島財政課長","answer":"年度途中の補正につきましては財政調整基金から充当していますが、決算のときによって、また当初予算では予測していなかった補助金の収入等も踏まえまして、何といいますか、財政調整基金を充てた部分が。","voiceIndex":210,"id":"exchange-055"}]},{"id":"topic-07","title":"専決処分の報告について（報告第３７号）","agenda":"専決処分の報告について（報告第３７号）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この前のほうにも関係するのですけれども、アスベスト除却内容が変わったなど、施工もいろいろと条件が変わってきた関係で変更となったのですが、これ技術的な話になったらごめんなさい、どのようなところが変わったという認識、アスベストの除却というと、もうほぼほぼ今まで決まってやっていたのではないかなと思うのですけれども、それが途中で何か入ってくるということは。","respondent":"佐藤経理課長","answer":"浜川中学校のほうからいきますけれども、アスベスト除却工法の変更については、既存建物に含まれるアスベストの含有について、施工段階で再度調査を実施して、設計で見込んだものより飛散性が低かったということで、除却方法が簡易といいますか。","voiceIndex":221,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"すみません。１件、浜川中学校のほうなのですけれども、地中障害物撤去、これ何か出たのですか。歴史的なものだと、なかなか工事に着手できないというような形になってしまうのですけれども、そのようなものではないという認識でよろしいですか。","respondent":"佐藤経理課長","answer":"浜川中学校で地中から出たものは、道路が後退した工事の際に、道路内のＵ字側溝のコンクリートのがらが出てきたということで、事前には分からなかったということでした。","voiceIndex":223,"id":"exchange-057"}]},{"id":"topic-08","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中総務委員会に関わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中総務委員会に関わる項目","exchanges":[{"speaker":"西本委員","kind":"質問","question":"総務委員会が担当でないという場合には指摘してください。高橋しんじ議員の教育についての中で、教育委員の任命同意がありました。教育委員だけではなくて、この同意というくくりの中で、やはり紙切れが１枚でよく分からないので、事前にそれぞれの担当委員会の中で質疑をし、その上で本会議場で決を採るということが筋ではなかろうかということを議論したいのですけれども、不適切でしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-058"},{"speaker":"こしば委員長","kind":"質問","question":"私もまだ、議事録全部を見ているわけではないですけれども、高橋しんじ議員の一般質問の中の教育のところを指していると思うのですが、答弁は全て教育委員会の理事者のほうからなされてきていると思いますので……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"だから、その選任同意という仕組み、質問がずれてしまうかなと思ったのですけれども。今回は高橋しんじ議員の質問は教育委員なので、そこでの質問になってくると文教委員会になるのかなという思いはあるのですけれども、総務委員会としてはそのような、ただ、そうすると項目の中に入っていませんよねという話になってしまうので、少し難しいかなと思いながら言ってみました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6913#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":59428,"voices":237}},{"id":"r06-20241126-6","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"区民委員会","time":"午前１０時０６分～午前１１時３９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6921#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":928,"voices":8}},{"id":"r06-20241126-7","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"厚生委員会","time":"午前１０時００分～午後 １時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番を入れ替えまして、(5)品川区子ども家庭センター設置に伴う保健センターの役割","agenda":"の順番を入れ替えまして、(5)品川区子ども家庭センター設置に伴う保健センターの役割","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"地域子ども家庭支援センターに専門職を配置するということだと思うのですけれども、新たにこれは専門職として配置されることになるのでしょうか。その専門職というのは、どんな資格で何人体制くらいになるのか、具体的に何をするのかというあたりをお聞かせいただけたらと思います。こういう組織として設置されることになった背景についても伺えたらと思います。","respondent":"石橋品川保健センター所長、染谷子ども家庭支援センター長","answer":"品川区では、保健センターで母子保健事業を今まで実施しておりまして、そちらを国のほうでは法律上、子育て世代包括支援センターと呼んでいるものでして、こちらの役割として。サービス面については、子ども家庭支援センターで実施しているショートステイの事業があるのですけれども、そちらを健診の場所で紹介するとか、あと、物によってはその場で予約を受付するなど。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"専門職の福祉や心理の方に相談ができる体制ができるというのは、すごくいいことだなという思いがしているのですけれども、そういうことで、「ここで相談が受けられます」という形で、看板とかも掲げられて、「どうぞ相談においでください」という形になるのか、そこの体制だけでなく、区民向けの相談のスペースというか、そのようなものもできるのか、その辺も伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"身近な地域でというところ、まさにそういったところが一つ、狙いとなってくるところでありますけれども、それぞれの保健センターにおいて、そういった子育て支援に関するサービス、それから相談ができるということについては、きちんとサインなどを出して。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、経験ある子家センの職員の方がそちらに配置されるという部分はあると思うのですけれども、トータルとしてはどれぐらいの職員が増えるのかという点について伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"現在、あくまで予定している人数ではありますけれども、福祉職については９名の増員、心理については１名の増員、そのほか、保健師も一部、今回の子ども家庭センターの開設に合わせて採用の予定があって、そちらは３名の採用といいますか、人員増を予定しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"すみません、教えていただきたいのですが、これは全部がいい方向に行くと思っていて、いいと思っています。それで、地域の近くのところでということなので、すごくいいと思っています。その辺は大丈夫ですか。結局、困難だとかいう相談が多いわけだから、あまり隣でということがないように、もちろん考えていらっしゃるのでしょうけれども、それだけ確認をしたいです。","respondent":"石橋品川保健センター所長","answer":"そのことも踏まえまして、今あるスペースの中で、隣り合わせて相談が漏れないような体制を組むなど、あと、相談の予約の取り方を含めて、場所と予約体制等も含めて検討しているところで、委員ご質問の心配のようなことが起きないようにということで。","voiceIndex":14,"id":"exchange-004"},{"speaker":"若林委員","kind":"確認","question":"２番の位置づけのところの確認というか、さっき読み上げられたのですが、具体的には２段目、これまで健康推進部内で使用していた相談支援記録等のシステム。これについて、情報共有をスムーズにということは、いわゆる保健と福祉の情報共有をスムーズに行うと読んでよろしいのですねという確認と、さらに、国のガイドラインに沿った様式。これはいつ、どんなガイドラインを指しているのかという確認が一つ。","respondent":"石橋品川保健センター所長","answer":"各種母子保健事業を通じてというところになりますが、健診ですとか、あとは育児学級等に、今までは保健センターの保健師が実施しておりましたが、そちらに子ども未来部の福祉職とお話させていただいた専門職が一緒に入りまして、両方の観点から。","voiceIndex":17,"id":"exchange-005"},{"speaker":"若林委員","kind":"確認","question":"それぞれに保健と福祉が一定、レベルアップした連携を図って、また、一緒にプランもつくるという、ここには書かれていませんけれども、大変重要なポイントをつかれている体制になるということで、あえて、ずっと言っていますが、教育関係との部分では、このシステムの話で言うと、何か関連性はありますかということだけ確認させてください。","respondent":"染谷子ども家庭支援センター長","answer":"システム上、現状は、今ご説明したシステムでは共有はしておりませんけれども、サポートプラン自体は、定期的な個別の会議ですとか、既存の会議体を活用する、それから、場合によっては庁内のサーバーでのデータ共有なども含めて、母子保健、児童福祉に限らず。","voiceIndex":19,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは、子育て応援課でされていたひとり親相談係というところが、ここの機能に入るのかというところが１点と、あとは、参考資料の２の（２）のところでも、子ども家庭支援センターでひとり親や女性支援・相談を実施、また相談体制を強化というところがあるので、どのように強化をされるのか、また、女性支援と相談というところがどういう内容を指すのかというところも改めて確認をさせてください。","respondent":"飛田子育て応援課長","answer":"ひとり親相談係というのを、今、子育て応援課に設置しておりますが、それをそのまま子ども家庭支援センターに設置するです。今までのひとり親の家庭相談では、あくまでも対象は親の立場というところに注目して、相談に乗っていました。","voiceIndex":22,"id":"exchange-007"},{"speaker":"ひがし委員","kind":"確認","question":"ちなみに女性相談というところは、もともと機能していた女性相談員による女性の方々への支援というところも、継続するという認識でいいのかというところも最後に確認させてください。","respondent":"飛田子育て応援課長","answer":"そちらの子育てのところもそうですし、お母さんとか女性の支援というところも今までどおり行うということになります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"意見","question":"もともとあった係がどうなるのかというところが気になったので、子どもも親もというところで、子ども家庭支援センターという中の機能に組み込まれたというところで認識をさせていただきました。相談体制というところもすごく重要になってくると思いますし、私もひとり親家庭で育って、親が大変そうにしているのも実感しているので、この機能というところも強化していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"}]},{"id":"topic-02","title":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備計画の進捗状況","agenda":"東大井三丁目における都有地（都営元芝アパート跡地）を活用した特別養護老人ホーム等の整備計画の進捗状況","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"東大井三丁目の特養ホームは、３か所のうちの一つで、すごく期待されるところなのですけれども、これはもともと都有地のところで建てるということなので、事業者の募集要項とかを見たら、５０年の定期借地ということになっていたのですけれども、これは東京都との契約で５０年の定期借地ということになると思うのですが。","respondent":"東野福祉計画課長","answer":"定期借地権の設定契約につきましては５０年、こちらにつきましては、都の都有地活用による地域の福祉インフラ整備事業実施要綱により定められているものです。こちらから類推しますと、５０年たった場合につきましては、原則お返しいただくというところで考えられるものです。","voiceIndex":32,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"５０年で老朽化ということなのですけれども、そこで更地にして返すとなると、入所している人たちの受皿をまたどうするか、５０年後なので、どういう調整になっているかというのは分かりませんけれども、定期借地のいつも問題になるようなところで、需要があって、やはりそれは必要ということになれば、先日のここでのグループホームの３０年のように。","respondent":"東野福祉計画課長","answer":"５０年先ということで、何かとお答えしにくいところもありますけれども、その時々の状況によりまして、東京都で判断されるということになろうかと思います。","voiceIndex":34,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこのところは確認しておいていただけたらと思います。それから、借地料がどれぐらいなのかというのは、この運営が本当に安定的にできるものなのか、どうなのかというところにも関わるところでもあると思うので、その辺のところは確認しておいていただきたいと思うのですけれども、その点もお願いします。","respondent":"東野福祉計画課長","answer":"品川区との関係におきましては、こちらの福祉避難所のほかに、地域交流拠点ということになりますので、地域への貸出しについて、どういう形で貸し出せるのかというところを改めて協議していくということになります。","voiceIndex":36,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"都の土地を借りて特養ホームをつくるというのは、多分、品川区としては初めてのことだと思うのです。そういう点では、一番初めに説明を受けたときよりも、定員数も増えているのです。初めは８０人くらいと説明を受けていたのが、１０５人になりましたし、ショートステイのほうも増えましたし、そういう点では本当に期待のある施設というところですので、期待に沿えるような形で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いしたいのですけれども、この施設は通所介護も入られるということで、送迎のサービス等が入るかなと思っていて、実際、ここの道路というか道で、両側通行がかなり狭いのです。","respondent":"東野福祉計画課長","answer":"計画地自体はセットバックをいたしまして、１.５ｍの歩道というのをセットバックするということで聞いておりまして、その部分はある程度広くなるのですけれども、こちらに入ってくるまでの道については、今のところ整備する予定はないと聞いております。","voiceIndex":40,"id":"exchange-014"}]},{"id":"topic-03","title":"「しながわ健康プラン２１（第二次）」素案にかかるパブリックコメントの実施","agenda":"「しながわ健康プラン２１（第二次）」素案にかかるパブリックコメントの実施","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"しながわ健康プランの素案のところの内容で、２点ほど質問させてください。その中で、No.１、９、１０、１１が増やすという内容になっていて、数値の目標が出ていないので、これを数値目標としていない理由が何かあるのかなと思うので、その点について教えていただきたいというのが１点です。次に、４９ページのところのしながわ健康ポイントについての質問になります。","respondent":"若生健康課長","answer":"あるいは、区の総合実施計画に重なっている指標というのもあります。それの目標値は既に定めているところですので、そこと合わせた形にしている。","voiceIndex":47,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"５％と一律にするのは根拠が薄いということで、増やすという内容にしているということで理解をいたしました。中間評価をしたときに、増やすというのが増えていたら、どうやっていくというのが見えにくいのかなという点は少し思いました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ＰＤＣＡサイクルはどうなるのかなと思ったら、６９ページのところにＰＤＣＡ図表を挿入予定ということで書かれていたので、この計画について検証して、さらにバージョンアップしていくというところの取組もされると思うのですけれども、そこのところでは、協議会をつくって検討するということも書かれていたと思うのですが、その協議会というのはどういうメンバーで。","respondent":"若生健康課長","answer":"パブリックコメントに際しての説明会の実施につきましてですが、今回、パブリックコメントを行うに当たっての住民説明会は、現時点では予定を考えてございません。","voiceIndex":51,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"少し細かいところなのですけれども、６２ページのところで、健康寿命を延ばしていくというのがあって、すごく大事だと思うのですが、６２ページのところに「６５歳健康寿命」というのが書かれていまして、要介護２以上となっているのですけれども、健康寿命、要介護２というと、要介護２までは健康という捉え方ということなのか、それは何か国の資料とかがあって、このような形になっているのか。","respondent":"若生健康課長","answer":"これは、東京都の健康プランの指標をそのまま横引きしているものではありますので、６５歳健康寿命（要介護２以上）という設定の仕方については、東京都で設定しているところになっておりますが、設定そもそもの考え方等については。","voiceIndex":53,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"協議会のまとめについては、公開していないということなのですけれども、ぜひ公開できるようなまとめをしていただいて、ホームページの公開とか、こちらにも報告いただいて、健康についてみんなで議論できるという場にしていただけたらということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"今はもう団塊の世代の方が７５歳になって、１０年後には介護保険も倍増するだろうという話があるわけだから、それをいかに抑制できるかというところも考えると、５５歳ぐらいから体を動かすことを、今、既に始まっているので、それを介護保険の中でやるというと、またいろいろ考え方があるので、介護保険の外、一般財源でやっていくというほうが私はいいと思っていて、一般質問したのだけれども。","respondent":"若生健康課長","answer":"そういったデータですとか、企業や団体といったところへのアプローチもかけていきますので、そういったところとの情報交換をしながら、働き盛り、５５歳とか５０代というところの健康についても取り組んでまいりたいと考えています。","voiceIndex":57,"id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"たくさん事業もやられているし、ただ、総花になると、何をやってきたかがよく分からなくなってしまうところがあると思うので、ある程度、これはこれで計画ですから、絞っていただいて、これは強くやっていこうとかいうのは、ぜひいろいろな連携を行うこともしていただいて、やっていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問","question":"４９ページ・５０ページのしながわ健康ポイントについてなのですけれども、現状値３,８１１人という数字がありますが、これはアプリをインストールされている方の総数とか、実際ポイントをためられたりという動きをしているというか、使っている方の人数なのか、どちらになりますでしょうか。","respondent":"若生健康課長","answer":"こちらについては、現在、アプリが令和５年度から新しくなっていまして、新しいアプリでは、インストールして、それを利用されている方というところがイコールになっておりまして、基本的には、インストールしていただいている方の数が３,８１１人ということになります。","voiceIndex":61,"id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要は、４０万人人口がいるうちの２.５％ぐらいという目標になっているので、毎年１,０００人ぐらい増えていれば、令和１１年度で１万人になるというところだと思うのですけれども、いい取組であるならば、もう少し高めに設定して、それこそ１０％ぐらいで４万人とかにして、もっと周知というか、広報を強めていければと思うのですけれども、その中で、例えば様々なイベントとか、それこそ来年。","respondent":"若生健康課長","answer":"目標値の１万人ですけれども、おっしゃるとおり、基本的に毎年度１,０００人程度というところを現実的な目標として、これは総合実施計画の指標と合っているところではありますけれども、当然、実際には現状値というのが令和５年度の実績になっていますが、今年度。","voiceIndex":63,"id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それで、次なのですけれども、同じ４９ページのところで、自転車ネットワークの整備ということで、有酸素運動になって非常に自転車というのは健康推進にいいかなと思うのですけれども、自転車ネットワークの整備という中に、よく最近、まちにある貸し自転車というか、３０分２００円とかで実施しているような、ああいうものはこの整備の中に、そういったものを区で行うとか、何か計画がありますでしょうか。","respondent":"若生健康課長","answer":"自転車ネットワークの整備の中身につきましては、防災まちづくり部の事業になっていまして、貸し自転車というところが含まれるかは把握してございません。","voiceIndex":65,"id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"最後に要望なのですけれども、（２）の健康なまちづくりに向けた環境整備というところで、誰もが気軽に出歩いたり、ウォーキングを楽しんだりすることということで書いてありますので、ぜひこういった水とみどりが豊かな環境を活かすということで、歩きたくなるウォーカブルな空間形成を進める上で、ベンチが必要になってくると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"経済的なところとか、教育の問題とか、それで本当に格差の中で、栄養の面とか、生活の面とか、かなり健康格差というのは厳然としてあると思うのですけれども、そういうのもデータとか、それをどう縮小していくのかという取組は、求められるのではないかという思いがしたのですが、そこのところは区としては、今回の計画の中ではどう捉えて、どう反映されているのかお伺いしたいと思います。","respondent":"若生健康課長","answer":"地域ごとに格差があるという、地域別の格差というのも縮小していこうということで、国全体ですとか、都の広域的なところで、なるべく地域格差が出ないようにというところの考え方も含めて、健康格差の縮小というところを国とか都ではうたっているのもありますので、そこについて。","voiceIndex":69,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"意見","question":"健康格差というのは、ＷＨＯからも健康格差の縮小というのが出されて、日本全体の国の計画の中にも入ったという経緯があるのではないかと思うのですけれども、貧困だったり、経済的な格差というものの中で、生活そのものが教育も含めて変わってくるので、そういうことによる格差というのができているという部分であると思うのです。これは意見として言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-027"}]},{"id":"topic-04","title":"「品川区がん対策推進計画（第二次）」素案にかかるパブリックコメントの実施","agenda":"「品川区がん対策推進計画（第二次）」素案にかかるパブリックコメントの実施","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"１８ページで、がん検診の実施状況のところなのですけれども、現在、バリウム検査とか内視鏡とかを含めて、１,２００円とか２,０００円とかという自己負担額があると思うのですが、最近品川区でも、ベーシックサービスという言葉が話題になっていて、こういった医療費とかも無償化の流れなのかなと思ったりするのですけれども、こういったところの現時点でのお考え、無償化への方針とか。","respondent":"若生健康課長","answer":"こちらは、策定委員会でもそういった議論があったところでございまして、この検診については、無償化ですとか、費用を軽減するというところも一つ、受診率の向上に資する可能性があるというところでは考えているところですが、現状、受診率を見ますと。","voiceIndex":77,"id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"意見","question":"有償か無償かの受診率の差というのはあまりないということと、がん検診を受診しなかった理由の５位というところが１１.６％、高いのか低いのかは、確かに検証の必要があるかなとは思ったりもするので、単純な区民負担という意味でも、個人的にはいいのかなとは思ったりしておりますので、ぜひこういったところも前向きに検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これも私は議事録を読ませていただきましたけれども、区としては、当面そういう無償化という方向では、現時点では考えておりませんというところですが、これは私たち共産党としては、予算修正も出させていただいたので、一応、どれぐらいかかるかというところでは計算はしたのですけれども、そこは全てのところで計算をされて、無償化でどれぐらいかかるのかというところでは計算されているのか。","respondent":"若生健康課長","answer":"がん検診を無償化した場合の試算については、私どものほうでも、仮に費用を無償化した場合のコストというところでは、内部では検討して調べて、算出はしております。","voiceIndex":81,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところと合わせると、国が求める五、六十％という目標というのは、品川区が掲げる目標としてはどれぐらいに相当するとか、そういう考え方というのがあるのか、それで、五、六十％と国が言っているところからしたら、区としてはどこまで引き上げることが必要だというのがあるのか、その辺のところも伺いたいと思います。","respondent":"若生健康課長","answer":"これは標本調査なので、全体の正確なものではないのですけれども、アンケート調査の中でも検診の受診率というところで言うと、大腸がんとか胃がんというのは３０％台、乳がん・子宮がんなどは４０％後半、肺がんが少し低いのですけれども、そういったところで一定程度。","voiceIndex":83,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。では、もう少し上げていくのが必要だという捉え方でいいのですね。分かりました。そういうところで、上げることが必要だということであれば、ぜひ無償化というのもご検討いただきたいと思います。そうすると、前立腺のＰＳＡとか喉頭がんとかは、なくす方向で考えているということの計画ということになるのか、その辺も伺いたいと思います。","respondent":"若生健康課長","answer":"こちらは、ご指摘あったとおり、指針外というと前立腺がんですとか、あるいは喉頭がん、それから胃がんで言うと、胃がんリスク検診、いわゆる胃がんのリスクを判別するために、血液検査によって、ピロリ菌の有無等を調べるといった検査なども含めて。","voiceIndex":85,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろ検討委員の先生方も、ＮＴＴの腫瘍内科部長だったりとか、昭和大学の腫瘍センター長だったりとか、医師会の先生方も入られていますし、そうそうたる方々が入られているわけですけれども、そういうところでは、専門家の先生方の意見というのは聞いていただきながら、慎重にご検討いただきたいということで、できれば続けていただきたいということで、私は要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-033"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私からは、５８ページ以降の目標の３のがん患者やその家族への支援を推進するという内容の、ＡＹＡ世代のがん患者の支援についての質疑をします。その１点だけで大丈夫です。","respondent":"若生健康課長","answer":"今後、ほかの区の状況ですとか、東京都の状況なども見据えながら、こちらについては、さらなる支援というところで何ができるかというところは検討してまいりたいと考えております。","voiceIndex":89,"id":"exchange-034"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回のものと比べさせていただいて、ここが追加されたというのは理解をしております。ぜひ情報提供、相談以外のところの金銭面の支援というところについても、改めて要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問","question":"４７ページの受動喫煙防止対策についてなのですけれども、受動喫煙防止の中で、例えば民間の公衆喫煙所などが対策としてというか、取組としてあるのかなと個人的に思うのですが、それが入っていなかったのですけれども、民間の公衆喫煙所はどのような位置づけというか、お考えでしょうか。","respondent":"若生健康課長","answer":"喫煙所というところでは、地域振興部で整備を進めておりますので、そことの連携というところで、計画には喫煙所という文言は出ていないにしても、現実としては連携を取りながら、受動喫煙防止対策を進めているところです。","voiceIndex":93,"id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"連携というところで一つ要望なのですけれども、品川区の場合、他区に比べて、民間の公衆喫煙所の助成率が１０分の１０ではない、３分の２とか５分の４だったりして、中央区、港区、文京区とか豊島区、その他もろもろで１０分の１０助成していて、設置数も多いというところがあるので、ぜひ１０分の１０を目指していただければという要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-037"}]},{"id":"topic-05","title":"「品川区自殺対策計画中間改定」素案にかかるパブリックコメントの実施","agenda":"「品川区自殺対策計画中間改定」素案にかかるパブリックコメントの実施","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"自殺対策推進検討委員会というのが庁内の委員ということなのですけれども、それから、自殺対策連絡協議会というのは学識経験者や関係機関等を交えた検討ということなのですが、ほかの２つはホームページで議事録とかも公開されていて、どんな資料が出されて、どんな議論がされたかというのがあったのですけれども、自殺対策の中間改定の策定については見当たらなかったのですが。","respondent":"五十嵐保健予防課長","answer":"委員会等の公表についてですが、現在、公表はさせていただいていないところになっております。今後、公表につきましては、検討させていただきたいと考えています。庁内の委員等のメンバーにつきましてですが、お手数ですが、素案の資料編になりますが、８６ページをご覧ください。","voiceIndex":102,"id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろとネット上で見たら、前の連絡協議会とかは公表されているのです。多分その資料の中に、先ほどの委員内の調査をした中身というのも、資料として出されたのかなと思うのですけれども、そういうのも含めて、これがどういう経過でどんな議論がされてというところが見えるような形に、ぜひしていただきたいと思います。それはぜひご検討いただきたいということで要望します。","respondent":"五十嵐保健予防課長","answer":"ＰＤＣＡサイクルに関しましては、こちらの計画でも実施していきたいと考えておりまして、こちらの計画の推進に当たりまして、庁内の検討委員会に諮りまして、進捗状況、取組状況の確認はする予定にしておりますが。","voiceIndex":104,"id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問","question":"資料の中で９ページのところなのですけれども、全国と品川区とを比べているのですが、男性のほうは全国に比べて、全て低めというところが出ていて、女性のところは、６０代が全国の２倍近かったり、それから２０代でも高いというのが、上の評価のところでも書かれているのですけれども、これの原因というのはどのように捉えられているのかということを伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"先ほどのプロファイルの部分でありましたように、男性のほうで勤務や職場の問題で亡くなっている方が多いという分析がされているところですが、なかなか職場の部分を繰り込むところは難しい部分もありますが、なるべく保健センターとも連携を取りまして。","voiceIndex":106,"id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、区としてはなかなか職場のところに、このような大きなところで勤務・経営ということで出されても、そこを自治体としてどうするのかというのはなかなか難しい部分があると思うのですけれども、そういうところで、ゲートキーパーということでおられて、大本のところでも、区の職員とかも含めてだと思うのですけれども、労働環境の、労働時間を短くするとか。","respondent":"五十嵐保健予防課長","answer":"民生委員にも実施させていただいておりまして、また区民の方に対しましては、現在はオンラインで見ていただけるような体制を整えているところですが、今後はゲートキーパーの研修の講座なども出張してできるようなものも考えていきたいと思ってあります。","voiceIndex":108,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"そういうところに、しかも１か月も日にちがないという状況だと、なかなかこのパブリックコメントを書きたくても書くのが難しい状況になると思うのですけれども、これはもう少し長くしていただくとか、健康プランと先ほどのがんの計画とかと併せて来年までという形になれば、もう少しゆとりを持って書けるのではないかと思うのですけれども、なぜこんなに短く、この忙しいときにされたのか。","respondent":"五十嵐保健予防課長","answer":"ゲートキーパー養成研修につきましては、昨年度につきましては９９２名の方に受講していただいている状況になってあります。","voiceIndex":110,"id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問・要望","question":"パブリックコメントは、できるだけ１か月は期間を取っていただきたいということで、今後に向けてということになってしまうと思うのですけれども、要望はさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"品川区の３つの重点施策の中でお伺いしたいのですけれども、子ども・若者、勤務問題というところと、女性の自殺対策のさらなる推進とあるのですが、品川区でも男性のほうが、基本的に自殺者数は女性よりもずっと多いというところで、なぜ女性に重点施策でフォーカスを当てたのかということ、自殺者数でははかれないようなところで、もし何か理由があればお教えいただきたいです。","respondent":"五十嵐保健予防課長","answer":"全体的に男性が多いのは承知しているところですが、別に男性の対策をやらないというわけではなくて、男性の対策もやりつつ、女性に少し力を入れようかなということで、３つの重点施策として入れさせていただいているものになってあります。","voiceIndex":114,"id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"提案","question":"次ですけれども、これはこの前の決算特別委員会でも少しお話させていただいたところなのですが、自殺死亡率の目標値なのですけれども、令和８年度は１１.５を掲げているというところで、自殺というのは、起きてしまったらもう取り返しがつかないといいますか、例えば喫煙率を下げるとか、肥満率を下げるとか、がんの受診率を上げるとかという目標値と違って、それが起きてしまったら。","respondent":"五十嵐保健予防課長","answer":"国も大綱を変えている部分ではありますが、前回の大綱と同じ値で、平成２７年と比べて３０％以下に減少するということで、令和８年までにその値にするという目標をそのまま掲げているところです。","voiceIndex":116,"id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問","question":"おっしゃることは非常によく分かります。ちょっとしたことで上振れしたりということがあると思うので、２年移動平均とかという感じで、そういうデータもあると、現在の状況がつかみやすいのかなと思うのですけれども、その辺はいかがでしょうか。データの出し方について。","respondent":"五十嵐保健予防課長","answer":"計画の数値目標についてですが、なかなか分母が少ない分、１人２人変わるだけで、ものすごく数が変わってしまうという委員のご指摘のとおりでございまして、計画の目標の自殺率としまして、最初の国が出している値ですが、平成２５年から２９年の値の平均を取りまして。","voiceIndex":118,"id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"目標値もそうなのですけれども、実際に実数とかも、ぽんと上がったり下がったりということで、良いと思うので、その辺が少し分かるようなデータの出し方、目標値だけではなくて、実数のほうもそのような工夫をしていただけると、より状況把握がしやすいと思いますので、その辺は要望としてお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-047"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"超短時間雇用についてなのですけれども、実績、２８社登録していただいて、希望者が３５人ということで、非常にいいかなと思うのですけれども、就労者３名ということで、具体的にどのような業務に就かれているか、もしお分かりになれば教えてください。","respondent":"松山障害者支援課長","answer":"お一人目が施設の清掃・下膳・消毒作業です。１日２時間、週３日勤務です。お二人目はオフィストイレ清掃、１日２時間で週２日勤務、それから３人目の方は、請求書支払い処理、データベース作成、１日３時間で週４日勤務です。","voiceIndex":126,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"確認","question":"今の超短時間なのですけれども、これは、賃金というのは最低賃金が保障されるということでよかったのか、確認させてください。","respondent":"松山障害者支援課長","answer":"２つ目ですけれども、企業についてですが、主に区内企業がほとんどです。ＣＳＲ企業を中心に、また商店街等も、各店舗に出向いていってご説明をしているという状況です。","voiceIndex":132,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで言えば、区の業務の中でも、品川区役所の中の、区役所本庁舎だけではないにしても、区役所関係の仕事の中でもそのようなものが切り出しできるのかなという思いがしているのですけれども、そこの取組と、それから、障害者の法定雇用率が、今品川区でどのような状況になっているのか、あと、社会福祉法人とかでも、そういう雇用率とか。","respondent":"松山障害者支援課長","answer":"区内の中の超短時間雇用を進めることや、法定雇用率を含めて、私どもの所管ではなくて別の所管になりますので、今お答えすることは、申し訳ありませんが、できません。","voiceIndex":134,"id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問","question":"それであれば、多分すごくたくさんの量を備蓄していて、それを常に回していくと、今年が１,０００万円増えたというか、その１,０００万円増えたのが、恒常的にずっと増えるぐらいのことにはならないのかなと思ったのですけれども、今までは防災用の毛布のクリーニングというのは引き受けていなかったのが、新たに引き受けて、こうやって収入が増えたということなのか、そこのところも教えてください。","respondent":"松山障害者支援課長","answer":"もちろん、防災の毛布なので、どれぐらいの頻度というのは防災課で所管しているものですので、できるだけ優先調達を使っていただくように促してまいります。","voiceIndex":136,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6919#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":49940,"voices":146}},{"id":"r06-20241126-8","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"建設委員会","time":"午前１０時０６分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年１月区営住宅入居者募集","agenda":"令和７年１月区営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この間の募集戸数と応募倍率を伺いたいと思います。それで、この間の実績が分かれば、入れた人の人数を伺いたいと思います。","respondent":"川原住宅課長","answer":"前回の令和６年７月につきましては、１２名の募集に対し３６０件の応募でございました。倍率は３０.０倍です。昨年度、令和５年につきましては年に２回開催してございまして、最新のものからですと令和６年１月が、９名の募集に対し３３２件の応募、倍率が３６.８倍です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても、この増設を進めていっていただきたいと思います。今、郵便事情なども大変になっておりますので戻していただきたいと思うのですが、いかがでしょうかというのと、あと、区営住宅の入居の際に必要な連帯保証人を、都営住宅ではなくしているというところで、区営住宅でもなくすべきだと思いますけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"約１０％の方が保証会社を利用して、残りの９０％の方は連帯保証人を引き続きご利用いただいているところですので、また、保証会社もしくは保証人の設置不可を理由に入居を断念したという方は今までいらっしゃらない状況ですので、現在のところ廃止する予定はございませんが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"連帯保証人のところは、今、保証会社を使っている方が１０％ということで、その割合も見ていきたいということでしたが、保証会社を利用している人が増えれば、連帯保証人が不要になっていくということなのか、その割合を見ていく視点というのですか、よく分からなかったので伺いたいと思います。","respondent":"川原住宅課長","answer":"利用者数の割合というところは、検証の一つとして注視していきたいと考えているところですが、区ではこれまでも、なかなか家賃を継続して払うのが難しいという方には分割納付や、区民の方に可能な方法でのお支払いというところをお願いしていますので、プラス、１つ。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたところを鑑みて、都営住宅では連帯保証人をなくしたと。私が言っているのは、保証人自体、つける必要がないのではないか、つけないようにするべきではないかということで、保証会社もやめるべきだということなのです。保証会社は、実際やれば負担も増えますし、そこが入居に向けてのハードルになり得るということで、なくすべきだということで求めているのですけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"生活が困窮されている方が多いですので、そういった方に対しては通常の使用料よりもさらに減額の申請書を出していただいて、その方に適した減免申請の内容にのっとって、低額な使用料をお支払いいただいているところですので、そこの債権管理を担っている以上、しっかりと。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"使用料を払ってもらうということは必要だと思いますけれども、その中で、やはり保証人というのが入居のハードルになるということがあってはならないと思いますので、そこはなくしていくようにしていっていただきたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"建設委員会でも述べてきましたけれども、先ほども応募倍率の質疑がありましたが、毎回そういう質疑があるわけですから、あらかじめ資料に記載したらどうかという指摘をさせていただいて、今回載っていないわけですけれども、その理由を伺いたいのと、やはりそういう質疑があるわけですから、入居募集についての報告の中で。","respondent":"川原住宅課長","answer":"２点目の、この倍率に基づいて、増設についての区の考えはですが、現時点におきましては、増設という考えはございませんが、引き続き、こういった入居に対してニーズがあるというところは把握していますので、特に前回の応募につきましても、この応募の方々の層というのは。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"その理由を伺いたいと思います。私はやはり委員会の資料というのは、質疑を充実させるといいますか、深掘りしていくといいますか、特に毎回、質問が上がっているわけですから。なぜ広報の枠内でしか委員会資料を作れないのか。そこを伺いたいと思うのです。私は高いと思うので、この倍率からも、区営住宅の増設を考えるべきだと私は思うのですけれども、区としても、３０倍、５０倍となっている。","respondent":"川原住宅課長","answer":"やはり、民間の賃貸住宅への住替えが難しくなる理由としては、特に高齢者の方については、断られてしまう、更新ができなくなってしまったというようなご意見を頂いているところですので、セーフティーネット住宅といった。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"そんなに強く拒むものでもないと思うのです。前回も言いましたけれども、そういう質問があるだろうから、課長も手元にそういう資料を用意して、正確な数字を答弁できるように準備もしているわけですから、ぜひ持ち帰って検討して、改めて委員会資料に載せることを要望します。ぜひ持ち帰って、もう一度協議していただきたいと要望したいと思います。","respondent":"川原住宅課長","answer":"万が一、亡くなってしまった場合に、身寄りのない方というのは当然、残置物をお引取りになる方もいらっしゃらない場合がありますので、そういった場合には、区の職員のほうで調査をさせていただいて、戸籍等から親族の方にご連絡を差し上げて。","voiceIndex":18,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"ありがとうございました。残置物のことなのです。職員の方は大変苦労されていると思いますけれども、その場合は、もちろん生活保護を利用されている方も中にはいらっしゃるし、生活保護を利用されていない方もいらっしゃるし、そこの利用の有無は一旦置いておいて、親族に連絡して、引き取ることを拒まれた場合はどういう対応になるのか、最後に伺いたいと思います。","respondent":"川原住宅課長","answer":"引取りを親族の方が拒まれた場合の対応ですが、ご遺体の引取り手がいないというところで区が判断し、行旅死亡人として適切に遺体の措置をするような形です。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"入居の資格条件なのですけれども、いわゆる公営と言われるものについては、所得で一般と特別の大きな区分があったり、所得階層などがあるのですよね。所得はさほど高くなくとも、なかなか物件が見つからなくて、割高というか、そういう物件にどうしても住まざるを得ない方もいらっしゃると思うのですけれども、そういう条件の人というのは困窮しているという条件に当てはまるのですか。","respondent":"川原住宅課長","answer":"その方の所得の種類によって計算が変わってくるような形になるのですけれども、例えば単身の方の場合は、所得の金額でいうと約１９０万円未満、１８９万６,０００円以内という形になってあります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"今ご答弁いただいたというのは確認の話だったと思うのですけれども、そういう中で支出の部分について見ていくという考え方については、都営も含めて、全国的にその辺の見方というはあるのでしょうか。そこはどうなのか。支出のところで見る。この辺の考え方というふうにつながってくるのかなと思うのです。まさに区内に住まいがあるわけですから、そういう部分での何か手だても一方ではあるわけです。","respondent":"川原住宅課長","answer":"決まらなかった方への次の手だてというところでは、ここは区がしっかりとハード面の施策としてやっていかなければいけないのが、区内では現在０棟なのですけれども、セーフティーネット住宅や、来年度秋に。","voiceIndex":24,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"３８０万円とか４００万円前半とか言われている中で、そういう所得などに限らず、いろいろな所得階層があっても品川区に住み続けられるような支援というのが必要かなというところでの問いだったのですけれども、また違う場所でいろいろ勉強しながら、品川区の住まい政策の関係を求めていきたいと思います。確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"}]},{"id":"topic-02","title":"戸越公園駅北地区における再開発事業に係る事業者による近隣説明会の開催","agenda":"戸越公園駅北地区における再開発事業に係る事業者による近隣説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、説明会を北地区で行うということですけれども、裏の対象範囲を見ますと、２Ｈが約２２０ｍということで、つまりは建物の高さが大体１１０ｍになるのかなと思いますけれども、この建物の計画概要を伺いたいと思います。それと、今後の予定のところでいろいろ、都市計画の説明会など、都市計画審議会も含めて書いてありますが、大体いつ頃になるのかを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"仮に順調に進むとした場合ですが、都市計画法第１６条に基づく説明会は、年明けの１月頃を予定しておりまして、その後の第１７条に基づく説明会は３月頃の開催を見込んでいるところです。その後、区の都市計画審議会を経まして、来年の春頃の都市計画決定を見込んでいるものです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"計画概要については、住宅、あと低層階が店舗と駐車場ということなので、今、造られている１９番地区より少し大きなマンションが建つということになるのかなと思うのですが、分かれば階数を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"北側の区道のお話ということでよろしいかと思っているのですけれども、区道を巻き込んだ検討範囲となっていることですけれども、現状、上位計画では、戸越公園駅北地区を含むエリアでは、計画範囲の段差というところにつきましては、先ほど申したとおり。","voiceIndex":33,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"対象範囲については、話をした方が入ったという話でしたが、そうなのです。準備組合から説明を受けていれば、どういう道路形状になるのかも含めて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"北地区につきましては、現在、準備組合により、商店街機能の維持および活性化も含めまして、まちづくりの検討が進められておりまして、検討の中で駅前広場の整備位置を踏まえて、当該区道の在り方を検討しているものと認識しています。","voiceIndex":35,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"準備組合で検討されているということなのですが、区としては聞いて説明を受けていないのかどうか。というか、区道に関することですから、説明を聞いていないわけはないと思うのですけれども、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区道の検討状況につきましては、まずは主体となります準備組合が、関係道路管理者等と協議している中で、まちづくり立体化担当としてもしっかりとそこはサポートしています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"今、敷地内通路にしていくということだと答弁がありましたが、あと車は敷地内通路を通れるのかどうか、自転車は通れるのかどうかというのを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"現状といたしまして、私のほうで聞いてありますのは、車は通れません。車は将来的には駅前広場を迂回していただくような形で考えてございまして、自転車につきましては現在検討中と聞いてあります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"自転車は検討中だということで、ぜひ通れるようにしていただきたいと思いますけれども、改めて伺いたいと思います。それと、やはり今回のこの計画が１１０ｍの高さというところでは、やはりこの周辺はそんなに高い建物はない。駅前にできたものだけということで、そうした中では、やはり町並みにそぐわないと私は思うということは表明しておきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今、自転車に対するご要望という形でお話しいただきましたが、この件に関しましては私のほうで準備組合にお伝えしますが、現状といたしましては歩行者専用を念頭に置いているものと聞いてあります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"新たな再開発が、また始められようとしていることだと思います。そのことをぜひ、そういった意見が建設委員会であったということを準備組合にも伝えていただきたいと思いますが、いかがでしょうか。本当に不誠実だと思います。準備組合から説明を受けていると思いますので、当日の説明内容の事業概要等について、一体何が説明されるのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の、再開発事業をやめるべきだと準備組合に伝えるというお話ですけれども、区では、市街地再開発事業は地域の主体で行われているものでありまして、地域の権利者の意向に沿ってしっかりと進められているものですので、一定。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、やめるべきということを伝えてほしいと質問したのです。その答弁が「支援する」というのは、どういうことですか。「そういう意見がありました」と伝えることもできないのですか。それと、事業計画案がどういう計画かと質問いたしました。その中身が、高さ、用途、住宅。それで私に、この計画の何を分かれというのですか。もう少し誠実に答えていただきたいと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"概要等につきましては、先ほど申したとおり、建物の概要と高さの話、住宅戸数の話、また上位計画等との整合性や当地区の課題、それに対してこの再開発で何をやっていくかというところのもろもろの概要をお伝えするものと考えているところです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"準備組合には、やめてほしいと意見があったことは伝えるということですので、しっかり伝えていただきたいと思います。これは、だって条例に基づいて示すわけですから、日陰の影響、あと総事業費、補助金。前回も言いましたけれども、当日出席すれば示されるものの概要ぐらい、委員会に説明するのが筋だと改めて思いますが、委員会資料についても大幅に改善していただきたいと思いますが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"このため、現時点として、資料としてお示しすることができなかったものです。議会に対しましては、今後予定されております都市計画手続等に関する報告などの機会を捉えまして、しっかりと示せるように検討してまいりたいと考えているところです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は先ほどそう指摘させていただいて、どういう何を造るのかという質問をさせていただいたところです。区も、きちんとまとまってからこういう説明会をやりなさいというぐらい言うべきだと思いますが、いかがでしょうかという点です。この辺のことは、よく決算・予算特別委員会でも議論がありますけれども、少なくとも新たなタワーマンションはやめるべきだと、改めて求めておきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"建設委員会の日程、議会にお示しする日程の関係というお話でございましたが、今回の件は建設委員会の日程と相手方の説明会の日程が少し離れてしまったということが、まず１つ、要因ではありますので、今後はそこの点につきましても調整させていただければと考えています。","voiceIndex":50,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"離れてしまったといいますが、議会は議決機関なのです。再開発に賛成・反対は、私は反対ですけれども、意見はそれぞれの主張ですから、尊重していただきたい。議決機関として、我々は切磋琢磨、意見をぶつけ合ってやっているわけだから、きちんと日程をよく見ろと、準備組合に伝えていただきたい。区もそういう答弁はよくないと私は思いますけれども、最後にいかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"今回、説明会につきましては、繰り返しになりますけれども、事業者主体で行われるものでございまして、事業者の日程の関係で、今回示せるものをしっかりと建設委員会にお示ししたつもりですので、ご理解いただければと思います。","voiceIndex":52,"id":"exchange-023"}]},{"id":"topic-03","title":"西五反田公園改修工事","agenda":"西五反田公園改修工事","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"これはそのとおりだと考えていますけれども、ここまで長期的になってくると、やはり工事の、何というのですか、品川区は予算がたくさんあるから大丈夫だとおっしゃるかもしれないけれども、さすがに今の円安と物価高の長さを見ると、やはり様々、工事をする部隊も、工事を開始する時期を遅らせるとか、工事を開始する時期の変更を検討するとか、そういうこともあり得るのか、いやいや。","respondent":"大友公園課長","answer":"それを踏まえて、実施していく工事の計画についても、年次計画、またもっと長期の計画等々を考えて実施しているところではありますけれども、その中において、実施時期等々はどこが適切なのか、何の工事が緊急なのかというところも踏まえて、予算のフレームワーク。","voiceIndex":58,"id":"exchange-024"}]},{"id":"topic-04","title":"第二戸越幹線整備工事（北品川特殊人孔等整備）","agenda":"第二戸越幹線整備工事（北品川特殊人孔等整備）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"理解を深めるためにというところで、河積阻害率という言葉が出てきたのですけれども、どういうものなのか、それが増えるとどういう影響があるのかというところを伺いたいのと、あと温度ひび割れがどういうものなのか、それがあるとどういう影響があるのかというところを伺いたいと思います。インフレスライドで増額する金額がどのぐらいになるのかというのを伺いたいと思います。","respondent":"北原河川下水道課長","answer":"河積阻害についてですけれども、河川は雨が降ったときに水を流すという役割を持っていまして、仮設物を設置すると、川の断面が減ることによって浸水が発生する懸念もあるということで、できるだけそれをなくすようにという形で検討しているものです。","voiceIndex":64,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"言葉のご説明をありがとうございました。そういうこともあるのかなと思いましたけれども、これが、標準仕様書に基づいてやった中でそういうのが発生したということでいくと、標準仕様書の見直しというのも必要なのかなと思ったのですが、そういったことを検討されているのかどうか、伺いたいと思います。計画段階で、しっかり計画をしてやることができなかったのかなと思うのですが、いかがでしょうか。","respondent":"北原河川下水道課長","answer":"ただ一方で、今ご指摘のありましたような、変更等が生じる、工期も延びていくということが当然とは我々も考えておりませんので、また今後、工期が延びたりというお話もさせていただかなければならない時期も来ますけれども、その際にはきちんと精査いたしまして。","voiceIndex":66,"id":"exchange-026"}]},{"id":"topic-05","title":"勝島地区雨水管整備工事","agenda":"勝島地区雨水管整備工事","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"勝島地区の雨水管整備をする目的というのですか、近年、浸水などが近くであったのかどうかというところも含めて伺いたいのと、あと、工程表です。今回、１工区ということで、令和８年度の半ばまでという期間ですけれども、その後、第２工区、第３工区が予定されているということですかね。この工程が分からない理由というのですか、今後の見通しというのですか、そこを伺いたいと思います。","respondent":"北原河川下水道課長","answer":"近年の浸水実績といたしましては、例えば今年、令和６年８月２１日に大雨が降った際も、道路冠水が大井競馬場の北門付近で発生しておりまして、そこについては過去にも浸水が発生しているということで、在来管の能力が足りないということで発生しているものと認識しています。","voiceIndex":72,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"以前にも道路の冠水があったということで、必要性は分かったのですけれども、今回の施工は、これだと内径１.２ｍの雨水管が、大体２６７ｍですか、設置されるというところで、もう冠水はしなくなるという計画だとは思うのですけれども、そこの確認をさせていただきたいと思います。","respondent":"北原河川下水道課長","answer":"一方で、今回の管に水を取り込むための、上部にある下水道管をどう取水していくかというところを現在検討しておりまして、そちらについても速やかに実施していくことで効果が発現するものになります。","voiceIndex":74,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"直近では令和６年８月２１日の大雨で道路冠水があったと。確認ですけれども、当時の大雨と同規模程度であれば、整備が終わった際には被害を防げるという想定なのか、そこを確認させていただきたいと思います。少なくとも被害の軽減ということなので、同規模程度の大雨では対応できるのかということと、今後、雨が強くなっていくことも考えられるので、それについてもご見解を伺いたいと思います。","respondent":"北原河川下水道課長","answer":"こちらの雨水管の整備水準に関しましては、まず時間５０mmに対応する管という形にはなってあります。","voiceIndex":76,"id":"exchange-029"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうか。今、様々実施はしてきているわけですけれども、コミュニティバスの候補ルートが２ルート、そのまま残されているという状況ですけれども、荏原ルートについては、ＡＩオンデマンド交通の実証実験をやっていくということになりましたが、今、大崎ルートはまだ何も実施されるというのがないという状況で、ぜひコミバスの運行を進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"コミュニティバスの大崎ルートにつきましては、これまでコミュニティバスについては、今年度までの試行運行の実績を基に来年度検討するということになっておりまして、それを踏まえて他のルートについて考えていくということで、今回。","voiceIndex":85,"id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"コミバスのルート実施に向けては、ＡＩオンデマンドの結果も踏まえてということでした。これは強く要望しておきたいと思います。やはり、今回示されたルートの中では、大崎ルートだけが区役所にも行き、あとは駅にも寄って行くというルートになっておりますので、利便性は高いかと思いますので、ぜひ実施していっていただきたいと思いますが、改めて伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"大崎ルートについても、交通上の課題のある地区という認識は、区も抱いております。先ほど申し上げましたとおり、コミュニティバスの状況とＡＩオンデマンド交通の成果を踏まえて、どのようなことができるか考えてまいりたいと考えています。","voiceIndex":87,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"事故も起こっているということもありますし、乗っている人自身も守るものが何もないというものですから危険があると思いますので、そこはしっかりと安全対策を進めていただきたい。それで、以前には、点滅していない、６km以下の速度になっていない状態で歩道を走っているという姿も見ましたので、ぜひそこは安全対策をしっかり行っていただきたいと思うのですけれども、いかがでしょうか。","respondent":"山下交通安全担当課長","answer":"乗っている方は、免許を持っている方もいれば、持っていない方もいらっしゃいますので、そういった皆様が安全に乗れるように、またそのルールを知ってもらえるように、区としましても広報・啓発を実施してまいりたいと思いますし。","voiceIndex":89,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。私は、ＡＩオンデマンド交通について伺いたいと思います。そこで、まず幾つの地区で検討されたのか。具体的には、資料に書いてあるとおり、昔は交通不便地域と言っていたけれども、今は交通サービス圏域外になっている西大井五丁目、六丁目、四丁目、大井七丁目と言えばよいのでしょうか。荏原地区を選定するに当たっての検討経過をご説明いただきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"選定の経緯ですが、コミュニティバス導入計画の中で候補ルートとして挙げさせていただいている３地区について検討させていただきまして、その中で、大崎地区、荏原地区、西大井地区を含めて様々検討した結果です。","voiceIndex":91,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ということは、西大井地区も、正確には西大井駅から大森駅のバスは開通したものの、以前の名前だと西大井循環ルートと言われるところが解決していないというところなのですけれども、行政区といいますか、いわゆる大井第三地域センター管内と言えば分かりやすいと思うのです。ぜひ進めていただきたいと思っているのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"ただし、循環ルートについては、まだ解決されていない課題だと認識しておりますので、どのようなことができるかというのは考えていきたいと考えています。","voiceIndex":93,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"循環ルートについては、どのように解決していくのか考えていきたいという、ここが一歩も先に進まないというところなのです。そこをご説明いただきたいのです。ぜひ少し踏み込んで、先の見通しが持てるようにご答弁いただきたいのと、ここの地域の課題についてもどう考えているのかも、もう少し深掘りしたいと思うのですけれども、質問の趣旨は伝わっていると思いますけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"どのような方針で解決するかですが、コミュニティバスの検討当時におきましては、様々、警察との協議等で、やはり交通規制上、難しいという話がありましたが、一方で新しいモビリティー、バスを前提としない新しい形態が近年少しずつ出てきていますので。","voiceIndex":95,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"その範囲で、今、検討しているということは分かりました。この後も報告会のことがありますけれども、行政視察でＡＩオンデマンド交通の説明をよく伺いまして、これなのだと思ったのです。ぜひ、交通不便地域を解消するために、大井第三地区、西大井でのオンデマンド交通の運行を求めたいと思いますが、最後に一言ご答弁だけ頂きたいと思います。","respondent":"櫻木地域交通政策課長","answer":"荏原地区での実証運行の結果を見て、ほかの地域にどのような展開ができるのか、できないのか、品川区にふさわしいのかというところを見定めながら、一方で交通課題解決に向けては引き続き努力していきたいと考えております。","voiceIndex":97,"id":"exchange-036"},{"speaker":"澤田委員","kind":"質問・要望","question":"私がお伺いしたいのは、コミュニティバスなのですけれども、利用者増と収支率の改善のために運行改善策を引き続き検討していくとあるのですけれども、現在、例えば周知方法など具体的な改善策というのはどのようなことをお考えなのか、あれば教えていただきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今後も来年にかけて、近隣の方に利用者連絡会という形で周知をポスティング等で行わせていただきますので、引き続きそのような形で利用促進を図っていきたいと考えています。","voiceIndex":99,"id":"exchange-037"},{"speaker":"澤田委員","kind":"質問","question":"ほかの質問なのですけれども、続きましてなのですが、グリーンスローモビリティで、こちらも私も試乗会に参加させていただきまして、風も心地よく、ふだん自転車で見ている景色とは全く違って、大変楽しく調査させていただきました。アンケートが行われていたと思うのですけれども、どのようなお声があったのか、もしあれば教えてください。","respondent":"櫻木地域交通政策課長","answer":"今後につきましては、これからまた地域に伺って、ご意見、あとは利用者アンケートの集計結果を見て、来年度に向けてどのようなことができるのかというのは検討させていただければと考えています。","voiceIndex":101,"id":"exchange-038"},{"speaker":"澤田委員","kind":"質問・要望","question":"電動キックボードの危険運転は、交通事故発生状況が区内でも１２件となっていて、私自身も危ないと思う運転をよく見かけるのですけれども、今後の対策として、登録時に安全な乗り方を教示するとありますけれども、具体的には、例えば冊子を配ったり、どのような形でお伝えするのかということと、また電動キックボード個人所有以外の方の利用者については、多分、ＳＮＳや各種メディア等を通じて。","respondent":"山下交通安全担当課長","answer":"基本的には、インターネットや、そういったところでも周知されているところなのですけれども、やはり知らないところを補完するといいますか、また質問を受けた場合にはそれに対して回答するとか、そういうことを一つ一つやっていくことによって。","voiceIndex":103,"id":"exchange-039"},{"speaker":"澤田委員","kind":"質問・要望","question":"２点目の、Ｌｕｕｐをはじめ、会社との連携、企業との連携というところで、特にそちらの方向ではなくて、情報発信を区として主にやっていらっしゃるということでしたけれども、発信していく中で、やはり運転の仕方だったり、車などを運転していない方の電動キックボードの乗り方というのは本当に危ないと思っていて、後ろも振り返らずに道路に入っていってしまったり、そういうことがあって本当に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-040"},{"speaker":"つる委員","kind":"質問","question":"最初に１つ、まず教えてください。大人の２人乗りは法律違反になりますか。","respondent":"山下交通安全担当課長","answer":"これは、電動キックボードの２人乗りということでよろしいでしょうか。","voiceIndex":106,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"となると、ラストワンマイルとか、いろいろな言い方があって、快適な移動ということで、この資料にも頂いているわけですけれども、そうすると、もう本当に細部というか、ドア・ツー・ドアで考えたときに、最後の本当にワンマイルどころか、さらに小さい単位で見た移動というのですか。もし分かれば教えていただきたいのと、そういう検討が区内ではあるかどうか教えてください。","respondent":"櫻木地域交通政策課長","answer":"事業としてシルバーカー等をレンタルしているようなところということで、ポートを設けてというような事業については、申し訳ございませんが私は把握してございません。","voiceIndex":110,"id":"exchange-042"},{"speaker":"つる委員","kind":"質問","question":"結局、シルバーカーにしても、ＷＨＩＬＬなど、いろいろな商品名があると思うのですけれども、ポートをつくれば、結局そのポートまでの移動をどうするのだという話になると思うので、なかなかそこはジレンマだと思うのですけれども、超小型モビリティーなどというのは、２人乗りができるものもあるのです。そこの部分というのは、どういう検討などをされているのか教えてください。","respondent":"櫻木地域交通政策課長","answer":"ただ、それが公共交通という枠組みなのか、いわゆる福祉的な分野で対応するのかというところは、様々連携しながら考えていきたいと考えています。","voiceIndex":112,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"現状をありがとうあります。ここにも種類に「あらゆる人」とあるわけですから、これはもう、言葉尻になってしまうといけないのですけれども、もう本当に、まさにそこが「あらゆる人」の課題であるということで認識いただいているので、先ほど私もお伝えしましたけれども、より福祉的なところでそこまで行くと。この辺の予約のありようも含めて教えてください。","respondent":"櫻木地域交通政策課長","answer":"前提としまして、現在まだ、利用するアプリ、システム等が定まっていない状況ですので、一般論でしかお答えできないところではあるのですが、一般的なアプリケーションでいうと、時刻予約という機能がありますので、少し前に予約していただいて。","voiceIndex":114,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、当然それで行って帰ってというイメージの方もいらっしゃるでしょうし、違う手段や、歩きも含めてですけれども、いろいろピースごとに、地域交通を展開いただいていると思うのですけれども、全体イメージというのでしょうか、行きはこれを使っても帰りは歩いてみるとか、それは健康によいですよなど、いろいろな健康部門の所管などと連携しながら、全体のいろいろな仕組み、それこそ健康ポイントなど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-045"},{"speaker":"えのした副委員長","kind":"質問","question":"様々ご説明ありがとうあります。私からはシェアサイクルについてお尋ねします。荏原地区は、下にもありますけれども、２３区のうち１５区が広域連携し、区をまたいだ利用も可能となっているということで、お隣は区境として目黒区や世田谷区があると思うので、やはりそちらの配置が多くなることによって、また利便性も向上するのかなと考えていますが、そちらはいかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"それと、荏原地区にポートが少ないという、推測にはなってしまうのですが、比較的ポートが設置されているのは、やはり商業施設であったり、あとは比較的空間に余裕のあるところに設置が進みやすいのかなというところで、荏原地区に関しては住宅が多いというところで。","voiceIndex":117,"id":"exchange-046"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"それと、先日夕方、１７時くらいまで指導されているのを拝見して、２年前ぐらいは、たしか大きな道路、中原街道の交差点や補助第２６号線など、そのようなところでやられていたのが、最近ではヒヤリ・ハットというのですか、地域の事故が起こりやすい場所で指導しているところを拝見していて、非常によい取組だなと実感しております。","respondent":"山下交通安全担当課長","answer":"実績につきましては、現場において、これは自転車に限るのですけれども、現場で例えば逆行、反対側を走ってきている自転車や、歩道で歩行者を考えないでスピードを出している方、あとはイヤホンや携帯電話を使用しながら走行している方々、そういった方々に指導・啓発しながら。","voiceIndex":119,"id":"exchange-047"},{"speaker":"えのした副委員長","kind":"確認","question":"確認が取れました。私も自転車安全利用指導員もネットで検索していたら、やはり募集している警備会社のサイトにつながったのですけれども、そこで資格を取るような話が載っていなかったので、今そのお話を聞けてすごく安心しております。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6917#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":44010,"voices":132}},{"id":"r06-20241126-9","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"文教委員会","time":"午前１０時０７分～午後 ４時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０６号議案、学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例、この２議案","agenda":"第１０６号議案、学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例、この２議案","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今回の改正の対象となる学校教育職員の方の給与改正について、確認をします。あわせて、都費職員の給与改正は東京都のほうで対応するのかと思いますが、その辺の状況、今回のタイミングと都のタイミングが合っているのかどうか、そこを確認させていただきたいです。","respondent":"中谷指導課長","answer":"２つご質問をいただきました。今回の対象の方ということですけれども、ご説明させていただいた学校教育職員につきましては、品川区の固有教員が対象となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問","question":"同時進行であり、内容もその改定率も同じということで受け止めていいのですか。はい、分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問","question":"一般のいわゆる事務系職員の方は、この改定で年間２０数万円上がるとたしか本会議で説明がありました。今お話があったいわゆる固有教員の方とか幼稚園教諭の方々は、平均という考え方なのでしょうか、年間で幾らぐらいプラスになるのかということがもし分かればお願いします。","respondent":"中谷指導課長","answer":"管理職のほうになりますと、そこまでの増額というところまではいかないのですが、今回の改定につきましては、全級・全号給で上がるということでご承知いただければと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、それが１２か月と、いわゆる賞与を計算すると、２０万円ぐらいのプラスという認識でよろしいでしょうか。","respondent":"中谷指導課長","answer":"今申し上げた月額に、掛ける１２、プラス、今改定が反映されている期末手当、勤勉手当、これがプラスアルファになりますので、初任の方で考えますと２０万円以上アップになるのかと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"せらく委員","kind":"質問","question":"賛成します。でも、少し以前との違いについて述べてもよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"せらく委員","kind":"意見","question":"これまで維新としては身を切る改革を行っておりまして、安定した職業である公務員の皆様の給料の引上げには反対してまいりました。品川区では、森澤区長の下、区長自身も身を切って進めていらっしゃるのと、行財政改革を行って改革を進めているという判断で、今回党議規則もないという会派での判断をいたしまして、今回の議案は賛成したいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-006"}]},{"id":"topic-02","title":"令和６年度第２回家庭教育講演会","agenda":"令和６年度第２回家庭教育講演会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"オンライン配信ということなのですが、２０日間ぐらいの期間がありますけれども、どれぐらいの方がこの配信をご覧になったという、最終的な結果というか、効果というか、そういうものも含めて分かるような形になっているのか教えてください。","respondent":"舩木庶務課長","answer":"は周知をどこまでしっかりと行き届かせるかということかと思います。この辺りは、先ほど申し上げましたように学校、そしてＰＴＡ等の学校支援団体を通じまして、児童・生徒の保護者に行き届くように、しっかりと可能な限り努めてまいりたいと考えております。","voiceIndex":35,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"分かりました。先ほどコロナ禍においては現在の２倍ぐらいの視聴数があって、それが落ちついてからは在宅期間もあまりないだろうから、４００回ぐらいになるということでした。今回、企画としてはとてもいい内容だと思いますし、多くの人に見ていただきたいのですが、どれぐらいの方に見ていただきたいという目標、思いはあるのでしょうか。","respondent":"舩木庶務課長","answer":"可能な限り多くの方に見てもらいたいというところがありますので、学校、そして学校の関係者の方のお力をお借りして、周知が行き届くような形で努めてまいりたいと考えています。","voiceIndex":39,"id":"exchange-008"},{"speaker":"田中委員","kind":"確認","question":"改めてお聞きします。今回の講演の対象は、いわゆる子どもを持つ保護者なのか、あるいはご家族全員で共有してくださいという呼びかけもあるように、児童・生徒の方にも当然見てもらいたいということなのでしょうけれども、どちらかというと、どちらを対象とされているのでしょうか。確認です。","respondent":"舩木庶務課長","answer":"ターゲットは保護者の方です。ただ、お子様が見られても気づきになるような内容もあります。第一義的には保護者の方を対象としていますが、ぜひご家庭で、皆さんで見ていただけるように、ご案内をしているものです。","voiceIndex":42,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな学校の取組の中には、地域の方から学ぶ事業というか、取組もあるかと思います。既にやっていらっしゃる部分もあるのかもしれませんけれども、こういう講演会はすばらしいものだと思っていますし、より発展させる意味でも、いろいろな策を講じていただきたいと思うのですが、いかがでしょうか。","respondent":"舩木庶務課長、丸谷教育総合支援センター長","answer":"しっかりと実施していく中で、今後、実際に児童・生徒向けの取組について、どういったことを考えられるか、考えていきたいと思います。警察の方をお呼びして、こうした犯罪に巻き込まれないように例年指導を行っているところです。今回の家庭教育講演会と直接結びつくものではございませんけれども、引き続き学校での指導を継続して行ってまいります。","voiceIndex":44,"id":"exchange-010"},{"speaker":"せらく委員","kind":"確認","question":"周知は、学校を通してお手紙の配付やＰＴＡからとおっしゃっていたのですけれども、それ以外の方法で、例えばＬＩＮＥを使うことは、今回の内容からすると考えていらっしゃらないというふうな受取りをしたのですけれども、認識について、確認をできればと思います。","respondent":"舩木庶務課長","answer":"保護者の方のみに行き渡るようなＬＩＮＥのネットワークというものがないため、今回については、予定しておりません。","voiceIndex":49,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問","question":"そうなると、対象の方以外にはあまり伝わってほしくないというようなことなのでしょうか。例えば、私なんかもＳＮＳを使って、こういうのがありますよと広報するというのは、あまりよくないということなのでしょうか。","respondent":"舩木庶務課長","answer":"こういうことがあるよとか、こういうことが予定されている、区ではこういうことが実施されているということをお伝えいただくこと、そのものを否定するようなものではありません。","voiceIndex":51,"id":"exchange-012"},{"speaker":"せらく委員","kind":"質問・要望","question":"しっかりターゲット層に届くような形で協力させていただきたいと思います。こちらも子どもへの暴力防止ということで、内容が近いのかなと考えています。特に大人のＣＡＰのワークショップというのは、各学校で結構な予算が取られていると思うので、こちらと重複するものなのか、違いというところを一つお聞かせいただければと思います。","respondent":"舩木庶務課長","answer":"一方でＣＡＰのほうは、繰り返しなりますけれども、こういった社会的なことというよりも、むしろ保護者とお子さんとという関係性の中で、虐待とかいじめとか、そういうところをどういうふうに防いでいくかに。","voiceIndex":53,"id":"exchange-013"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも２点伺わせていただきます。その背景を確認したいのですけれども、こちらは予算としてはＰＴＡ支援として計上されているということで、基本、一義的には区内の学校に通う保護者や子どもたち向けということだからということなのでしょうか。予算としてどのようについているかというところを含めてご回答いただきたいと思います。２つ目が、周知の仕方のところです。","respondent":"舩木庶務課長","answer":"今後につきましては、どれだけその限定的な方にさらに行き届かせるかという方法はいろいろ様々あるかと思いますので、そこは今後の１つの課題として捉えて検討していきたいと考えております。","voiceIndex":57,"id":"exchange-014"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご回答ありがとうあります。確認なのですけれども、家庭教育力支援の予算ということであれば、特に区内学校の保護者向けに限らずとも、私立学校の保護者向けにも別に見てもらうことを妨げないということで、つまり、そういった方々も見られるような環境で展開していいのかというところをご答弁いただきたいと思います。周知のところのご説明、ありがとうございました。","respondent":"舩木庶務課長","answer":"区の教育委員会が実施しているという意味で、区立の小学校、中学校、義務教育学校に通われている児童・生徒の保護者をターゲットとしている事業として位置づけています。","voiceIndex":59,"id":"exchange-015"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の調査結果","agenda":"区立学校におけるいじめの重大事態の調査結果","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"お答えいただける範囲で結構ですが、確認をさせていただきたいと思います。一方で、いじめた側の子どもに対する指導について、お答えいただける範囲で結構ですが、どのような指導をされて、その結果、ご本人、いじめてしまった子どもも、理解をしてくれているのかどうか、この辺の状況をお答えいただける範囲内でいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"けがの度合いについてですけれども、このいじめの対応のところで、「ひどく」というところがありまして、何というのでしょう、重大事態に当たるような大きなけがをしたということになります。","voiceIndex":65,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、そこまで大きなけがをさせてしまった事態だということですが、こういう行為をしてしまった場所は学校の中なのでしょうか。こういういじめが起きるのは休み時間とか、登下校の時間とか、授業ではない時間帯の出来事だと思えるのですが、そういうときの先生方の配置といいますか、今後未然に防ぐという視点でどういうふうに目配せしていただく体制を取っていただいているのか、その辺いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そうした意味で、先生の配置ももちろん含めてそうなのですけれども、子どもたちが感情的になったときに気持ちを抑えるとか、そういった指導を行っていくということも併せて必要かなと考えていますので、今後また共有しながら進めていければと考えております。","voiceIndex":67,"id":"exchange-017"},{"speaker":"山本副委員長","kind":"確認","question":"ご説明ありがとうございました。私からも何点か質問します。こちらのいじめの重大事態の調査結果について、定期的にこのようにご報告いただいておりますけれども、改めて文教委員会での報告の意味や位置づけについて確認をさせてください。","respondent":"丸谷教育総合支援センター長","answer":"発生を報告しておりますので、改めて調査が終了した時点で、調査が終了したということをご報告しているところですが、事案の公表について、ご家庭の許可が得られれば、その時点で詳細をこの場で報告し、事案についての共有や未然防止の観点から、今後の対策についてもご協議。","voiceIndex":71,"id":"exchange-018"},{"speaker":"山本副委員長","kind":"質問・要望","question":"個別の事象の報告をいただけることはありがたいのですけれども、やはり全体感というところで、一つ一つ把握することもさることながら、品川区全体の区立学校の中で、全体として今どういう状況なのかというのを理解に努めていくのも文教委員会の役割かなと思ってあります。もしよろしければ、そのような工夫をしていただけるとありがたいと考えていますので、ちょっとその部分のご見解をいただきたいです。","respondent":"丸谷教育総合支援センター長","answer":"その研修では、いじめ事案の事例を扱う事例検討を進めており、こういったいじめの重大事態になり得るような事例についても、ワークショップ形式で学んでいるところです。","voiceIndex":73,"id":"exchange-019"},{"speaker":"山本副委員長","kind":"質問・要望","question":"理解が深まりました。類型化しながら、いじめ防止研修を通じて進められる各学校に向けて分かりやすくいじめの予防の説明をしていくということで、とてもよいと思いました。ぜひ、進めていただきたいと思います。１点、確認になるのですけれども、この類似事案の役立たせ方、具体的な共有の手法について。","respondent":"丸谷教育総合支援センター長","answer":"資料をお配りすることで、自校に持ち帰って確認することや、各校でもいじめに関する研修を校内で行うことになっておりますので、そういったところで、教員一人ひとりに伝わるような仕組みを作っていきたいと考えております。","voiceIndex":75,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"確認","question":"３つお尋ねします。３つ目は、大けがということですから、病院に行ったのではないかと思うのですが、もしそうだとすると、治療費については、日本スポーツ振興センター、前の日本学校安全会か、そちらのほうからになるのか、それとも加害という言い方はよくないかもしれませんが、けがをさせてしまった方の保護者の方々が何らかの措置をしたのでしょうかというところについて、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"いじめ対策委員会の答申自体は８月２２日に結果が出ていまして、教育長が受理をしている形になります。その後、教育総合支援センター内の係のほうから保護者に結果を郵送させていただいて、結果の公表の可否をご判断くださいということでやり取りを進めております。","voiceIndex":79,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"いじめの予防プログラムということを児童・生徒、そして教員もともに同じ認識で行っているというご説明で、非常に頼もしいなと思いました。今年度、結果としてどうだったのかということを測定し、改めて分析するということなのですけれども、改めてそういった結果の報告が文教委員会なり、区役所なりであると考えてよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"効果検証というところでは、今後１年間まずは取り組んでみて、効果というか、成果というか、そういったところもしっかりつかんで、この場でも報告をしていきたいと考えております。","voiceIndex":86,"id":"exchange-022"},{"speaker":"山本副委員長","kind":"確認","question":"先ほどの質疑の中では、教員向けのいじめ予防プログラムを拡充していくことで予防に努めていて、その効果検証をして結果報告をいただくということだったのですけれども、いじめＤアンケートの活用によって件数は増えているけれども、早期発見に結構つながっていて、重大事態には至らずに対応できているとこれまでの決算特別委員会等でも確認等をさせていただいておりまして、理解をしているのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"このいじめＤアンケートを基に、いじめの認知がしやすくなったという声は学校からも聞こえてきているところですので、こうしたところからも、いじめの認知率についての効果検証はできると考えておりますので、そうした数値的なデータも示せるようにしていきたいと考えております。","voiceIndex":89,"id":"exchange-023"}]},{"id":"topic-04","title":"令和７年度以降の土曜授業","agenda":"令和７年度以降の土曜授業","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"幾つかお伺いしたいのですけれども、まず冒頭の変更の趣旨のところで、「土日は子どもたちの家庭や地域社会での生活時間の比重を高め」とあります。こういった取組をする中で、すまいるスクールに行くお子さんが今後増えていくのかどうかという経過をぜひ見ていただきたいなと思います。全国的に、土曜授業については、今、どのように取り組まれているのか、２３区の傾向など、改めて伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"都内、２３区においては年１０回であるとか、そういう形で実施してきた自治体が多くございましたが、近年はどの自治体も、土曜授業を縮小する方向で進めております。","voiceIndex":96,"id":"exchange-024"},{"speaker":"西村委員","kind":"質問・要望","question":"個人的には、全国的に土曜授業が少なくなっていく傾向であることは、改めて驚いたなと思いました。今言っていただいたように、充実した週末とするため土日を活用する中で、例えば地域部活動移行、また官民連携の取組等を教育委員会主催や区のほうでおこなっていただけるのか、そういった取組の可能性があればお聞かせいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちの充実した体験活動については、今後土曜授業を決め打ちで設定はしないということを周知し、広げていきますので、その中で、各事業者や民間の方に土曜の取組を増やしていただいて、子どもたちが参加できるような取組が増えてくるとありがたいと考えているところです。","voiceIndex":98,"id":"exchange-025"},{"speaker":"山本副委員長","kind":"質問","question":"私からも何点か質問します。今回、土曜授業が年間で２回以上縮小になるということなのですけれども、総授業時間は減るのでしょうか。つまり、土曜日が減った分を平日に振り替えることで、総授業数自体は減らないということなのでしょうか、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"ただ、コロナ禍に行事の精選であったりとか、そうした活動を効率的に行うということが各校進んできておりますので、これまで例えば行事の準備に使う時間を膨大に用意していたものが少し縮小されたりですとか、そういったことも踏まえて。","voiceIndex":101,"id":"exchange-026"},{"speaker":"山本副委員長","kind":"質問・要望","question":"理解し、ただ振り替えではなく、一部減らしているかもしれないということで受け止めましたので、もし違ったら教えていただきたいです。それから西村委員からもお話がございましたけれども、土曜日、新たに授業等がなくなった時間についてぜひ子どもたちに有意義に使ってもらえるように、区や教育委員会として具体的なサポートを進めてほしいと思っています。これは要望です。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、土曜日に連携できるような事業がありましたら、その辺りは、教育委員会としても連携して進められるようにしていきたいと思います。","voiceIndex":103,"id":"exchange-027"},{"speaker":"山本副委員長","kind":"質問・要望","question":"１点だけ。民間との連携の趣旨ですけれども、区内の小中学生に任意で参加できるような取組がありますよというのを案内する。例えば勉強、学びにつながるようなイベントを、区や教育委員会が音頭を取って実施する、そういったこともあるかなという想定をしての要望でございました。参考としていただければと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ、すみません、素朴な疑問というか、仕組みについて、詳しいところが、よく分かっていないのですけれども、今回の変更点で、「スチューデント・シティ（土曜実施）後の月曜日は当該学年のみ振替休業日とする」とあります。今までは、振替なしの土曜授業の一環としてやっていて、月曜日は休みにしていなかったということなのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今、委員からご質問があったとおりです。スチューデント・シティは５年生が参加しているのですが、土曜日に実施して、その翌月曜日は通常授業ということで、振替休業日にはしてきてはございませんでした。","voiceIndex":107,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"変更の趣旨のところに、本来の目的が書いてあります。先ほど教育総合支援センター長が、「保護者の方から習い事に行かせられないというお声もあったので、土曜日の授業を減らした」とおっしゃっていて、理由の１つに聞こえたのですが、それは、本来の目的なのですか。","respondent":"丸谷教育総合支援センター長","answer":"本来の目的ではないのですけれども、保護者から、習い事とか、例えば通院予定を組みたいのだけれども、土曜授業があるから通院できないとか、幾つかそういった声があって、土曜授業について見直してほしいというような要望も少なからずございました。","voiceIndex":111,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"教育の現場として、保護者の方のリクエストにお答えするのはもちろん大切なのですけれども、本来の目的、柱をしっかり持っていていただきたいなと思いました。１２月に説明会があって、その後、具体的に学校で計画を立てていくと思うのですけれども、教育委員会に提出する時期と、それから地域といろいろ相談していったりする時期、その流れとその時期を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"各校が作成する教育課程についてですけれども、１２月に説明会を行いまして、１月の下旬に案という形で教育委員会に上がってきます。そしてその後、我々教育総合支援センターの指導主事と行事予定等を詰めながら、最終的な確定は３月の末となります。","voiceIndex":113,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域の行事と学校は密接な関係があるので、その後改善されて、連絡は密にしていただいていると伺っています。今回もこういうふうに変わったので、地域の行事等との調整というのですか、学校の年間行事に合わせて地域の行事を組むことがありますので、そこのところをしっかりと周知、調整していただいて、伝えるようにお願いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"地域行事と学校には密接な関係がありますので、その辺りの調整をしっかり行うように学校のほうにも働きかけてまいります。","voiceIndex":115,"id":"exchange-032"}]},{"id":"topic-05","title":"令和５年度品川区立学校における不登校・いじめの状況","agenda":"令和５年度品川区立学校における不登校・いじめの状況","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"その辺り、実数は分からなくてもいいのですけれども、状況を伺いたいなと思います。もう一点が、学校の中で実際に授業を流すというような、オンラインで授業をつないでいる学校や教室が区内にどれぐらいあり、オンライン授業が実施されているのか、その辺りの実態が分かっておられたらお聞かせいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"正確な数は把握していないのですけれども、児童・生徒の要望であったりですとか、状態に合わせて各校で対応を行っているところです。それで授業を受けられる子もいれば、それすら難しいというお子さんもいます。一人ひとりに合わせた対応を行ってまいりたいと考えております。","voiceIndex":121,"id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"１点目のほうで、外に出てこられない子たちの状況に関するご相談を私自身も多くいただきます。親御さんと学校はつながっていますけれども、子どもが全く第三者の方と会えない期間が数か月続いていたような状況で取り組める施策として、すごく有効ではないのかなと思いますので、そういったプッシュ型の支援、子ども家庭支援センターとの連携のところを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"関係機関との連携につきましても、子どもや家庭の実態に合わせて進めていきたいと考えております。オンラインでの授業配信というところで、こうした取組について、好事例を広げていけるように情報共有を図ってまいります。","voiceIndex":123,"id":"exchange-034"},{"speaker":"西村委員","kind":"質問","question":"いじめのほうなのですが、学年別いじめの認知件数のところで、グラフが山のようになっているところが一つ気になりまして、５年生のところで高くなって、そのまま下がっていくようにグラフ上は見えるのですが、それはやっぱり年齢が上がっていくごとに、こういったいじめが見えづらくなっていたり、またＳＮＳとかＬＩＮＥだったり、裏に隠れているというような可能性はあるのではないかと思うのですが。","respondent":"丸谷教育総合支援センター長","answer":"当然裏に隠れたＳＮＳ等を利用したいじめというものもありますので、そういったものは、学校が把握した時点で認知して対応していくというような考えでおります。本区においても子どもたちにいじめに関する理解を深めさせるような取組を継続して行ってまいります。","voiceIndex":125,"id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"そこはぜひ、分析を進めていただいて、また共有いただきたいと思います。もう一点、品川区独自のところでいくと、まもるっちがあります。オーストラリアだったと思うのですけれども、１６歳以下のＳＮＳの利用を禁止していくというような報道がありました。その点何かお考えがありましたらお願いします。","respondent":"丸谷教育総合支援センター長","answer":"本区については、まもるっちがありますので、６年生まではスマートフォンは不要という家庭も多いかなと思いますけれども、中学生になってスマートフォンを持ち始めるころには、しっかり指導していきたいと考えております。","voiceIndex":127,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"３つお伺いします。先ほどのご説明にもあったのですけれども、不登校の児童・生徒数が１,０００人あたりの国の推移と見比べると品川区が十数％多い。この辺についてはどのような分析をされているのかというのが１つです。品川区としてこれからどういうふうに不登校対策をお考えになっていて、どういった方向で思考されているのか、この３点について、まず、教えてください。","respondent":"丸谷教育総合支援センター長","answer":"不登校特例校についてですけれども、今、全国的にも少しずつ広がりを見せているところですので、そういった周辺自治体の状況や成果等も見ながら、本区にとってどういった形の取組が児童・生徒のためになっているかということを検討しつつ。","voiceIndex":129,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"２つ目の質問のところで、担任や区の機関などと、直接、継続的に対面で相談・指導等を行っているという話でした。９割を超える９３％の方がやり取りをする中で、お子さんたち、様々な反応があると思うのです。９３％の児童・生徒がよくそうやって継続的に会ってくれるなと思うのです。どういう対応があるのかというところをもう１回ちょっと深く、もう少し詳細に教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"子どもによってはＨＥＡＲＴＳが相談をして、その後学校に一緒に行ってみようというような取組、そういった事例もありますので、子ども一人ひとりに合った対応をしています。","voiceIndex":131,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"意見","question":"ありがとうございました。不登校児童・生徒のうち１２.９％、約１３％の方がマイスクールを利用されている。接触を持っているということで現場のご苦労は容易に推測できるところなのですけれども、そういった意味でも品川区の不登校児童・生徒のうち９３％の皆さんとコンタクトを取って直接相談支援をできているというのは、非常に評価すべきことなのかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"不登校の子どもが増えてしまっているということと、それに対して、現在７３％の方が専門的な相談・指導を受けたり、あるいは２０％の方が学校で相談したりというようなそれぞれの状況は分かるのですけれども、相談を受けた後、不登校の子どもが安心して再び地元の学校に通えるようになったなど、指導・相談した結果、成果というのでしょうか、そういったところがもしあれば、よりいいのかなと思ったので。","respondent":"丸谷教育総合支援センター長","answer":"今年度から各校で学校風土を高めていくことができるように様々なことに取り組んでいますので、今後の不登校の解消やいじめの重大化を防ぐというところでは期待していきたいと考えております。","voiceIndex":135,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"私からは、学年別不登校児童・生徒数のグラフから質問させていただきたいと思います。１、２、３、４年生について、令和５年は大体同じ数なのですけれども、令和４年と比較して１、２、３年生は倍増しています。令和５年は、１年生も最初からかなり多い人数で結構びっくりしているのですけれども、特に低学年に対しての支援についてどういった思いがあるか、お聞かせいただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"基本的には在籍校の別室を利用していただくことが最も負担の少ない支援なのかなと考えておりますので、今年度の利用状況を見ながらまた次年度以降の対策については考えていきたいと思います。","voiceIndex":138,"id":"exchange-041"},{"speaker":"せらく委員","kind":"意見","question":"いろいろな対応を検討しているということですが、令和５年は、いきなり１年生の人数が多かったということでした。","respondent":"丸谷教育総合支援センター長","answer":"ですので、全てのお子さんを事細かにというところは難しいと思うのですけれども、やはり気になるお子さんについての連携というのはしっかりと引継ぎを行って、小学校での支援や指導に活かしていければと考えております。","voiceIndex":140,"id":"exchange-042"},{"speaker":"せらく委員","kind":"質問","question":"展示会とか教育関係のものを見ていると、幼稚園、幼児教育から小学校、中学校までシステムで児童のデータ引継ぎが結構スムーズにできるようなツールもあったりするのですけれども、品川区ではそういったツールなどは使っていらっしゃいますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"区立小学校から区立中学校に向けては、システム上で児童・生徒の情報の連携が進んでいるのですけれども、幼稚園や保育園と小学校のつなぎの部分は、そういったシステムがあるとは把握していないところです。","voiceIndex":142,"id":"exchange-043"},{"speaker":"山本副委員長","kind":"質問","question":"その上でちょっと何点か伺わせていただきます。不登校の支援なのですけれども、マイスクールの利用者が不登校児童・生徒の全体の１２.９％という状況で、この数字に対する受け止め、どのようにお考えかというところでお教えください。行政視察でお伺いした話だと、まさに最後のセーフティーネットとして位置づけているということで、すごくその方々の熱い思い、熱意も感じましたし、すごく印象的でした。","respondent":"丸谷教育総合支援センター長","answer":"不登校支援につきましても、担任任せになるのではなくて、学年や学校内、生活指導部会という組織もありますので、そういった学校の中の組織の中で、一人一人への支援について検討して進めているところです。","voiceIndex":145,"id":"exchange-044"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それぞれご説明をありがとうございました。不登校の児童・生徒に対する方針について、理解を深められました。１点、戻りたくない子どもたちに対するセーフティーネットというところがあればいいのかなというところがありますので、こちらはぜひご検討をいただきたいと、要望します。先ほどの質問と同じですが、リアルもとても大事だと思っていまして、リアルで共有していくことも大事だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"確認","question":"二点お尋ねします。一つは、今日、ほかの委員の方々からも不登校特例校に関連しての質問があったのですが、今の教育総合支援センター長の話だと、幾つかの支援の１つとして学校に戻らなくてもいいという方法もあるということなのですか。大和郡山市は人口８万人の市かな、品川区と比べれば５分の１。幾つか、その先生方の支援という話がありました。お分かりの範囲で結構ですので教えてください。","respondent":"丸谷教育総合支援センター長","answer":"他自治体の不登校特例校の成果や課題等も見ながら、本区の児童・生徒にあった支援の在り方というものについて、引き続き検討していきたいと考えております。","voiceIndex":149,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不登校特例校については理解しました。別の機会にお尋ねしたいと思います。中学校はいろいろな教科や部活があるので、いろいろな先生が生徒に関わっていて、Ａ先生はなかなかなじめなくても、Ｂ先生だったら話ができるよみたいなことも中学校では比較的しやすいのですが、小学校の場合はお一人で担任をお持ちなので、どうしても担任の先生の負担になる。これは、要望ではなくて応援です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-047"}]},{"id":"topic-06","title":"「品川区不登校支援ポータルサイト～ぷらっと～」の開設","agenda":"「品川区不登校支援ポータルサイト～ぷらっと～」の開設","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"私も実際に拝見をさせていただきました。要望とご質問、併せてなのですけれども、これからいろいろな学び方、居場所があるよということで情報を載せていただけると思っています。発達障害を持っているお子さん向けの放課後の居場所を展開していらっしゃる区内の団体もありますので、そういったところも幅広く載せていただきたいと思います。要望と質問両方ですが、ご答弁をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"民間の例えばフリースクールですとかその他の団体につきましても、掲載方法を今検討を行っているところです。順次、居場所、または学び方、学べるもの、そういった情報も併せて掲載していけるように努めてまいります。","voiceIndex":161,"id":"exchange-048"},{"speaker":"西村委員","kind":"質問・要望","question":"情報提供していただく際ですけれども、既に不登校になっている保護者と子どもだけではなくて、行き渋りになっている生徒・児童もいると思いますし、これから自分の子どもが不登校になったらどうしようと思われている方もいらっしゃると思うので、幅広く周知をお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"私はまだ内容を拝見してないのですけれども、確認をさせてください。これは、品川区の教育費として当初予算案の中に計上されていたということでよろしかったのでしょうか。その上で今回これは、どれぐらいの予算で実施されているのかというところを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"予算の中に入っているものです。額については、すみません、今資料がないのですけれども、３００万円から４００万円で構築しているサイトです。","voiceIndex":164,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"確認","question":"すみません、私は今まだプレス発表等を確認していないのですけれども、今回の不登校支援のポータルサイトの目的というところで、先ほど西村委員からあったとおり、どこにマイスクールがあるのかとか、不登校の方で悩んでいる保護者の方がたくさんいらっしゃいますから、こういうアクセスしやすい環境というのは非常に大事かなと思います。","respondent":"丸谷教育総合支援センター長","answer":"今回の不登校支援ポータルサイトについてですけれども、予算プレス発表の際には、ポータルサイトのガイドブックとセットで発表しているものとなります。ガイドブックのほうはまだ作成中なのですけれども、先行してポータルサイトのほうを開設したという経緯になります。","voiceIndex":166,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"当初予算案のプレスの中に入っているということで、すみません、私もあまり記憶になくて大変失礼いたしました。今日の報告事項からは少し外れるのかもしれませんが、同じ予算でやるというガイドブックというのはどういったものをお考えになっていているのでしょうか。その目的は何かということで、こちらのほうも併せてお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"対象については、やはり不登校になりかけているようなお子さんのいる保護者の方が対象になるのですが、発行部数が限られますので、全世帯ということではなくて、お困りを感じている方に行き渡るような形で、今、数も含めて検討しています。","voiceIndex":168,"id":"exchange-052"},{"speaker":"せらく委員","kind":"質問","question":"サイト作成費用が３００万円くらいと、あと運営の費用が毎年かかってくるものだと思いますけれども、その辺りの金額が分かれば教えてください。ぷらっと不登校支援ポータルサイトを見ていて、メニューのところに教材というのがあるのですけれども、教材は今後どのようなものを掲載する予定なのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"サイトのメニューについてですけれども、現在は不登校支援情報のところが開くようになっているところですけれども、そのほかのこれから更新する小学１年生から３年生の皆さんへというところは子どもたちへのメッセージであったり、保護者の皆さんへというところでは。","voiceIndex":170,"id":"exchange-053"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも、何点かお伺いいたします。先ほどせらく委員からもご質問ございましたけれども、いじめ対策のポータルサイトと同じというところで、これはそれぞれ別々に注文をしたのでしょうか。それとも発注したのでしょうかということと、この東京法規出版に業務委託としてお任せしているものが他区も結構あるとかいうのをもしお調べになっているようでしたら、教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"効果測定につきましては、方法も含めて検討が必要かと思いますけれども、例えば、アクセス数ですとかそういったところから始まって、今後チャットボットも実装する予定ですので、どのような相談や検索が多いのか。","voiceIndex":173,"id":"exchange-054"},{"speaker":"山本副委員長","kind":"質問・要望","question":"１点、細かいところで恐縮なのですが、入札はいじめのポータルサイトと一緒なのでしょうか。それとも別々で、結果的に一緒のところが請け負うことになったのかというのをちょっと確認させてください。まとめてちょっとお話ししてしまいますと、子どもへの教え方のところで理解をいたしました。効果測定のほうも、どういう形でできるかどうかも含めて、ぜひその辺も含めて進めていっていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"結果的にいじめポータルサイトと同じところになっているのですけれども、予算の枠組みも違えば入札の時期も異なりますので、結果的に同じところになったという認識でおります。","voiceIndex":175,"id":"exchange-055"}]},{"id":"topic-07","title":"品川区立八潮子育て支援施設の愛称募集","agenda":"品川区立八潮子育て支援施設の愛称募集","exchanges":[{"speaker":"山本副委員長","kind":"質問・要望","question":"私から、１点だけ質問させていただきたいと思います。この公募の愛称の決定方法なのですけれども、こちらはアプリやはがきによる投票を行って区長が決定するので、投票結果で一番多いところに決まるということになるのですか。そうすると、あらかじめ選ぶものがあるということなのでしょうか。","respondent":"藤村子ども育成課長","answer":"検討過程で「エコルとごし」の場合、検討委員会があったはずなのですけれども、今回の子育て支援施設は新しい施設で、メインユーザーが子育て世帯というところになってくるので、より利用者に近づいたところで、お名前を採りたいなというところが一つ。","voiceIndex":182,"id":"exchange-056"},{"speaker":"山本副委員長","kind":"質問","question":"募集と選考ということで、最初にお聞きしたときには理解が及んでいなかったのですけれども、ご説明をいただいてクリアになりました。ぜひ多くの方々に関心を持っていただいて、応募いただいて、その中から親しみのある愛称をつけてもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-057"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"端的に数字から確認させてください。ちょっと大きな数字だったのでびっくりしたのですけれども、メンタルヘルスが原因の休職者増というところで、令和５年と令和６年の同時期において、いきなり小学校において２倍以上になっていますが、これは延べというか、どういう計算をされていらっしゃるのか。","respondent":"中谷指導課長","answer":"そうして、年度途中になると業務が増えてしまうというような現状がありますので、そこにいかに会計年度任用職員等の配置など、正規の教員の業務負担がいかに分散できるかというところをしっかりと支援していきたいと考えています。","voiceIndex":189,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"一番の原因だということの認識なのでしょうか。もう一つ言えば、やはり今少子化である中、教員不足ということが言われる状況で、ごめんなさい、こういう言い方が適切なのかどうか分かりませんが、トレーニングをあまり十分に受けていないまま、教員になっている方がいるとか、そういったことも考えられるのかどうか。もう１回重ねての質問になってしまうのですけれども、これについてもう一度教えてください。","respondent":"中谷指導課長","answer":"増えている原因について、これという限定的な理由は見いだすことはできないかと考えています。実際にメンタルヘルスで休職をされる方の個別のケースというのは、実に様々であります。","voiceIndex":191,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"複合的な要因が多分あって、様々なご事情もそれぞればらばらだから一言では言えないというのはそのとおりだと思うのですけれども、２つだけ教えてください。それと、先ほどの不登校のとき、いじめのときの資料の中で、１,０００人あたりというような国の平均との比較というのが出ていましたけれども、いわゆるその全国的な傾向と比べて、品川区がどういう位置にあるのか。その辺りも教えてください。","respondent":"中谷指導課長","answer":"２つ目の全国的な傾向というところなのですけれども、割合で申し上げますと、小学校と中学校を比較しますと、中学校は全国平均よりも下、そして小学校については全国平均よりも上、高い数字となっております。","voiceIndex":193,"id":"exchange-060"},{"speaker":"田中委員","kind":"質問・要望","question":"教員不足の現状と課題のところの確認をさせていただきたいのですけれども、一番左の欠員状況は、病気や産休で欠員のうち、臨時任用職員とか講師の方で補充されていない人員ということです。都の責任という言い方は、言い過ぎかもしれませんが、都が行うべき任務なのか、区が自らの予算で確保しなくてはならないものなのか、そこを確認させていただきたいと思います。","respondent":"中谷指導課長","answer":"基本的には、これは東京都教育委員会の示す基準に基づいて行っているところなのですけれども、実際にやはりこうやって人を確保したくても難しい状況があるので、補充をしていくために、私たちのほうでは区費講師と言いまして。","voiceIndex":196,"id":"exchange-061"},{"speaker":"田中委員","kind":"確認","question":"欠員に対する補充は都の考え方の下で行われているというお話であります。その補充されている人数と、実際に欠員となっている人数の割合、要は都が一生懸命やっている結果であってまだまだ２０人足りないという状況なのか、都は都でなかなか大変でそこまで補充し切れなくて、結果２０人という数字になってしまっているかという、その都の対応状況はどうなのかというのを確認したいのですけれども。","respondent":"中谷指導課長","answer":"なので、申し訳ありません、産休の方だけ今人数が出ていないのですけれども、おおむねこの合算させていただいた数がお休みを取るというような、または辞められるというような方ですので、トータルで申し上げると大体そのぐらいの数で。","voiceIndex":198,"id":"exchange-062"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味では、都は都でその辺は頑張っているけれども、また年度の途中なのでなかなか急には人員確保が難しいため、２０人が欠員状態になってしまっているのかなという印象を受けました。なかなか区費では難しいのかなとも思えるのですけれども、先ほどの区費講師の方の位置づけと言いますか、臨時的に短期間の補充のためという意味ではないということで良いのでしょうか。","respondent":"中谷指導課長","answer":"先ほどご質問の補足になるのですけれども、産休代替の数が出ましたので申し上げると、産育休全て合わせた数で、小学校と前期課程が７４名、それから中学校と後期課程については２０名です。","voiceIndex":200,"id":"exchange-063"},{"speaker":"西村委員","kind":"質問","question":"働き方改革としての取組ということで、始まったばかりでありますが、不登校巡回教員について、もう少し現状と評価を伺いたいと考えています。どのように巡回をされていて、現場からはどのような教員の方々の声が上がってきているのか、お聞かせいただければと思います。","respondent":"中谷指導課長","answer":"これは都の事業ですので、都の教育委員会が定期的に連絡会などを開いておりまして、各地区に今おります不登校対応巡回教員に対して、サポートをしながら事業を進めているというものになっております。","voiceIndex":202,"id":"exchange-064"},{"speaker":"西村委員","kind":"質問・要望","question":"よく分かりました。学校の中だけで解決を導いていくのではなくというところで、いろいろな知見が合わさっていくと、私たちもご相談を受けることがすごく多いので、ぜひまた改めての機会でご共有をいただきたいと思います。この中にはないのですが、教員の負担ということで考えると、最近区内でも外国籍のお子さんがすごく増えてきたなという実感があります。","respondent":"丸谷教育総合支援センター長","answer":"日本語指導が必要な児童・生徒への対応ということで申し上げますと、山中小学校と八潮学園の中に日本語指導教室を設置しております。昨年度までは山中小学校１校だけだったのですが、今年度から２拠点に拡大をしております。","voiceIndex":204,"id":"exchange-065"},{"speaker":"西村委員","kind":"質問","question":"もう一点最後に伺いたいのが、もう一枚のほうの業務の役割分担適正化を進めるための取組に、教師の業務だが、負担軽減が可能な業務とあります。今、チームで学校全体で動こうとしていても、どうしても担任の先生お一人が窓口になってご対応が偏ってしまう、負担になっているというところがあろうかと思いますので、そういったサポートの体制の整備ができないかと思うのですが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"支援が必要な児童・生徒とご家庭への対応ということで申し上げますと、支援にも様々な支援の形態があるかと思います。必要な支援もご家庭により様々です。","voiceIndex":206,"id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問","question":"今の現状の課題ですね、教員の不足と、あとサポート体制が整理されているので、大変分かりやすかったです。研修等はあるのでしょうけれども、難しい側面があると思います。いわゆる管理職の学校のマネジメント・運営に関するスキルアップについてはどのようにお考えになっていて、教育委員会としてどのようなフォローをされているのかお尋ねします。","respondent":"中谷指導課長","answer":"もちろんそのためにはきちんと人を確保していかなければいけないということがあって、４月１日の時点でやはりやっていただきたい方がそこにいらっしゃるという状況になるように、準備の段階から。","voiceIndex":208,"id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一つの学校の例をお話しいただきました。もう一つの確認は、不登校巡回教員について、これは加配をしていったところの分がこの方で決まったのかということの確認で、つまり例えば豊葉の杜学園は不登校の加配が１名あって、その学校だけだったけれども、これを不登校巡回教員という形で５校巡回というふうにしていっているのかというところが一つ。","respondent":"中谷指導課長","answer":"これからなのですけれども、やはり東京都教育委員会としては、この不登校施策に非常に重きを置いて広げていきたいと考えており、これに品川区としてもしっかり応えていきたいと思っているので、今年は１校の拠点校と４校の巡回校ということでやっておりましたが。","voiceIndex":210,"id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問","question":"巡回教員について、今お話があったように東京都の力も借りて、この良い仕組みを広げていくという話を伺えたので、大変期待しています。別の方の一般質問にもありましたけれども、待遇が実は違うわけです。どれがという話はちょっと控えさせていただいて、この辺については質問してもいいのでしょうか。お願いします。","respondent":"中谷指導課長","answer":"先ほどご指摘いただいた、区で行っている会計年度任用職員のほうの待遇というところですけれども、こちらについては様々、主管である人事課のほうと連携させていただいて、きちんとした見直しというのを随時やらせていただいているので。","voiceIndex":212,"id":"exchange-069"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私からも質問します。理解が進みました。お聞きしたいのが、働きやすい環境づくりというところで、先生方のデジタル活用、デジタル環境についてお聞きしたいと思います。その点、改めてご質問させていただきたいと思います。例えば教職員向けのアンケートですとか、調査分析、それから他自治体との比較検証とか、どういった根拠を基にそのようにお考えかというところをお教えいただけますでしょうか。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"そういった意味では良い事例というか、こうやって子どもの学びや表現力というのを深められるのだということをしっかり全校で共通理解しながら、またさらに進めていくというようなことが大事であるかなと考えているところです。ＧＩＧＡスクール端末については今の説明のとおりです。そのほかにも、教員が使用するコンピューター、様々なネットワーク環境があります。","voiceIndex":214,"id":"exchange-070"},{"speaker":"山本副委員長","kind":"質問・要望","question":"１人１台端末のところですけれども、私も子どもたちに１人１台端末があって、Ｗｉ－Ｆｉでつながる環境が用意できているということは、非常に良いことだと思ってあります。裏づけや根拠というところはないですが、ほかとの比較はしないけれども、今のシステムとしてはベストだというようなご認識であって、ほかと比較したときにはどうなるのかというところで、ちょっとご確認をさせていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-071"},{"speaker":"山本副委員長","kind":"質問","question":"収束するような形での質問にちゃんと納めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-072"},{"speaker":"山本副委員長","kind":"質問・要望","question":"そういったことから、同時進行、両方双方向でやるのがとても有効だというお話をお伺いしています。改めてお聞きしたいのが、現状のシステムの中で最適だというご回答でしたけれども、さらにこの仕組みをどう生かすかというところで言うと、仕組みの構築というところで言うと様々よりよくしていく余地があるのではないかと思うのですけれども、改めてご見解をお聞かせいただけますでしょうか。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"自主の校長会でも、それぞれ区の施策であったりとかその実施に向けて、他校ではどのような進め方をしているのか、そういう情報共有の場を月に一回設けておりますので、そういったところでの情報共有も図られているという認識です。その意味では、先ほどのリアルとデジタルというところをいかにうまく学校の中で使いこなしていくかと。そこが校長先生としてのマネジメントにもなっていくのかなと考えています。","voiceIndex":225,"id":"exchange-073"},{"speaker":"山本副委員長","kind":"質問・要望","question":"リアルも否定は全くしておりません。リアルも大事だと思ってあります。そして、リアルとデジタルをやはり有効に活用していただきたいです。デジタルの進化は日進月歩ですので、そういったところもぜひ教育委員会のほうで主体的にご研究をいただいて、取り組んでいただきたいと思います。デジタルに関するところは以上ですが、続いて、よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-074"},{"speaker":"山本副委員長","kind":"質問・要望","question":"そうですね。その点をまず１点。こういったところは、やはりシステムを活用していくということが効率的になると思いますし、区の中で言えばデジタル推進課等、知見のある方がいらっしゃいますので、ぜひそういった知見のある方にご協力をいただいて、そういったデジタルプラットフォームづくり、もしくは簡単に情報が見えるような形にしていくというのをしてはいかがかと思いますが、ご見解を伺います。","respondent":"中谷指導課長","answer":"最後に、エデュケーション・アシスタントですけれども、こちらもお話しいただいたとおり、拡充の方向で考えております。東京都の補助というところと、やはりそこでは足りないところについては区の補助が区の予算でできるかというところも含めて、検討しています。","voiceIndex":230,"id":"exchange-075"},{"speaker":"山本副委員長","kind":"質問・要望","question":"学校地域コーディネーターのリアルもとても大事だと思ってあります。ぜひリアルも進めていただきながら、デジタルを効果的に使っていただいて効果を上げていただきたいと思ってごいます。それから、エデュケーション・アシスタントについてもご説明ありがとうございました。ぜひ進めていただきたいと思います。ちょっと長くなりました。失礼いたしました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-076"}]},{"id":"topic-09","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"私は高橋しんじ議員が一般質問されていた、教育委員の任命に関連する内容についてお伺いをしていきたいと思います。１つ目の任命同意からうかがいます。質問としては、今後の教育委員の任命について、我々が同意するにあたり、特に教育分野において、より詳細な経歴をお示しをいただきたいと思うのですが、今後の任命同意の際に教育委員の情報としてご提供いただけないでしょうかというのがまず質問です。","respondent":"舩木庶務課長","answer":"今の委員のご指摘の部分はあろうかと思いますけれども、まずは文教委員会の所管の範囲としましては、以上のお答えとします。","voiceIndex":235,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の質疑のやり取り、これはぜひ委員長に、今後の任命同意にあたって、要は教育委員候補の方のより詳細な情報について、今回の質問を通じて求めていくべきだという声があったということを委員長会なり議運なりに諮っていただきたい。今後の教育委員の同意のあり方について、議論していただけるようにお計らいをしていただけるとありがたいということで、要望、お願いをさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-078"},{"speaker":"田中委員","kind":"質問","question":"よろしくお願いします。もう一点、もう一つの切り口として、教科書執筆に携わった方が、教科書採択において、関係者として退席をされたことについての評価というのでしょうか。教育委員としての役割はたくさんある中で、教科書採択は大きな役目の一つだと言うお話もありました。質問としては、教育委員としての役割の中で、教科書採択は、どのような位置づけであるのか、そこをお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"委員の皆様には、教科書の検討委員会が作成した教科書の特徴をまとめた一覧をご覧いただきながら、また教科書見本も併せてご覧いただきながら、本区の児童・生徒に合ったより良いものを選んでいただくという手順を踏んでおりますので、そういった教育委員の役割があるです。","voiceIndex":240,"id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"具体的に言ってはいけないのかもしれませんが、教科書採択には携われなかったけれども、これまでのご経験をもとに、ほかの分野ではしっかりご対応いただいた実績というか評価というか、教育委員の方の評価をするというのも大変極めて難しい話かもしれませんけれども、これまで教育委員を果たしてこられたそのお方の功績といいますか、実績をどのようにご評価されていらっしゃるのか。","respondent":"舩木庶務課長","answer":"本当にいろいろな意味で、審議をしていただき、非常に見識や経歴を活かしたご意見を頂戴しています。そういったところで、教育委員会としましては、教育委員としては適任であると認識をしております。","voiceIndex":242,"id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"まとめます。ただ、逆に教科書採択という観点で言うと、どうしても当事者ということで退席をせざるを得ないわけですが、今回の質問を通じて、教育次長のご答弁にありましたように、私も識見高い教育委員として、またぜひ引き続き教科書採択以外の部分で活躍していただきたいと思っています。そこだけすみません、まとめる前にもう一点だけ確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"今回、当該委員が携わった教科の教科書については、教科書採択の審議に参加しないということで想定をしておったのですけれども、東京都にも確認を行い、東京都から文部科学省にも確認をしていただいたところ、やはり他の教科の教科書であっても。","voiceIndex":244,"id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"手続の問題ですが、私は区長から推薦いただく際、議会側に示す項目について、もう少し詳細な項目を設けて、具体的な、教科書執筆にも携わってこられたというような情報を今後はぜひいただきたいと思っています。その上で、議会としてそれ以外の分野でこれまでの経験をぜひ品川区の教育に生かしていただきたいという観点で、責任ある立場で、判断を下していく。私の質問は以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-082"},{"speaker":"高橋（し）委員","kind":"確認","question":"地方教育行政の組織及び運営に関する法律の中で退席すればということですから、問題はないと。私が質問させていただいたのは、疑念を持たれることが起きないようにする。１つ確認は、教科書を書いていた、退席をしなければいけない。でも法律では問題がないけれども、では道義的あるいは公平性について、大丈夫だろうということで議会のほうに任命同意をしたのでしょうかということをお尋ねします。","respondent":"米田教育次長","answer":"教科書の採択にあたり、教育委員であり、教科書執筆に携わっている人間がいる場合に、そのお考えというのは様々だと思いますけれども、本会議でも申し上げましたように、私どもといたしましては、教科書の採択に関して。","voiceIndex":247,"id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"確認","question":"教育次長は、この教育委員が任命されたときは次長でいらっしゃったわけで、今の教育長も行政側でいらっしゃったわけですから、その辺の経緯はご存じなのかなと思います。これは文教委員会なので、その話は置いておきます。その教育委員がこれからも教育委員でいらっしゃるということについては、法的にも、それから道義的、公平性にも問題ないとお考えなのか、もう一度確認させてください。","respondent":"米田教育次長","answer":"繰り返しにはなりますが、検討委員会より提出された資料等、教科書の見本を基に、当該委員を除いた委員が各々の教科書の内容について審議を行いまして、公正公平に採択を行った結果でありますので、その採択の手続や内容について疑念を持たれることはない。","voiceIndex":249,"id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"確認","question":"そのご発言は確認しましたが、全くの外から見た場合、それはどうなのかと思う方がいらっしゃるということは、やはり感じていただかないといけないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"質問","question":"奨学金を受けていらっしゃる方は、区の行事への参加するとか、区のボランティアに参加するとか、やはりそういったこともしていただけると一体化すると思うのですが、その点についてはいかがでしょうか。貸付をする、一定の基準で返還免除にするというのがあったのですが、そういう形でなく、新聞報道では返還義務がないというようなお話だったのですけれども、その点についてもいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-086"},{"speaker":"山本副委員長","kind":"提案","question":"奨学金制度はそれにつながる仕組みだと考えており、先日の決算特別委員会でも幾つか新たな仕組みのご提案をさせていただきました。現状、作文の審査と面接の審査、それから最終審査があると理解しておりますが、作文の審査ではどなたがどういう形で選ばれるのでしょうか。そこで、この新たな奨学金制度の創設の目的について確認をさせてくださいです。","respondent":"飛田子育て応援課長","answer":"現在実施している高校生への貸付免除についてですが、こちらの義務づけ等についても様々なところで制度設計しているところで、検討してまいりたいと考えております。続きまして、山本委員からの質問です。","voiceIndex":255,"id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"現在検討中の部分が多いということでした。先ほどお話ししたことも含めて期待も大変大きいと思いますし、大きなニュースにもなっていますので、ぜひ今お話あったように様々な条件をクリアしながら、検討を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":259,"id":"exchange-088"},{"speaker":"山本副委員長","kind":"質問","question":"目的のところ、改めてお聞きして分かりました。その目的を達成することに対して、所得制限なしということは有効な場合があると考えます。一方で、進学への思いや将来の夢が強ければ、その親の経済状況において恵まれていて、奨学金の支援がなくても進学できる若者は応募ができるのでしょうか。それとも、応募ができないような制限をかけることをご検討されているのでしょうか。お教えてください。","respondent":"飛田子育て応援課長","answer":"現在奨学金の支援の必要でない方も応募できるのかというところですけれども、所得制限なしで１００名規模を軸に検討を進めてまいります。他区の制度等のことですが、所得制限を設けない制度は区内では例がありません。","voiceIndex":260,"id":"exchange-089"},{"speaker":"山本副委員長","kind":"質問","question":"その給付は大学の授業料相当との報道でしたけれども、例えば私立大学の医学部では、年間授業料が２,０００万円以上するという場合もあります。医者になって人命を救いたいという何か強い思いがある若者の場合、全額の負担をするということもあるのでしょうか。それとも、その一定の上限額の設定や学部の制限を設けることも検討されておりますでしょうか。","respondent":"こんの委員長、飛田子育て応援課長","answer":"先ほど、現在まだ制度設計中だという断りもありましたので、お答えできる範囲で結構です。お願いします。現在面接や成績等、また社会貢献等の活動も踏まえまして、授業料の一部を給付と考えております。その他についてはまだ検討中です。以上です。","voiceIndex":262,"id":"exchange-090"},{"speaker":"山本副委員長","kind":"提案","question":"今後、検討を進められるということで理解しております。その１００名を選考するための労力も相当にかかるのではないかとも考えます。ご提案としては、その１００名規模で所得制限なしでということですけれども、所得制限ありとなしと場合分けしてやっていくというのも、その目的に照らし合わせると一つ選択肢としてはあるかなということですので、こちらをご提案とします。ご説明ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":265,"id":"exchange-091"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"義務教育施設の整備基金についてお尋ねします。石田秀男議員が本会議で質問したのですが、その内容は少し置いておいて、改築を進めていっていただきたいという視点で質問をします。公共施設等総合計画によりますと、２０２４年から２０４３年の間に改築にあたる学校がものすごくたくさん表には出ていますので、そういうことを踏まえて、今後の流れをご説明いただきたいと思います。","respondent":"荒木学校施設担当課長","answer":"新規積立にあたりましては、予算編成の所管である財政課において、特別区税の剰余額、財政調整交付金余剰額などを原資に、充当先予算の必要額見込みを勘案して決定していると聞いております。","voiceIndex":268,"id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"基金の取崩しがそれほど令和３年、令和４年、令和５年は１９億円ですが、少ない中で済んでいるということなのですが、昨日も学校改築の補正予算に関する審査、金額の増加というのがありました。改築を進めていっていただきたいと思うのですが、今のペースでなかなか難しい状況なのかということだけ確認させてください。","respondent":"荒木学校施設担当課長","answer":"現在は１年につき１校のペースで学校改築を実施をしております。繰り返しになるのですけれども、既に設計に着手している浅間台小学校までについては、今後も引き続き継続して建替えに向けて事業を進めてまいります。","voiceIndex":272,"id":"exchange-093"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本当に財政として、いろいろな予算があり、他の所管の事業も多くなっていく中で、学校改築がなかなか進まないということのないように、ぜひ、先ほど１校と言いましたけれども、できれば１年に２校ずつ表の中の改築対象のところを進めていただきたいと思います。これは、要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-094"},{"speaker":"山本副委員長","kind":"質問","question":"私からは、高橋しんじ議員の一般質問の中での生徒による主体的な取組について、所管質問をします。浜川中学校の標準服の改定プロセスは、とてもすばらしいものだと私も思います。ご答弁の中で、区立学校全体でも生かせるよう好事例として周知してまいりますというお答えがございましたので、この周知の仕方についてお教えください。","respondent":"丸谷教育総合支援センター長","answer":"標準服の選定につきましては、校長・園長連絡会で共有するほか、生活指導主任会等で生徒指導提要についての理解を深めるための説明の際に、周知をしてまいります。","voiceIndex":276,"id":"exchange-095"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ＴＥＡＭＳで自主校長会の資料を保存されているですけれども、情報を引き出しやすい状況になっているかどうかをご確認をいただきたいと思います。常々、様々な区立学校の取組について呼びかけていらっしゃって、ご存じの方、学校関係者、先生方も多いとは思いますけれども、やはりそういう情報の取り出しやすさというところが大事かと思いますので、整備を進めていただくことを要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":280,"id":"exchange-096"},{"speaker":"高橋（し）委員","kind":"質問","question":"先生方に主体的に児童・生徒を取り組みさせるための研修というか、手法といいますか、どのような形で先生方に習得していただいているのでしょうかというのが二つ目の質問です。先ほど校長連絡会とかいろいろなところで周知するとありましたけれども、この点についても小中一貫教育の連携校の大きな一つの成果ではないかと思ったので、その点について、二つ目はそれについて、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"標準服の改定に限って申しあげると、浜川中学校はもう最後のほうになりまして、ほかの１４校は既に新しいといいますか、更新した標準服になっておりますので、今後、同じ取組というのは難しいのですけれども。","voiceIndex":282,"id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、私が一般質問したのにまた質問しまして申し訳ありません。今、お話があったように大変すばらしい取組ですので、ぜひ区内に広めていっていただきたいと思います。いろいろ形は変わっても、中学校の生徒たちが自分たちの未来のことを自分たちで決められてうれしかったとテレビでも言っていましたので、ぜひそういった学校が増えることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-098"},{"speaker":"山本副委員長","kind":"質問・要望","question":"好事例というのは、一言で言うとすごく短い表現ですけれども、やはりそこの本当にいいものというのは細かなところにあるのかなというのを思いましたので、まさにそういうものがちゃんと共有できるようなお伝えの仕方をしていただきたいというのが私の思いです。様々なところに好事例のヒントがあると思いますので、私からも改めてそういった意味でのご協力をお願いさせていただいて、追加での要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":286,"id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6915#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":89009,"voices":292}},{"id":"r06-20241126-5","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"総務委員会","time":"午前１０時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"給与等に関する条例の一部を改正する条例、(5)第１０４号議案、職員の給与に関する条例の一部を改正する条例および(6)第１０５号議案","agenda":"給与等に関する条例の一部を改正する条例、(5)第１０４号議案、職員の給与に関する条例の一部を改正する条例および(6)第１０５号議案","exchanges":[{"speaker":"西本委員","kind":"質問","question":"たしか、区長は２割下げたので、辛うじて副区長より低いというのは分かるのだけれども、本来だったらどのぐらいになるのか。これは減給したところの換算でやっているのですか。そこがよく分からないので、それを教えてください。それから、職員ですが、扶養手当の改定の配偶者等というところで、この配偶者等の「等」とは何ですか。それによって不利益を被る方はどれだけいるのかということを教えてください。","respondent":"勝亦総務課長、宮尾人事課長","answer":"２割カットの特別条例につきましては有効ですので、改定後、１１５万２,０００円になりますけれども、こちらから２割カットした給料月額になります。今、実際に配偶者に係る手当を受給している職員の数ですが、今年の４月時点で２２０名程度の職員が受給しているという実績です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"本則の区長の件ですけれども、すみません、計算機がないので、副区長のほうが多くなるということですか。それを教えてください。それと、「配偶者等」というところの扶養手当が２２０人いらっしゃるのです。２２０人の方は不満を言っていないですか。その分の財源を利用して、お子様がいらっしゃる方にということなのですけれども、これは廃止した分で賄えられるということになっているのか教えてください。","respondent":"勝亦総務課長、宮尾人事課長","answer":"改定後につきましては、１１５万２,０００円の２割をカットいたしまして、９２万１,６００円。改定後の副区長は９２万６,０００円ということで、こちらも副区長のほうが若干上回る形になってあります。扶養手当の廃止と子に係る手当ですが、委員お見込みのとおり、今回、扶養手当を廃止することによって生じる財源を用いて、この手当の増額に充当するという考え方になってあります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"これは、区長自らの判断なので、別にそれに対してどうのこうの言うつもりはないのですけれども、実態は分かりました。扶養手当の件なのですけれども、配偶者等の扶養手当も必要だったのではないかなと思うのです。どういう判断の下、ここを廃止したのか。もしも廃止せずに、現状の金額でお子様に対する扶養手当という形になると、どのぐらいの金額の差が出るものでしょうか。そこを教えてください。","respondent":"宮尾人事課長","answer":"細かな試算は、現時点ではまだできていないのですけれども、まず、考え方といたしましては、国も、今回、人事院勧告を出すに当たって、民間企業に調査した中で、そもそもこの手当を支給する制度を持っている会社の数が減少傾向にあること。","voiceIndex":12,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"私が思うに、今現在、大半の区民の方や、中小零細企業においては倒産・廃業など、本当に大変厳しい時期にあると思います。スーパーも値段を下げて何とか売上げを確保していこうという時期に、区民の生活を支える人たちの収入が増えて、支えられる人たちの収入が増えないということと、３年連続で品川区の行政関係者の給料がアップになるということは、私は問題であると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"反対で、少しだけご意見させていただければと思うのですけれども、先ほど、須貝委員がおっしゃられたとおりのところもあって、まだ区民の生活は大変というところがある中で、自らの報酬を上げるという改正案には賛成することができず、反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"賛成です。意見を述べします。ところが、この１年ぐらいの間に、どうも後援会で企業団体献金をもらっているという、私の信念からすれば、本当に背信的な国会議員がいるということが分かり、今、我が党の中も混乱している状況です。誠に申し訳ないことに、やや所属政党の考えの中で結論を出しているというところではあるのですけれども、そのような事情から、本件については賛成とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"もちろん、民間の方たちがまだまだ厳しい状況にあることは重々承知の上ですが、公務員の方たちも離職率が高くなっているところなども考えると、本件については賛成というふうに、これまでとは態度を変えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-007"}]},{"id":"topic-02","title":"第８７号議案、令和６年度品川区一般会計補正予算","agenda":"第８７号議案、令和６年度品川区一般会計補正予算","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今回、物価高騰ということで、それぞれ増額という形なのですけれども、何で今なのでしょうということです。タイミングはいろいろあると思うのです。現状として、基金の残高は今どのぐらいあるのですか。それと、債務負担行為の追加という形で、出ているのが一般財源なのです。本来は、支援が来てもいいのではないかなと思うのですけれども、どのような状況なのでしょうか。","respondent":"加島財政課長","answer":"その他にも特別養護老人ホームや介護サービス事業所、障害者支援施設等に関する物価高騰対策支援が組まれておりましたが、こちらは都が実施するもの、保育所につきましては区が実施するものということで、今回、都の補正予算の可決を受けて。","voiceIndex":69,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"結構高くなってきているのではないかなと思うのです。そのようなことになると、昨日もありましたけれども、物価高騰は大丈夫ですか。どうなのですか。そのような心配があるのですが、その見込みはいかがなのでしょうかということです。来年度予算の時期になってきているので、それを踏まえて予算を出しているのでしょうから、今の感覚的にどのような感覚を持っているのか、少しお聞きしたいと思います。","respondent":"加島財政課長","answer":"スクラップの財源を活かして、ビルドした新規事業を実施するというサイクルを回すことによって、財源を充てて運営できるようにしていきたいと考えております。","voiceIndex":71,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"行政側ではかなりいろいろ考えながらやられているなということは重々分かって、理解しているつもりでいるのです。これは、考え方としては理解できます。なので、今後、考えておられると思うので、私が言うものではないと思いますけれども、一応、財政は長期にわたって、検討も含めて見直しをしていただきたいとお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ。今回、物価高騰対策として補正予算が出ているということで、私はそれに対しては、本当にいいことだ。これだけ物価が高騰している中で、保育園などを支援していくことは大切だと思います。ただ、先ほども申し上げましたけれども、一方で、民間が大変なら、民間の支援として、同じような対策があるといいですねということを一言申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"すみません。１点だけ確認します。今回、都の補助金にすぐに品川区が対応されて、このように補正予算ということで対応いただきました。さらに、都の補助金の対象にならないところは、しっかり区が補充しているということで、それぞれの園については、大変助かることかなと思いますが、各園、幾らぐらいの補助金なのでしょうか。園によって違うのでしょうか。それだけ教えていただきたいと思います。","respondent":"加島財政課長","answer":"第３回東京都議会定例会で可決された補正予算のスキームにのっとって、今回、区の補助を行いますが、例えば、私立認可保育園でしたら、子ども１人当たり９５０円掛ける在籍人数ということで、１園当たりの補助が出てまいります。","voiceIndex":76,"id":"exchange-012"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"詳細は分かりました。６か月間の対応ということでありました。今後もよく状況を見ていただきながら、状況によっては、また都の補助金が出るようであれば、しっかり早めに活用していただくことをご検討いただきたいですし、それでも各園から足りないという声があれば、そこはしっかり区で対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-013"}]},{"id":"topic-03","title":"都市ブランディング推進に向けた取り組み","agenda":"都市ブランディング推進に向けた取り組み","exchanges":[{"speaker":"西本委員","kind":"質問","question":"報告会をしましたので、それを皆様に読んでほしいなと思うのですけれども、まず、一番私がどうなのだろうなと思うのが、ターゲットが未来の品川をつくる人たちなのです。今、品川区は人口が４２万人弱です。そこはどうなのですか。質問になっていないと思うのですけれども、これを本気でやるのですか。もう少し品川区独自のやり方を考えてほしいなと思うのですけれども、いかがでしょうか。","respondent":"與那嶺戦略広報課長","answer":"昨年実施した区民調査においては、２０年先を見据えて、２０年後の品川区はどんなまちになっていたいと思いますかというところや、２０年後の品川区はどんな暮らしが実現していたらいいと思いますかというところも質問の中に入れさせていただいています。","voiceIndex":91,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"区民アンケートもそうだし、ずっと全部一緒。だから、答えは一緒なのです。シティプロモーションのときのアンケート結果と、今回の都市ブランディングの区民アンケートの結果の差はあったのですか。こういうやり方だと、何のためにやっているのかも分からないし、メッセージ性があまりにも抽象的で、理解できないのではないかなと思うのですけれども、いかがですか。見直しを図るべきだと思います。","respondent":"與那嶺戦略広報課長","answer":"それは、今も都市ブランディングを進めていく中でも、品川区の魅力として持っているところです。","voiceIndex":93,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"ますます何だろうという疑問が出ている状況です。「品川だからできる『多様性の実現』」と言いますけれども、品川区でなければできないことは本当にあるのですか。なので、「都市ブランディング」ははやり言葉のようだけれども、とても大変なことだと私は思うので、これは慎重に計画し、慎重に進めていただきたい。それで、総務委員会には、その都度報告していただくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"ただ、そうは言っても、やってみようということなのであればやってみて、試行錯誤するというのは大事なのかと思うのですけれども、その中で１個、質問にしていったほうがいいと思うので、今の国家ブランディングと対比して考えていくと、では、都市ブランディングを考えていくときに、都市ブランドメッセージはまだ分かります。","respondent":"與那嶺戦略広報課長","answer":"どちらかというと、今回の都市ブランディングで考えていくのは、今、多様性の実現というお話で、ここも、これからさらに深めていく必要があるかと思いますけれども、そこを打ち出していくに当たって、今の考え方を具現化するようなロゴをつくりまして、品川区が目指す価値を。","voiceIndex":97,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"これは本当に何が正解というのはないと思うのですけれども、例えば、多様性というものを品川区のデザインにする。もう既に品川区のロゴというか、デザインがあるわけですから、先ほどから繰り返しております、国との対比で考えると、日本はとても安全だということをイメージしてもらう対象として、何かデザインがあるかといったら、国旗でいいような気もするのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-018"},{"speaker":"まつざわ委員","kind":"意見","question":"私も総務委員会で長野市へ行って、長野市はうーんということがあったので、本当に難しいのだなというのを痛感しました。それで、ターゲットが２０年後の品川区で、アンケートを行ったといいますけれども、無作為に抽出したのか、まず、そこを聞かせてください。","respondent":"與那嶺戦略広報課長","answer":"もう一個の個別のアンケートにつきましては、既に品川区内の様々な領域で活躍されている、こちらでも地域や文化、多様性、スポーツと書かせていただきましたけれども、そういった様々な分野で活躍されている方々にお話を伺うという形で実施したものです。","voiceIndex":101,"id":"exchange-019"},{"speaker":"まつざわ委員","kind":"質問","question":"私は、どちらかというと、先ほど、松本委員からもありましたけれども、メッセージ性は大事ですが、ロゴ・アートをどんどん進めていくよりは、しっかりとこういうものをやるのですけれども、どうですかという周知がすごく大事かなと思っています。それはもうなしなのか。そんなわけにもいかないではないですか。だから、そこら辺を最終的にというか、どのように考えていくのかなということを教えてください。","respondent":"與那嶺戦略広報課長","answer":"しっかりと区民の方々、地域の方々のご意見を伺っているところで、確かに先ほども言ってもらったように、それも含めて今回の調査を実施させていただいた。これも一つの声の蓄積だと思っています。","voiceIndex":105,"id":"exchange-020"},{"speaker":"まつざわ委員","kind":"意見","question":"大事なのが、やはり新しい血なのです。その閉鎖的な難しさ。なかなか町会で、もうやりきれないというのは私も痛感しているので、新しい血を品川区にどう入れていくか、どう循環させていくかということを、行政、または民間で考えていただいて、入れることによって何かそういった活性化が生まれるのではないかと思うので、そこら辺は私たちも頑張りますけれども、そこを重点的に考えていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"若者はどうなるのと思えば、若者の大半は、やはりお勤めをすると、地方に働きに行ってしまう。先ほど申し上げましたけれども、これは国の指示なのですか。今、ここで都市ブランディングに対して議論しても、区としては、今、進めるということなのでしょうから、いろいろなことを踏まえながら、私は推進するならやっていって、ぜひ総務委員会でも途中経過を話していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"都市ブランディングについては、ぜひ頑張っていただきたいと思っています。あえて「ステークホルダー」と書いてあるのですけれども、この意味や、何で書いたかを教えてもらいたいと思います。今後の予定のところで、指標をどうやってつくっていくかというのは、シティプロモーションでも課題だったかなと思っていて、そこをどうやっていくのか、今思っている課題感などを教えていただければと思います。","respondent":"與那嶺戦略広報課長","answer":"シティプロモーションも、いわゆる定住意向や愛着度といったことは取ってはいたのですけれども、今回、ブランディングでやっていくのは、イメージづくりでどういった愛着が持てるかというところになっていくので、今の時点でこの指標を使っていくというものは。","voiceIndex":110,"id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。先ほど、コミュニティの話もあって、そういったコミュニティづくりも課題だと思うのですけれども、地域の愛着から品川区への愛着という流れがイメージできないので、その辺がどういうイメージなのか教えていただきたい。","respondent":"與那嶺戦略広報課長","answer":"そこが、まさに来年度行っていくアクションにつながってくるかなと思っていて、それについては、検討が進んだ段階で、こちらでご報告をさせていただければと考えています。","voiceIndex":112,"id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"ご説明ありがとうございました。私たちも行政視察で長野市に行かせていただいて、いろいろと長野市の状況を伺っていく中で、難しいなということも感じましたけれども、今年度、品川区は広報広聴課を発展させて、区長室戦略広報課を立ち上げて、その中に都市ブランディング担当ということで専任で何人かいらっしゃるのでしょうか。","respondent":"與那嶺戦略広報課長","answer":"もう一人、民間会社から出向派遣で来ている者がおりまして、その２名で、今、都市ブランディングの活動を進めている形で、まさに業務としては、都市ブランディング推進に向けた様々な検討や準備を行っているものです。","voiceIndex":116,"id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問","question":"もう少しこの民間会社の方の状況をお聞きしたいのですが、こういう都市ブランディング、広報などの経験がある方なのか。長野市では、このステークホルダーが結構キーポイントになっていて、元広告代理店の方もいらっしゃったなということがあるのですけれども、民間会社から品川区に来られている方は、どういう経験があるのかというのを少し教えてもらってもいいですか。","respondent":"與那嶺戦略広報課長","answer":"失礼しました。少し説明が足りなかったので、補足します。","voiceIndex":118,"id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"住みやすい地域で、近くで買物もできる、病院もある、介護施設もあるという中で、地方ではなかなかそれができなくて、都心に返ってくるという動きもある中で、品川区をどう選んでいただけるのかということはすごく大事だと思うのです。今現在のロゴ・アート策定の推進状況をもう少しお知らせいただくとともに、分かりやすいという視点でのお考えをお聞かせいただきたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ロゴとアートの推進状況は、まさに今つくり上げている最中でございまして、今年度中にしっかりとお披露目できるように準備を進めている最中です。ご意見を頂きました分かりやすさという点は、我々も大事かなと思っています。","voiceIndex":120,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"すみません。もう一つ。しつこくてすみません。心配というか、いろいろ議論を聞く中で、３２名の方に対面インタビューや書面アンケートを取っているのです。だから、多分、都市ブランドはそれなのではないかなと思うのです。これは非常に難しいので、聞いた意見は、どのように活用するのですか。そうなってくると、やはり引っ張られやすいのではないかなと思うのですけれども、そこはどうでしょう。","respondent":"與那嶺戦略広報課長","answer":"今回、昨年末に実施したアンケートは、３２名の方にお話を伺ったのですけれども、あくまで、ここでは品川区の魅力や、先ほど申し上げたように、２０年後にどういったまちになってほしいかという思いを伺ったような形ですので、そこで出てきた内容を集約というか。","voiceIndex":123,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"ロゴ・アートについて、これは長野市もそうだったのです。だけど、それはそれとして行政の判断で、私たちもそれに賛同する形で、賛同が大きければそうなっていくのでしょうけれども、もっと地域を大切にしてほしいなと思うのです。長野市の縁というのは、とても分かりやすい。そういうことはしないでほしいのです。本当に税金の無駄遣いだと私は思いますので、その辺の税金の使い方はいかがですか。","respondent":"與那嶺戦略広報課長","answer":"そこについては、まさにこれから検討して、後で報告するです。一方で、今回、都市ブランディングでは、何度も申し上げておりますけれども、区からの発信だけではなくて、様々な方に使っていただくというところも目指していくところです。","voiceIndex":125,"id":"exchange-029"},{"speaker":"西本委員","kind":"意見","question":"広報するために莫大な税金をかける。これは、一つの考え方なのです。でも、私は、そこまでやる必要があるのかということと、やはりそこはきっちり私らも議論しなければいけないなと思っていますので、決して無駄に使うことはしないと思いますけれども、そこを意識して、大切な税金なので、本当にお願いしておこうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-030"}]},{"id":"topic-04","title":"続きまして、(2)「デジタルプラットフォーム」を活用した区民意見募集の試行","agenda":"続きまして、(2)「デジタルプラットフォーム」を活用した区民意見募集の試行","exchanges":[{"speaker":"西本委員","kind":"質問","question":"「デジタルプラットフォーム」なのですけれども、これは具体的にどのような感じなのでしょうか。実際に見ればいいのでしょうが、どういう場なのかをもう少し詳しく教えてほしいのですが。","respondent":"與那嶺戦略広報課長","answer":"こちら、資料にも記載しているのですが、いわゆるインターネット上に設けられる様々な投稿ができる「場」という形で、今回に関しては、PoliPoliという企業のサイトを利用させていただいて、そこで、いわゆる品川区の意見募集ページを設けて。","voiceIndex":134,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"すみません。あまりよく分かっていません。要は、民間のサイトに入るような形なのですか。従来品川区もホームページから入ってもらって、メールとかを使っていましたよね。そういうサイトに入っていって、意見を発信するというか、それと何が違うのですか。","respondent":"與那嶺戦略広報課長","answer":"今回そのサイトを使った理由としては、実際に投稿内容であるとか、結果の分析であるとか、今回で言うと、いわゆる投稿内容をしっかりとチェックして、例えば誹謗中傷であるとか差別的な表現とか。","voiceIndex":136,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"そこから飛ぶという形でサイトに入ってきて、要は、そこでいろいろな分析とか、あとは不適切な用語を使っていたらそれを削除するとか、そういうもののサービスを利用しましたということですか。今までは、内部でやらなければいけなかったことを外部のサイトを使うことによって、それを縮小できたということなのでしょうか。品川区にとって何のメリットがあるのですか。","respondent":"與那嶺戦略広報課長","answer":"今、区ホームページからリンクで飛ぶというのもご案内させていただきましたけれども、ほかにも品川区では、ＸやＬＩＮＥなど、様々ＳＮＳを持っていますので、そういったところで定期的に「こういった募集をやっているので、ぜひ利用してください」という発信を行いまして。","voiceIndex":138,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"朝ご飯もそうではなかったですかね。朝ご飯提供もそういう形でと言うのだけれども、それは１つの手法ではあるにせよ、でも本当にそれがいいのかということを最終的には区の職員の考え方が必要になってくる部分があるので、今後これはどういう活用をしていくのですか。その辺と、それからデジタルの活用方法についてのお考えをお聞きしたいと思います。","respondent":"與那嶺戦略広報課長","answer":"今後に向けて、より意見をしっかり多くの方からいただくであるとか、それを区の行政に活かしていくというやり方というのを、ここは今回の成果などを踏まえながら、引き続き検討していくという形で予定しているものです。","voiceIndex":140,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、その決定をするときに、ここは１つの意見という形に過ぎないと私は思っているのです。なので、どう総合的に判断をこれからしていくのかという形は、ぜひしっかり理解した上でやってほしいなと思います。これからいろいろなものが出てくると思うので、流されない状況で見極めるというのは、ぜひお願いしたいなと思いますので、よろしくお願いいたします。次の１月の報告を楽しみにしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"それを使われたというのは、今回１つの取組だと思うのですが、その中で、私PoliPoli Govの費用がどのくらいかというのはいまいち分かっておりませんで、今回の費用がどのくらいだったのかというところを教えていただけますか。","respondent":"與那嶺戦略広報課長","answer":"今回のPoliPoli Govを活用した際の費用なのですけれども、６０万５,０００円です。","voiceIndex":144,"id":"exchange-036"},{"speaker":"松本委員","kind":"提案","question":"その辺りはどのような提案を受けていらっしゃるのでしょうか。","respondent":"與那嶺戦略広報課長","answer":"ただ、今後に向けましては、そこも含めて、こういったサービスを行っている事業者、様々あろうかと思いますので、いわゆる件数ごとでやっていく形にするのかも含めて検討していきたいと考えています。","voiceIndex":146,"id":"exchange-037"},{"speaker":"松本委員","kind":"質問・要望","question":"多分こういう政策共創プラットフォームですか。自分も品川区に住んでいるから、意見してみよう」みたいな、こういうふうな、必ずしも品川区のホームページなどを見るだけではない人からの意見というのが、当然として得られるというのも１つのいいところなのかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-038"},{"speaker":"まつざわ委員","kind":"意見","question":"私もデジタルプラットフォームは分かっていなくて、問題点、課題というものをいろいろ調べたら、結局大量のデータが来るからセキュリティプライバシーの管理が相当大変ではないかというものがあるのですけれども、これはPoliPoliがそういうものも全部やっていくというので、まず合っているのか聞かせてください。","respondent":"與那嶺戦略広報課長","answer":"それも含めて、今回あくまで試行という形ですので、今後に向けてはどういったものがいいかというのを検討していきたいというものです。","voiceIndex":150,"id":"exchange-039"},{"speaker":"まつざわ委員","kind":"質問","question":"私もこれはすごくいいことだなと思って、それこそ先ほどの話ですが新しい血が入ってくるということでは、とても期待しているところがあって、あと教えてほしいのが、従来の広聴方法の中で、結局電話とかメールとかがあると思うのですけれども、結局そのオールドタイプといいますか、デジタルではない古いタイプの意見というのも、この「デジタルプラットフォーム」に反映させて。","respondent":"與那嶺戦略広報課長","answer":"これまで行っていきた、いわゆる既存の意見の取り方というと、それはそれで大事に使っていきたいと考えています。当然電話やメールを主に活用されている方。","voiceIndex":152,"id":"exchange-040"},{"speaker":"まつざわ委員","kind":"意見","question":"ごめんなさい。勘違いしたのか、この「デジタルプラットフォーム」に入れれば、要はそういったいろいろな集約した意見を羅列してまとめられるので、例えば電話とかの対応も全然ありでいいのですけれども、そういう電話対応の意見などもこのデジタルプラットフォームに合わせたら、それがまとまるのかなと思っていたので、そういうものではないということですね。","respondent":"與那嶺戦略広報課長","answer":"そういったやり方はあるのかなとは思います。そこも含めて、我々も今やりながら研究しています。","voiceIndex":154,"id":"exchange-041"},{"speaker":"まつざわ委員","kind":"意見","question":"「デジタルプラットフォーム」の課題の１つで、情報格差、電話しかできない人というのは、少なからずいらっしゃるので、そういった声もデジタルに落とし込んでいただければ、ありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"今、あまり詳しくは私も理解できなくて、すみません。１点だけですが、最初にお話ししましたけれども、「デジタルプラットフォーム」に入れない方というのですか。そういう方たちの意見というのは、どこかで拾えるような手法は、また別に考えていくということなのですか。あまりよく理解していないので、教えてください。","respondent":"與那嶺戦略広報課長","answer":"「デジタルプラットフォーム」、なかなか利用が難しい方についてのご質問です。","voiceIndex":158,"id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"特に若い層やファミリー層や子どもが参加できるものというのと、防災訓練で新しくそういった方たちも参加できるような新しい訓練内容ができてきた中で、ファミリーとか若い世代をターゲットにアンケートをするときに、もともと参加されている町会員などの方たちからはある程度その現場でもアンケートが取れたり、町会を通じてアンケートが取れるというところと。","respondent":"與那嶺戦略広報課長","answer":"特に若い世代が来てくれないだとか、ファミリー世帯にもっと来てほしいというところの防災課のニーズともマッチしたところがあって、防災課と協力しながら、試行実施を行っております。実際に、ではどういった方から声をいただいたかというところ。","voiceIndex":160,"id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"参加したとかというところ、PoliPoliを見ると、訓練に「参加したことがある」「知らない（参加したことがない）」「知っているが参加したことがない」とかというところで、そういったところが興味深かったと伺ったので、そういういろいろな視点を持ってこれを使ったということがよく分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"最後に意見だけ。多分今日どういうものか分からないという委員の方も結構いらっしゃったかと思うので、ほとんど答えまで私のほうで言います。逆に言ったら、年齢などは今オープンになっている情報では出てこないので、その辺りも皆さんに告知していただけるとありがたいと思うのですが、いかがでしょうか。","respondent":"與那嶺戦略広報課長","answer":"今後その辺りの報告を、準備が出来次第予定しておりますので、そういった中でご確認いただけるようにしていきたいと考えています。","voiceIndex":163,"id":"exchange-046"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"他自治体から比べると、数は多かったということで、報告がありました。今後また様々展開を検討していくということなのですけれども、何かこういうところが効果的に、こういうテーマであれば、このプラットフォームというものが効果的なのではないかというのを、区として、何か考えていらっしゃることがありましたら、教えていただきたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ここがまさに今検討しているさなかというところでございまして、具体的にはこのテーマと申し上げる材料はありませんが、多くの方に関心を持ってもらえたり、より積極的に参加してもらえるような観点を持って、テーマ選定に臨んでいきたいと考えています。","voiceIndex":167,"id":"exchange-047"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"さんざん私も言いましたけれども、さんざん品川区でそれを意識してやっていたわけではないですか。１７項目のうち何をするのですかということです。あっちこっちやっていて、もう何を求めているのか全然分からないのですよね。品川区でやってきていたではないですか。だったら、１７項目のうちどこですかということです。これは違うのではないですか。このＳＤＧｓで何をやりたいのですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回の未来都市計画という形で、そういったものを束ねて計画化しているところではありますが、富山市の方のご説明と通ずるところもありますが、「ゴール１１、住み続けられるまちづくりを」というのは、我々自治体の行政職員にとっては究極的な目標であると捉えております。","voiceIndex":173,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"１７番ですか。だから、これからＳＤＧｓをやるにしても、お互いに連携をどういうふうに取っていくのかということを、やはり庁舎の中で議論すべきなのではないかなと思うのです。これがもともとある意味というものを、もう一度見直してほしいなと思いますので、意見として。それと、間違えないでほしいのですよ。先ほどの理由で言うのであれば、働き方改革ではないですか。だけれども、今逆行ではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"どちらかというと、しながわシティラボと大きいものがあって、その中にしながわＳＤＧｓ共創推進プラットフォームを入れているのか、それとも完全に別だけれども、ホームページは包含関係になっているのか、この辺りの位置づけが少し分からないので教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"そこで、上がった課題ですとか、あとは区の中からも上がったような課題などを、インターネット上で、区内のステークホルダーだけではなくて、区外の企業や大学なども含めて発信していくサイトとして、しながわシティラボを立ち上げておりますので、並列といいますか。","voiceIndex":177,"id":"exchange-050"},{"speaker":"松本委員","kind":"確認","question":"私なりに解釈すると、まずプラットフォームが組織といいますか、存在としてあって、そこでいろいろな課題とかを出して、その課題を解決するための１つの手段として、インターネット上でラボを作ってやっているという理解でよろしいか。ここまで確認させてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"お見込みのとおりです。手段の１つとして、しながわシティラボをインターネット空間に立ち上げたという位置づけです。","voiceIndex":179,"id":"exchange-051"},{"speaker":"松本委員","kind":"提案","question":"その課題解決の方法で、しながわシティラボのほうが実証実験型と課題解決型があって、課題解決型は多分品川区側から課題を出して、いろいろ募集していくと。もう少し分かりやすく言うと、民間企業が売上げを上げるために、今回区が場所を提供しているというふうに、見え方としては見え得るのではないかと思うのですが、これは区としては特に問題ないという考えなのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"もう１点、場所の提供については、企業が売上げを上げるために、区が場所の提供をしているというような見え方もできるというご指摘ですが、その辺り含めて、区の社会課題の解決につながるかどうかですとか、区民サービスの向上につながるですとか。","voiceIndex":181,"id":"exchange-052"},{"speaker":"松本委員","kind":"提案","question":"社会課題を解決するというふうに何となくつくっておきながら、今回は絶対ないとは思いますけれども、例えば行政とか政治とかとある程度つながりが深いところにそういうものが認められやすくなるということが起こると、それはよろしくないので、あくまで社会課題を解決するというところに、ちゃんと焦点を当てた判断が、審査がなされるというのが大事だと思うのですが、この実証実験型の提案について。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"真に社会課題の解決に資するものかどうかというところを、所管と企画課のほうである程度検討した上で、実証実験に至るという経緯です。","voiceIndex":183,"id":"exchange-053"},{"speaker":"松本委員","kind":"提案","question":"ただ、そうした中で、今回のマチルダの提案は、結構価値に入り込んでいるところなので、先ほどのお話もありましたけれども、これは行政がやるべきことなのかという価値もあるとは思うのですが、実証実験を推進して、課題を解決していくという方向性はとてもいい方向性で、今、品川区がそれを特別区と横並びだけではなくて、かなり今、前を走っているというのはとてもすばらしいことだとは思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-054"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"だから子どもたちに「ご飯を残すと片づけるのが大変だから、ご飯はしっかり食べようね」とか「残したら自分たちで洗おうね」とか、うちもぜいたくに食器洗い機を買うようになってしまったものですから、少しでも一緒に洗わなければと思いながら、それで一緒にやりながら食育になったり、そこで子どもの話を聞いたりというのに、私はそういう食のすばらしいものがあると思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-055"},{"speaker":"須貝委員","kind":"質問・要望","question":"今まで、皆さんのお話を聞いていて、西本委員が言うのもやはり筋が通っているし、課長の言うことも別に間違いではないと私は思います。皆さんそれぞれ違うのですよね。結局、様々な生活環境や様々な人間性がある限り、品川区への要望。ではよそから取ろうかという話にもなる。今後もどこまで進むのか、どういうふうに変わってくるのか。総務委員会で途中経過をお知らせ願えれば、ありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-056"},{"speaker":"大倉委員","kind":"提案","question":"いろいろ伺って、大きくは分かりました。１個気になっているところで、しながわシティラボでの実証実験提案型というのは非常にいいなと私も思っていて、いろいろな提案を受けて、いろいろな実証実験をしながら、スクラップ・アンド・ビルドではないですけれども、いろいろやってみて、これはもう少し課題があるね。これはもう少し進めてやっていきましょうという判断ができていいなと思っています。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回、提案の中に、区の中にステーションという場所を設けて、オンラインではなくて、オフラインでそこで子どもたちとのタッチポイントとして、そこを少しにぎわいの拠点にしたりですとか。","voiceIndex":188,"id":"exchange-057"},{"speaker":"大倉委員","kind":"提案","question":"いろいろないい提案があったときには、その提案が実現できるような環境をどうやってつくっていこうかとか、どういう場所があるかとかというふうに探していくというような流れになるのですかね。タッチポイント。そういう場所については、品川区は、今回大崎の夢さん橋を提供するけれども、その後のタッチポイントのオフラインでのというところまで、場所の確保みたいなのを考えているということなのですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"例えばクイズだったり、イベントをその場所で展開するというような提案内容でございまして、現在ほかの先行しているステーションでもそういった企画を実施されているというところで、顧客だけにとどまらない地域の子どもたちとの接点にもつながるという提案でございましたので。","voiceIndex":190,"id":"exchange-058"},{"speaker":"大倉委員","kind":"提案","question":"すみません、細かくいろいろご説明いただいて、ありがとうあります。そういうことであれば、同じような業界の事業者とも全然違うというところでは理解しました。場所も指定して、提案がされるのだなという、そういうのも含めて、経緯が分かったので、引き続きいろいろな提案を受けていただいて、ぜひ頑張っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-059"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"場所の提供ということでのご案内で、区の予算的負担はないということですね。本格運用をこの場でされるためにはどういう成果があればできるのかとか、それとも、いや今回だけで終わってしまうのだとか、今後の展開について少しお聞かせいただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"実証実験の３か月が終わった後の判断基準ですとか、継続の可否の観点についてのご質問かと思います。","voiceIndex":196,"id":"exchange-060"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"分かりました。株式会社ということもあるので、営利を求めていかなければいけないというお話がありました。今回この大崎で出されているここの利用者は、品川区民限定であるのでしょうか。多分そこはそうではないかなと思うのですけれども、区民限定なのかどうか。ほかの地域の人がここを指定して取りに来るということもあるのではないかと思うのですが、確認させてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"まだ定性的な定量調査はアンケートなどを取っていないのですけれども、マチルダの実証実験を開始してからのは反応としては、品川区にお住まいの方で、これまでは東京駅ですとか大手町の辺りにもステーションがあるのですけれども、そこで受け取っていたお客様が。","voiceIndex":198,"id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問","question":"ぜひ、今回の実証実験の結果を受けて、継続できる方向であれば、こういう場の提供は必要だと思いますので、引き続き継続をしてもらえたらなと思います。この次の実証実験の、マチルダに続く第２号、第３号の動きというのは、どういう状況でしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"しながわシティラボの今後、マチルダに続く第２号、第３号の現在の進捗状況ですが、現在課題解決型のほうで、複数企業から提案を受けて、所管等の調整、まだマッチング過程にある提案が複数ありますので、そちらがうまくいけば。","voiceIndex":200,"id":"exchange-062"},{"speaker":"まつざわ委員","kind":"質問","question":"ステッカー、これはすごくかわいいものができてすごいなと思って。私、ごめんなさい。勝手に区長たちが決めたのかと思ったら、小学生が最後選考でみんなで選んで投票でと言ったのですが、投票は小学校全部でやっていたのか、無作為で選んだ方に選んでもらったのか、それだけ教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ＳＤＧｓステッカーのデザインの決定に至る投票についてですが、投票については、投票期間の９月２１日から１０月４日の間、電子申請による投票をまずメインで行いました。","voiceIndex":202,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"すみません、１個。今までの議論を踏まえて、この課題は何だろうということと、その課題を解決するために、この株式会社マチルダを選ぶというのは、誰が中心になってやっているのですか。誰が決めるのですか。決めた人を知りたいです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"しながわシティラボのマチルダの決定に至った、決定した者は誰かというようなご質問であるかと思います。提案については、私ども品川区の企画課のほうで受けまして、事業者ですとか、関係する所管なども交えて決定をいたしました。","voiceIndex":205,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"品川区の子どもたちをどうしていきたいのかという、それが果たして今の役所の中でどういう認識を持っているのですか。ここだけの説明だと、こども会議において、家族と過ごす時間がもっとあるとよいということから、この解決策として、これになったではないですか。それを決めるときに、子どもたちが言っていること、必要としていることというのをもっと深く考えてほしいなと思うのですよ。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、今回の実証実験を通して、本当に子どもたちが親子で過ごす時間が増えたり、食の選択肢が増えるというところにつながるのかどうかといったところは、実証実験の中できちんと見極めていきたいと考えております。","voiceIndex":207,"id":"exchange-065"},{"speaker":"西本委員","kind":"意見","question":"指標になる、評価するという何かしらあると思うのですよ。数量的なところもあるかと思うのですけれども、思いであったり価値みたいなものですよね。行政としてこういう方向で行こうね、こういう方向に行ったら数が多くても希望者が多くてもやめようねというそういうものがないとおかしいと思います。極端な言い方かもしれないけれども、ネグレクト。いろいろ提供する側があるから。どうなのでしょう。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"特に今回、保護者にとっては家事負担の軽減につながるものではありますが、品川区こども会議での子どもたちからの意見なども重視いたしまして、子どもにとってのメリットが強いものであるということが確認できなければ。","voiceIndex":209,"id":"exchange-066"},{"speaker":"西本委員","kind":"意見","question":"でも、それをすることによって、大切にしなければいけないことがなくなってしまうということを、品川区としてはやるべきではないと私は思います。それが、品川区の子どもたちをどうしていくのか、親たちをどうしていくのかということにつながっていくのではないかなと思うのです。見直しを図るべきところについては見直しを図ってもらいたいと思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6923#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":64497,"voices":218}},{"id":"r06-20241126-10","meetingId":"r06-cm11","date":"2024年11月26日","dateIso":"2024-11-26","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6933#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2849,"voices":17}},{"id":"r06-20241127-14","meetingId":"r06-cm11","date":"2024年11月27日","dateIso":"2024-11-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、先ほどの説明で、新たに冒険ひろば、あとキッズプレイルームが用途に入ったということで若干説明がありましたが、入れることになった議論の経緯なども含めて伺いたいと思います。マイスクールが今まで適応指導教室という名前だったと思うのですけれども、何か違うところがあるのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらはワークショップの方でも昨年度、実施した中でも、こういった施設が欲しいとあったのですけれども、主としていたしましては、今年度、庁内検討会を開催いたしまして、有識者からこういった子どもから高齢者まで全ての交流を促すのであれば。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"サウンディング調査も行ったということで、何社が来て、どういったところから申し込みがあったのかも伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"２点目の障害者就労支援へのご質問ですけれども、委員、お話のとおり、こちらは図書館ですとか体育館、あとは会議室の受け付けとか、いろいろところで障害者の方も含めて活躍できる機能がありますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは意見を述べておきたいと思います。そうなると今、能登半島でも注目されましたトイレの問題があると思うのですが、もちろん耐震トイレだと思いますが、そこの確認と、あとトイレの数、女性を男性の３倍にするというのがスフィア基準の中でもありますので、そうした整備、計画を進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"トイレ等の考え方については、区民避難所の機能から照らし合わせて考えていくところもありますので、引き続き、検討させていただければとあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"トイレのところでは引き続き検討ということですので、マンホールトイレなども検討するということで書かれておりましたので、マンホールトイレはしっかり水道直結式というのですか、ため置き式ではなくて、流せるマンホールトイレにしていただきたいと思いますし、トイレの数も女性は男性の３倍ということで、検討を進めていただきたいと思います。これは意見を述べておきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"２点目の日程ですが、オープンハウス方式の説明会ですけれども、こちらが１２月８日の旧荏原第四中学校のほうですけれども、こちらは１０時から１５時の間で、旧荏原第四中学校での実施、１２月１３日のエコルとごしについては、少し来館者の方がいらっしゃる午後、夜間。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"事業内容の精査というのはどういうことをするのか。","respondent":"吉岡政策推進担当課長","answer":"来年度以降、サウンディング調査を実施いたしまして、こういった部分の計画の中身をさらに具体化していくという作業が事業内の整理というところですので、今、定めた機能がなくなるとかそういったことを検討しているものではございません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"図書館についてお話がありましたけれども、ぜひ図書館、他のところを、ここでいうとゆたか図書館をなくさないようにしていただきたいと思います。そして、そういったことも含めて、区民の方の意見をよく聞いて、それを反映させて進めていただきたいと、これを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"整備運営手法のところで、幾つか詳しく伺いたいのですけれども、従来方式とＤＢＯ方式とＰＦＩ（ＢＴＯ）方式ということで、結論はもうこのＢＴＯ方式を採用する方向で検討を進めるとなっているのですけれども、まず従来方式との比較で、ＤＢＯ方式とＰＦＩ方式の違い、この応募グループ全体と基本契約を締結して共同事業体にまとめて発注というのがＤＢＯ方式であって。","respondent":"吉岡政策推進担当課長","answer":"２点、大きくご質問いただきました。ＢＴＯ方式をこちらで検討したですけれども、大きく２点、違いがあります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"それで定量的評価では、これは建設費用も含んだ上でということなのですけれども、たしか以前のこの委員会の中で、同じようなＳＰＣを使って、広島のまるくる大野というところがやっているというようなことはたしかご説明を受けたと思うのですが、そこでの運営について、先ほど、別の委員からも質問がありましたが、いわゆるかなり民間寄りになるというイメージがあるのですが、そこでのサービスについて。","respondent":"吉岡政策推進担当課長","answer":"次年度以降、こういった事業内容の整理もございましたけれども、いろいろな民間事業者のサウンディングをしながら、そういったリスクの部分も含めて、しっかりとどういったところを効果としていくか、モニタリングしていくかも突き詰めて検討していくというところと、対話。","voiceIndex":18,"id":"exchange-008"},{"speaker":"山本委員","kind":"提案","question":"私からも幾つかご質問します。検討が一歩進んでいるということを理解いたしました。施設ゾーニングプランについて伺います。現状、こういったゾーニング案をお示しいただきましたが、これは一案というか現時点の案ということで、民間事業者の方からの提案で、また違うものが出てきたら最終的に変わるということもあるのかというところを、少しお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"今、委員から確認がございましたとおり、これはあくまで一例ですので、こちらが求める機能、役割といった部分を備えたご提案であれば、変わったゾーニングプランに変わるというところが今回のテーマです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"次に整備運営手法に関してご質問します。先ほど、他の議員からのご質疑もございまして理解が進みました。具体的に言うと、利用者側の負の単年度の費用負担が高まるのかなという。逆に長期にならせば、それが単年度の負担が減るのかなという関係があるのかなと理解しておりまして、この期間の考え方、それからサウンディング調査等でそれをお聞きしているのであれば、その点をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"事業期間の１５年という想定といいますか、こちらで考えさせていただいたというところなのですけども、これもいろいろな複合施設のＰＦＩ、債務負担を調べてみますと、大体１５年から２０年と言われているところです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。もっと長期間、当然使い続ける前提ですし、その後も契約が続く想定ながら一旦、１５年や２０年の区切りで見直そうということだと理解をいたしました。それから、こちらはＰＦＩ手法として考えるとＰａｒｋ－ＰＦＩは別法令に基づくものだとして除くとすると、区としてのＰＦＩとしての取り組みは初だという理解ですけれども、それでよいでしょうかです。","respondent":"吉岡政策推進担当課長","answer":"はこのＰＦＩにつきましては、今回、初めてというところもありますので、Ｐａｒｋ－ＰＦＩはまた別としてというとこですけれども、ＰＦＩ事業といたしましては初めてですので、他自治体の事例も参考にしながら。","voiceIndex":25,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"理解が進みました。品川区のＰＦＩとしてぜひ進めていただきたいと思いますが、区民の利用料の負担でしたりとか、そういったところへの考え方になるのですけれども、ここは特段ＰＦＩ手法を使って、民間事業者が長期で契約ベースとなるということで、従前手法と比べて区民の利用する方々の負担がそれに比べて上がるということではないということでよいでしょうかということを、念のため確認させてください。","respondent":"吉岡政策推進担当課長","answer":"一方で、新たに入る機能については、どういった民間提案があるかというところで、そこでどう収益を取っていくのかということは、逆に指定管理料がこちら、区として下げられる部分もありますので、そういった部分については今後、区民負担の部分と。","voiceIndex":27,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ民間の事業者の皆様の創意工夫を取り入れながら、区民の皆様の負担も軽減が図れるよう、ぜひそのバランスをとりながらよい施設となるよう、検討を進めていただきたいと思います。最後に、区民の皆様からの意見の募集や聞き取りというところについて伺います。区では、１０月からデジタルプラットフォームということで、防災訓練に関するアンケートを新しい取り組みで実施されています。ご意見を伺います。","respondent":"吉岡政策推進担当課長","answer":"今後も広く意見を聴取するため、ご案内のものもありますので、今年度に関しましては、なかなかもう実施が厳しいかというところがあるのですけれども、次年度以降、区民の皆様の意見を聴取するいろいろな手法をこれからもまた研究していきたいと考えております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"つる委員","kind":"確認","question":"資料１とか２を拝見させていただいて、各委員の質疑で理解しておりますが、コンセプトとかそれから導入機能の素案がいろいろ出ていて、これを一体の施設としてやるということで、資料２の１１ページには、これまでも様々な委員会で確認等がある部分で創発が促されるというのがあると思います。それこそ障害の有無の部分についても、いろいろなそういう機会をつくってきた。","respondent":"吉岡政策推進担当課長","answer":"非常に頭を悩ませるご質問のところでございまして、まさにこれはこのＳＰＣを設立して契約するという段のところに行くまでに、しっかりと検討しなければいけないところでございまして、それがある種、事務事業評価という言葉もありましたけども、まさに評価。","voiceIndex":32,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"そうすると、施設は一緒でもそれぞれの事業での評価というのはでこぼこが当然あって、ではそれをどう関連づけていくかという。まだ期間があるわけですけれども、その辺をしっかりと設定して、ここでいることでどういう、まさにこの創発という言葉が資料の中にはあるわけですけれども、そこのところは一定、明確にしないといけない。そこのところだけもう１回確認をさせていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"例えば図書館には来館者数がいっぱい来ているけれども他のところの稼働率が少ないというところであれば、そこに何が足りないかしっかりと検討していく必要がありますので、それぞれの数値を図っていく、効果を図っていくというのは非常に大事かと考えています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"センシティブだなと思うところなので、先ほどゾーニングの話もあったわけですが、この辺りも含めて、その辺のまさにつくりによる、ハードによるその辺の一番快適なゾーニングのやり方があると思うので、そこも含めて先ほど言ったような、最終的な施設全体としての目的価値、アウトカムだとかそうしたところ、それは区の課題のどういうとこに資するのかというようなこともしっかりと明確に今後して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば今回、この旧荏原第四中学校がこの施設を開放するに当たっては、今までの区有施設とは違う、ちょっと特例の形で、この旧荏原第四中学校においては体育館も含めて全てが平等に、誰もが使えるような、高齢者であっても、若者でであっても、子育て世代であっても、そういう特例的なそういう施設ができたら、より多くの方の利用が誰もが平等に、期限的にも３カ月前。","respondent":"吉岡政策推進担当課長","answer":"こういった体育館あるいはほかの諸室の使い方につきましては、まだそこまで実際ルール決めというのは当然、先の話になるところですけれども、やはり目的としては、交流あるいは区民の皆さん使っていただきたいという、あくまでも区有施設、区立施設にはなりますので。","voiceIndex":37,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"幾つかお話を伺います。２つあると思うと言っていた。１つは成績にすごく特化する中高一貫校。近隣の区民の方のご意見というのはすごく分かるけれども、それは非常に行政のよいところでもあるし、私は少しうーんと思うところもあるので、ぜひそこら辺もご理解いただいて、ぜひよい方向の施設になっていただければなと思っているので、何か今、私が話したことで、思いとか意気込みがあれば伺いたい。","respondent":"吉岡政策推進担当課長","answer":"先ほど、基本的な使用、利用については他の区有施設と同様にしっかりと安価な、あるいは無料で使っていただくところもありますけれども、その中でどういった収益を生み出せるかといった部分は民間の手挙げにもつながるかと思いますし。","voiceIndex":39,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"地域の方々もそれぞれご意見をお持ちだと思うので、これはよかったのか、悪かったのか分からないけれども、エコルとごしのときにも、カフェを入れてほしいという話が相当あった。せっかく食事がとれるとか、ちょっと何かお弁当とか持ってきても食べられるというのは相当やったけれども、そのときに役所の方々は、やはり地域からの反対があったものですからこれは置けませんといって、結局なくなった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"要望も併せて質問させていただきたいと思うのですが、まずワークショップをされた中で、大崎高校の皆さんの声がとてもリアルでよいなと思ったのですけれども、自習室が整備されれば、確かに学校が使えない時間帯とか放課後の活用で、生徒・児童が大変集まってきてくれるだろうなというイメージを持っております。","respondent":"吉岡政策推進担当課長","answer":"資料１の一番下の部分のところですけれども、現状、冒険ひろば、公園内に設置されているところがあるのですけれども、ただ、公園内に訪れる高齢者の方があそこの公園を通ったときに、冒険ひろばで遊んでいる子どもたちを見て、楽しそうだなということで、実際、声をかけたり。","voiceIndex":42,"id":"exchange-020"},{"speaker":"西村委員","kind":"質問・要望","question":"もちろん、これから時間がある中で議論を進めていただくことになると思いますので、１点だけ、これは要望でさせていただきたいのですが、障害者の方の受入れを積極的にしていくという中で、ソフト面ではありますけれども、障害者の方の視点で仕事をつくり出していくということも必要だろうと思いますので、様々な特性に合わせた職業訓練ですとか。","respondent":"吉岡政策推進担当課長","answer":"自習室におきましても、大崎高校の生徒のワークショップでもございましたとおり、やはりそういった施設があると中学生、高校生の皆さんが使いたいというニーズは、我々が視察に行ったところでもそのような使われ方をしていたというところがありますので。","voiceIndex":44,"id":"exchange-021"}]},{"id":"topic-02","title":"ウェルビーイング・ＳＤＧｓ推進ファンド事業実施状況","agenda":"ウェルビーイング・ＳＤＧｓ推進ファンド事業実施状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"４事業が選定されたということですが、どういった点が評価されたのかを伺いたいのですが、それと併せて評価の結果を公表していただきたいと思うのですけれども、いかがでしょうか。今回、助成金の額が１,００７万７,０００円ということで、区として出資したのは５００万円だったと思うのですけれども、民間からの出資は幾ら集まったのかも伺いたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一方で、不選定になった事業者につきましては、事業者名は伏せた形で公開をすることを検討しておりまして、あとは事業内容等につきましても、事業者ごとに機密情報等ありますので、その辺りは事業者と調整しながら、どの程度。","voiceIndex":50,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"提案","question":"自治体ＳＤＧｓモデル事業として、この事業を提案されているわけですから、ＳＤＧｓに資する事業であるかというところが非常に大きな、やはりここは審査基準であると思うのですけれども、この４つの今、事業を拝見したときに、それぞれに立派な目的を持たれていて、様々な課題についてトライをされるということは読み取れるのですけれども、ＳＤＧｓにどう資するのかというところが。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後、委員からもご提案いただきましたように、現段階のこの事業者名、事業概要助成金額の設定といった情報だけでは、１７のＳＤＧｓの目標のどこにつながるのか、その先の１６９のターゲットがどこにつながるのかというところが。","voiceIndex":52,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"それは大変ありがたいなと思うので、そのようにしていただければと思うのですけれども、これも伺いますが、そのやりとりの中で、審査員の中から、どうしてこの事業はＳＤＧに資する事業なのですかという問いがあったと先ほどありましたけれども、それに対して、選ばれたこの４事業者は、これは先ほどおっしゃられた１７のゴールと。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"もう１点、ＳＤＧｓに資する事業かどうか、委員からも審査の中で質問があったというところに関してですが、目標１７のところにつきましては、提案内容などからひもづけたり、質疑の中で確認するというところがございましたが。","voiceIndex":54,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"提案","question":"それと、全体としてやはり始まったばかりというところで、先ほど民間からの出資について課題があるとか、内容的にはやはりこれだけこの４事業を見ると、地道な、地に足がついた形の提案かというところで、Minecraftとかこれもやはり現代風なのかなと思うのですけれども、それ以外は割と地道な活動なのかというところで、率直に言うと、すごく目新しいという感じはしませんけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問","question":"ご説明ありがとうございました。私からも何点か質問をします。審査です。ここまで二次審査を進めて、審査結果が出て、事業者が決まりましたというところで、この審査内容、それから立ち上げからここまで進めてきてのご感想をお聞かせいただければと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"本事業は新しい事業でございましたので、事務局担当といたしましても、少し走りながら考えるというようなところもございまして、検討と大分苦労をしつつ、進めてきたというところではありますが、まず本事業について、応募を多数の事業者の方。","voiceIndex":57,"id":"exchange-026"},{"speaker":"山本委員","kind":"提案","question":"次に進みます。こちらの４事業者が選ばれたということですけれども、この４事業者それぞれこれまで区と何らかのご接点があったのでしょうか。続けますと、それぞれ４事業者のところで、この事業をそれぞれご提案されていますけれども、そもそもその各事業者がこの事業自体をそもそもやっていて、それをこの推進ファンドという枠組みができたから、それに申し込んだということがあるのかどうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一方で、一般社団法人のＮボノ、４点目のところですが、こちらについては活動をするメンバーの中には、区内で別の任意団体としてプログラミング教室などを実施するような方もいらっしゃいまして、そういった意味ではこの団体としては区との関わりはないのですけれども。","voiceIndex":59,"id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"それぞれ目的、従前やっているところもあるというところでしたけれども、それをそれぞれ今回の事業に応じて発展した形で取り組まれているということをお考えだということで理解をいたしました。ちょっと続けますけれども、中身のところで、こちら、それぞれ目的のところで、それぞれ目的を掲げていらっしゃいますけれども、定量的な評価というのはどのようにお考えなのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"例えば利用者ですとか、参加者に対するアンケートの調査結果ですとか、あとイベントなどについては、そこに集まった集客数ですとか、そういったものを１つの指標として、それぞれの事業者が成果を定性的にだけではなくて。","voiceIndex":61,"id":"exchange-028"},{"speaker":"山本委員","kind":"質問","question":"最後に、この成果報告のところになりますけれども、助成対象事業者から実行委員会へまず報告があった後、議会報告ということですけれども、これはその後、区民の皆様へも含めた報告会、例えば他の助成事業だと、区民の皆様も参加できるような形での報告会があったかと、少し記憶しておりまして、そういったこともしたらよいのではないかと考えていますが。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"実行委員会へ事業者が成果報告会を実施した後ですとかといったタイミングで、区民の方向けにも同様の成果報告会を開催してはどうかというご提案ですが、そちらについて、次年度の成果報告、区民の方、議会に向けての報告内容を今後、検討させていただければと考えています。","voiceIndex":63,"id":"exchange-029"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、ラヴィプラスでしたら４７８万円と、他の団体と比べて一番大きな金額になっておりますし、先ほどおっしゃったスペースに関して、何か家賃が発生するのかなと思ったのですが、区内施設ではなく、レンタルスペースを借りるのか物件を借りるのかというご答弁があったので、この資料を見ていると区内施設を活用されるのかなと思ったので、その点をもう一度お聞かせいただきたいと思うのと、あと。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"こちらについては、申請金額につきまして、賃料という形で、今回の助成については申請を受けているところです。今後は３月にかけて、固定の物件も探していく、検討していくと事業者からは聞いているところです。","voiceIndex":66,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"先ほどの質疑の中でもあったのですが、区が５,０００万円ということで、なかなか民間の資金というところが苦戦しているというお話があって、今回、初めて４事業選定ということでスタートしているわけですけれども、この４事業の事業者の活躍というか、そこが一つ大きなきっかけになろうかと思いますし、これまでも含めたどういうふうにこの全体の事業自体のアピールというか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回、４事業が選定されまして、ファンドについて一定の実績が出た形ですので、これまでファンド事業について概要に関することしか企業の方にはご説明できなかったところ、実績についても説明できるようになってまいりますので、より具体的にイメージを持っていただいて。","voiceIndex":68,"id":"exchange-031"},{"speaker":"つる委員","kind":"提案","question":"各事業者が独自に展開される部分も、それぞれがステークホルダーなのでやるという部分と、またこういった出資という形で、ＳＤＧｓに貢献していくという観点がある中で、先ほどあくつ委員からも確認がありましたけれども、この事業が１７の目標だとか１６９のターゲットだとか、その中で品川区の課題の解決というところでの提案があったわけだと思うのですけれども、そこをしっかりと伝えていかなければ。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今、委員からいただきましたご提案、アドバイス等も含めて、今後は区内企業を中心として出資を募っていく段階については、そもそもの目的ですＳＤＧｓにつながったりですとか、こちらのファンドに資金を提供していただくことによって。","voiceIndex":70,"id":"exchange-032"}]},{"id":"topic-03","title":"官民共同による「保育士向けＡＩ研修」の実施","agenda":"官民共同による「保育士向けＡＩ研修」の実施","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"もう１つは、なぜ保育士に向けたＡＩ研修なのかというところで、この事業概要というところではあるのですけれども、もう少し議事録を作成するとか、あまり保育士が議事録をそんなに頻繁につくるのかというところが私もあまりイメージができなくて、事務作業があるというのは存じ上げていますけれども、そういったところで生成ＡＩの活用と、どういったところで事業の効率化に資するのかというところを。","respondent":"西澤ＤＸ戦略担当課長","answer":"かつ、先日、台場保育園まで行って、園長にご協力をいただきながら、保育現場でのＡＩ活用について意見交換をする場を設けて、どういったところに活用シーンがあるかということを、企画案の検討だとか、保育士は２週案というものをつくっていらっしゃるみたいで。","voiceIndex":76,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"もう既に我々のほうにもプレス発表、区民にもこれは知らされているということで、私が気づいていなかっただけで、大変失礼しました。毎日という言い方はちょっと例えですけれども、それがかなり負担になっているということでよろしいのでしょうか。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＡＷＳとシフトプラスとの関係、それとあとは他自治体の事例について、まずご回答します。ＡＷＳとシフトプラスは、令和６年度の６月からＡＩの活用に関する意見交換を定期的に行ってまいりました。","voiceIndex":78,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"もう昨年の１１月から毎月４０万円前後を品川区のほうで負担して共同研究もされているということなのですけれども、今後その募集対象、今回は区立保育園の保育士ということで、区立なのですけれども、区立の方たちがこれはどんどん使っていきたいといった場合は、月額４０万円のこのサービスでやっていくということでよろしかったのでしょうか。最後に確認させてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"もう既に区立保育園の保育士はこの環境が使える環境にあります。なので、この４０万円の範囲の中で使っていくことになります。","voiceIndex":82,"id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。私からも何点か質問します。それから先ほどのご質疑にもありましたけれども、アンケートで実態を確認して、それに応えてさらに意見交換を進めていき、このような研修に至っているというプロセスもとてもよいと考えています。数字がないということでしたら、可能な範囲でもちろん結構です。そのリテラシーや使い方というところで、少し気になったので、以上３点、お伺いします。","respondent":"西澤ＤＸ戦略担当課長","answer":"その中でリテラシーについてなのですが、やはりアンケートを取った結果、こういったツールがあるというか、生成ＡＩ自体は知っているけれども使ったことがないとか、使ったことはあるけれどもよく使い方が分からないとか、そういった意見が結構多くて。","voiceIndex":84,"id":"exchange-036"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。人数について、概略は分かりました。少し細かくて恐縮なのですが、皆さん全員、その方々が使える環境にあるということでよいのかということと、それを使い方が分からないので今回お教えになられるということでよいのかということで教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"全員が利用できるかに関しては、全員が利用できますといったところになりまして、研修を受けなくても利用はできます。","voiceIndex":86,"id":"exchange-037"},{"speaker":"山本委員","kind":"質問・要望","question":"今後の、要は進め方です。こういったところで、学校教育においても、生成ＡＩを主体的に取り組んでいくということが有効ではないかと思っているのですが、そこら辺、区のデジタル推進課としての関わりができるのかどうかということと、それについてどのようにお考えになるかということで、ご意見を伺います。","respondent":"西澤ＤＸ戦略担当課長","answer":"区の職員の業務の効率化を目的とした導入ツールであるため、まずは今回、保育士というところをやりましたが、要望があれば今回の研修の効果を検証しつつ、研究してくことになるかなと考えております。","voiceIndex":88,"id":"exchange-038"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれご回答ありがとうございました。これは要望です。それから学校教育への発展についてですけれども、職員の方もＰＣで同じアプリケーションが使える環境があるということで理解をいたしました。今後、要望があれば、そういったデジタル推進課の皆様として対応されていくということでしたので、これについては別途、要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"先ほども少しご説明がありましたけれども、期待される効果として保育の質の向上ということで言われているのですが、ＡＩの活用との関係が少しよく分からないので、具体的なところで説明いただけるところがあれば伺いたいのと、それと関連して、この品川区の自治体ＡＩｚｅｖｏができることというのは、どういうことがあるのかというところを伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"保育の質の向上については、こちらにも記載してありますとおり、本来業務である子どもたちの対応や関わりに多くの時間を割くことができるという点と、従来の経験や知識だけでなく、ＡＩの活用に多角的な視点から保育を行うことができるという２点です。","voiceIndex":91,"id":"exchange-040"},{"speaker":"のだて委員","kind":"意見","question":"１点、ＳＤＧｓの説明の仕方というところで、具体的にあったのですけれども、議事録作成とかで、その時間が空くというところは分かりやすいのですが、そうしたところで、２番目のＡＩの活用に多角的な視点というところは、もう少し具体的な事例があればご紹介いただければと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"個人が聞くと、その自分の経験からの運動会しか多分、想定しないでしょうけれども、ＡＩに聞くと、いろいろなこれまでのネットワーク、インターネット上の情報だとか、研究資料だとかそういったものから出てくるので。","voiceIndex":93,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6925#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":45276,"voices":99}},{"id":"r06-20241128-19","meetingId":"r06-cm11","date":"2024年11月28日","dateIso":"2024-11-28","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度区内一斉防災訓練の実施","agenda":"令和６年度区内一斉防災訓練の実施","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"これは、裏面を見ると、避難所の一覧はほとんど小学校や義務教育学校になっていますけれども、その中でも私の地元ですとスクエア荏原、大井３地区ですとウェルカムセンター原、あと八潮地区ですと、こみゅにてぃぷらざ八潮が入っていて、通常、学校ですと子どもたち、来ていても保護者の方、関係者だと思うのですけれども、かなり不特定多数の方が、日中ですと来館されていると思うのですけれども。","respondent":"伊藤災害対策担当課長","answer":"こういった話合いを通じまして、実際に発災したとき、地震が起きたときの対応について、連携を密にできるように努めてまいりたいと思います。どうぞよろしくお願いいたします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"えのした委員","kind":"質問・要望","question":"ぜひ、地域の方のお声を伺って、スムーズな運営ができるように、防災訓練だけでなくて日々も連携を取っていただきたいと思います。ありがとうございました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"すみません。今ご説明いただいた、裏面の米印がついているところの「医療救護所を表す」というところで、ご説明の中では今回、医療救護所については特に触れられなかったので、どういうふうになっているのかなという、訓練の実施の状況を、まず最初に伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"一方で、やはり医療救護所として指定されているところもあることから、備蓄している物品の確認等を行うということで、医療救護所での訓練も行うというような避難所もあると聞いてあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"そういったところの仕事などもいろいろと出てくる中で、せっかく区内一斉でやるので、医療救護所の訓練を、このタイミングでなるべくできるといいのかとは思うのですけれども、今後についてどういうふうに、区内一斉防災訓練における医療救護所の訓練の拡充というのですか、充実というのかについてのお考えをお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"今回、先ほど１枚目で説明しましたとおり、職員訓練と地域の訓練に分かれているというお話をさせていただきましたが、地域医療連携課につきましては、こちらに本部を置きまして訓練を行うと。","voiceIndex":11,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。今年が医療連携の部署ができてから最初ということで、徐々にという部分もあるのでしょうけれども、今後、各避難所の全ての医療救護所設置予定のところで訓練ができるような形を目指して進めていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回気になったのが、医療救護所に当たっているところ、先ほどのお話だと、まず避難所の訓練を行って、プラスで医療救護所の物品等の確認をするところもあるということのお話だったのですけれども、学校医療救護所は１３か所指定されていて、今回、八潮学園は丸がついていないということは、区内一斉防災訓練に参加されないという認識で確認しているのですけれども、参加されなかった理由や、では別途。","respondent":"伊藤災害対策担当課長","answer":"一方で、八潮地域におきましては、この３地区で毎年、訓練を行うところを順繰りに回していくという方針があるということで聞いておりますので、間違いなく訓練は実施していただくということで聞き及んです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"確認","question":"では１点、医療救護所の訓練はしないけれども、物品の確認というのは訓練とは別途できちんと行われているという認識でよろしいでしょうか。","respondent":"平原防災課長","answer":"先ほど災害対策担当課長からお話しさせていただいたのは、皆さんのところの避難所に医療の拠点があるといったところを知っていただくという意味で見ていただくということで、物品の管理につきましては、別途、職員のほうでしっかりと行っているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"先ほど塚本委員から質問があった点を私も質問しようと思ったので、確認が取れましたのであれなのですが、もう一つ参考までに、そうすると医療救護所の場所は、それぞれの医療救護所が設置されている学校では、そのスペースが保健室ということになると理解しているのですが、そうしたことも、この避難所運営会議の方たちもご存じで。","respondent":"平原防災課長","answer":"そういったところは、「この学校は医療救護所ですよ」といったところは、私どもからしっかり説明させていただいているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで、資材等を確認するということで、流れとして、そういう説明だと思うので、本当にこういうことも地道にやらなくてはいけないと思います。各町会の役員がこういうことを把握して、どういうことをやるかということを確認する意味では、年に１回は必要かと思います。その中で、光明というのですか、若干ですけれども、お子さんを連れていた家族がいたということはよかったのかなと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"伺いたいのが、いろいろな障害者団体から、自分たちが参加できるような訓練というのを求められていて、それは普通にこういう場所に訓練にいらっしゃればいいのではないですかと私たちは思うのですが、その辺のご案内、例えばこういうのは、今も町会の掲示板などを見ないと分からないというご意見がありましたけれども、障害者団体からはそういうご意見が出ているわけなので。","respondent":"伊藤災害対策担当課長","answer":"一方で、今後も顔の見える関係をつくっていくということで、地域に障害を持たれている方がいるということを認識する上でも、地区防災訓練において、しっかりとアピールしていただいて、ほかの訓練にも来ていただこうと考えています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"吉田委員","kind":"提案","question":"そんなつもりは私たちは全然ないし、皆さんも絶対そんなことはないと思うのですけれども、それが今の現状だということは認識していただいて、これから一層、ウエルカムというか、ぜひ来てくださいみたいな表記や広報の仕方を検討していただきたいと思います。これは私たちも提案していかなくてはいけないと思いますので、要望でとどめしますが、今後はぜひそういうことをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"防災計画に記載があって１個というのはいい取組だと思っているのです。そうすると、助けてほしいときに、長い距離を歩くのでなかなか大変なのかなと思った場合には、例えばコンパスのあれではないですけれども、学区ではないですけれども、空いた部分も鑑みてもいいのかなと思ったので、これはお答えはないので要望として、バランスというのももう一度、考えていただきたいというのが１件。","respondent":"伊藤災害対策担当課長","answer":"訓練に関しまして、私どもでできる限りのことはやっていきたいと考えております。一方で、町会長会議へのつなぎということであると、やはり担当課があると思いますので、こちらは情報提供、情報共有をさせていただきたいと考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"最後に１点、荏原５地区は、要は旧荏原第四中学校が今改築中ですけれども、今回も旧荏原第四中学校でやるのですけれども、たしか豊町三・四丁目は、旧荏原第四中学校に入り切らないので大崎高校がプラスアルファでやるのですけれども、例えばその訓練は、たしか前に聞いたときは、そういうのもやっていますと言うのですけれども、こういったときの地域一斉防災訓練の中では、そういった高校との連携。","respondent":"平原防災課長","answer":"定員がいっぱいになったようなときには、定員がいっぱいになった状況に応じて近隣の大崎高校を補完避難所として開設していくということで、大崎高校との間では、現在、私どもと、それから一部、町会の方にも見ていただくような形で話合いを進めさせていただいているところです。","voiceIndex":33,"id":"exchange-013"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"ひがし委員","kind":"質問","question":"では製品プラスチック回収の点から、先ほど少しお話がありましたけれども、不要な充電式電池の収集を今年度９月から始めていると思います。都内初ということで、収集に踏み切った理由と、始めて２か月だと思うのですけれども、始めてみての課題等があれば教えてください。","respondent":"篠田品川区清掃事務所長","answer":"品川区の場合は、戸別収集をしているということがありますので、そのときに、通常の電池も戸別収集のときに出していただけるようになっていましたので、併せて最終的な処理ルートが確保できれば収集できるだろうということで検討したところ。","voiceIndex":40,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"確かに、このごみの出せないというところで、区民の方からも出せるところを増やせないのか、なぜ回収してもらえないのだろうみたいなお話を聞いていましたし、自分自身も充電器などを出すときにすごく困っているという現状があったので、今回、品川区がこういったところに取り組んでくださったというところは大変評価しております。こちらは要望でとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"},{"speaker":"吉田委員","kind":"提案","question":"ひがし委員のご質問に続く形になるのですけれども、リチウム電池について、いろいろ課題が見えてきたからということなのでしょうか。その辺の経緯を伺いたいと思います。お金の問題とかはどうなのだろうか」という、要は自分の区でも提案してみたいということだと思うのですけれども、その辺のことを少し詳しく教えていただけると、参考にさせていただきたいのですが、よろしくお願いします。","respondent":"篠田品川区清掃事務所長","answer":"今、委員からもお話があったとおり、かなり以前から一応、問題意識としては持っていたとは聞いているのですけれども、リチウムイオン電池は処理がなかなか難しいというところがあって、簡単に回収してすぐにというわけにはいかなかったというところが、どうもあったようです。","voiceIndex":44,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"は自治体として課題意識を持ったというところから始まったということですよね。は引取手と、それにかかる費用の問題というような、すごくざっくりしたまとめですけれども。だから、実態として事故が顕在化してきたということも、１つ大きいということでしょうか。それは構いませんよね。私は全区的に広げていただきたいと思っているのですが、いかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"品川区の今回のものに関しては、そういったものも含めて引取りができるという形で間口を広げましたので、そういった形での対応も行っているところです。","voiceIndex":46,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、小学校の授業なのですけれども、今、所長がおっしゃっていたとおり、以前は小学校でやっていたとおっしゃっていますけれども、やはり子どもたちは当然、毎年入れ替わるわけじゃないですか。すみません。それで、放置自転車の車両においては、八潮北と不動前の保管所にあるじゃないですか。その１点だけ確認をお願いします。","respondent":"篠田品川区清掃事務所長","answer":"私どものほうでは、なかなか放置自転車自体の取扱いというのができないものですから、あくまで粗大ごみとして入ったものでしか対応できないところがありますので、今後そういった連携ができるかどうか、中でも考えていく必要はあるのかなと受け止めたところです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"えのした委員","kind":"質問","question":"そこで、私も先ほど負担とは言いましたけれども、作業者の方、先ほど安全の話は出ましたけれども、手間がやはりかかってくると思うので、その辺を区としてどのようにお考えなのかということと、あと普及・啓発で、環境学習は子どもたちに大事だと思いますが、実際は捨てているのは大人が今は分別しているのかなというところで、各種イベントにも出前授業など出されているとおっしゃっていましたけれども。","respondent":"篠田品川区清掃事務所長","answer":"できることならば、例えばそういった若い方が行かれるようなコンビニなどといったところをきっかけにできればいいのかなと思いつつ、どういった形で協力できるのかというのは、決め手がなかなかないというところがありますので、委員ご指摘のことを踏まえまして。","voiceIndex":53,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問","question":"出ているとしたら、どれくらい出ているのか。その点についても伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"ただ、いわゆる法的な部分での、以前、国が負担していた部分に関しては、逆に言うとそこは新たに追加されたわけではないので、今までどおりという形になりますから、区が負担していた部分は引き続き区が負担するという形で、継続されているということになります。","voiceIndex":56,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"意見","question":"今の説明が、いま一つよく分からなかったのですけれども、拡大生産者責任としての、事業者のほうが負担するというところは、製品のほうは仕組みとしてないということで書かれていたのですけれども、そういうことでいいのか。その辺のところがよく分からなかったので、仕組みと品川区のやり方というところがどうなのかということでお聞かせください。","respondent":"篠田品川区清掃事務所長","answer":"それに関して、ただ負担するに当たっては、品川区としては、これまでの収集の仕方自体が変わっているわけではないので、要は容リ法で一緒に集めていますので、それで容リ法に基づいた形で、全て再商品化まで兼ねていますので、今までと変わらないという形になるです。","voiceIndex":58,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"気候危機の問題からも、ＣＯ２のところでも、プラスチックというのは石油から出てくるので、石油を掘り出すところから、それから製品にするところから、様々ＣＯ２を増やすという問題にもつながってくるので、ＣＯ２を減らすという観点からも、どうしたらプラスチック製品そのものを、生産そのものを減らしていくかというところに。","respondent":"篠田品川区清掃事務所長","answer":"日頃からの周知・啓発といったものしか、なかなか区の立場ではやれないものですから、強制的にごみを減らすような取組があれば一番いいのかもしれませんけれども、なかなかそういったものは私どもも探しあぐねているといった状況があります。","voiceIndex":60,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"拡大生産者責任というところでは、ＥＵでは自治体の分別収集や散乱ごみ回収費用などまで事業者負担としていて、かなり事業者の負担がしっかりと求められているということなのですけれども、それに比べて、やはり日本では事業者の費用負担というのが軽いので、余計に使用量を増やすという効果が弱いとも言われていると思いますので、そういうところでは、やはり区としても、今回。","respondent":"篠田品川区清掃事務所長","answer":"実はこれまでプラスチックのごみは、容器包装以外のものに関しましては、清掃一部事務組合でもサーマルリサイクルという形で、燃やしてそれをエネルギーに変えるというリサイクルでいきますという対応を取っておりましたので、そういった意味では、一定程度。","voiceIndex":62,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"あと、ごみを燃やした後にできる焼却灰なのですけれども、頂いた資料の「ごみれぽ」の冊子のほうで、１２ページに、焼却灰がどういうふうに活用されているかということで、セメントや徐冷スラグ、焼成砂というのですか、この３つに活用されていますということで説明がありましたし、ここにも書かれているのですけれども、これはどれぐらい活用されているものなのか。","respondent":"篠田品川区清掃事務所長","answer":"それから徐冷スラグや焼成砂というのは使える範囲が限られている部分もあるので、恐らく清掃一部組合も、できるだけこちらは、売れなければそのまま埋立てに回るだけの話になるので、その辺を減らすために様々努力をされているとは伺っているので。","voiceIndex":64,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"以前はなかなか実用化が難しいみたいなことで伺っていましたけれども、７万トンということですけれども、これは全体の何％ぐらいというのは分からないということですよね。分かりました。それから、安全性や何かも、無害化みたいな技術も進んで、活用できるようになったということで捉えていいのでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"詳しい安全基準等については私も手元にないのですけれども、聞いている話では、基本的にはもう焼却してしまっているものですので、安全性に関しては確保されていると聞いているところです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私はすごく受けまして。その中で、放置自転車の保管所ですね。あれは私は前も質問したのですけれども、保管所の自転車というのは、１回オートバイの話をしたら、所有権のいろいろなものがあって難しいという話があったのですけれども、あれだけある保管所の放置自転車の活用というのは、とても大事なことではないかというので、その辺の考えをまず１点、教えていただきたい。ふれあい作業所です。","respondent":"溝口防災まちづくり部長、篠田品川区清掃事務所長","answer":"そういった取組を続けてきているところですので、今後も同じような形で取組を続けていきたいと考えているところです。自転車の関係です。今、自転車のリユースの整備に関しましては民間の事業者にお願いしていますけれども、ふれあい作業所と今後そういった形で活用ができるかどうかというのは考えてまいりたいと思っているところです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"まつざわ委員","kind":"質問","question":"先ほど、せお委員に教えていただいたのですけれども、このリサイクル事業で約３億円余の収入があるので、これは本当にすごいことだと思っていますので、区と区民がしっかりとリサイクルに向けてやった結果だと思いますので、私たち議員も含めてどんどん、これだけの収入をみんなで頑張っているのだ、品川区は頑張っていますというのは推し進めて、また宣伝していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、視察に行ったときのことなのですけれども、あそこの工場で出ているＣＯ２というのは、様々、排ガスの対策を取られていて、いろいろなろ過装置を通って排出されるとは説明されたのですけれども、それでもＣＯ２は出るというところで、あそこで出るのはどれぐらいなのか、分かれば教えていただきたいのと、それと、そのときにちらっと説明された、ＣＯ２回収の技術開発というのが、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはりプラスチックの廃棄とＣＯ２というところでは切り離せないですし、それをどれだけ減らしていくかというのが、今、喫緊の課題になっているというところで、様々工夫されて、燃やさずにリサイクルというところで努力されていると思うのですけれども、それと併せて、ＣＯ２を出さなくできる技術が一緒に進むというのはすごいことだと思って伺いました。すみません。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで時間を、どうやって資源を有効に拾い出して、人手もあまりかけないでやっていけるような、有効利用できるような方法を取る。でも、それはやはりある程度、人件費を抑えて頑張っている状況があるから、何とかやっていると思うのですけれども、やはりよりいいものを求めるなら、よりいい設備、環境が私は大事だと思うのですけれども、その辺のご見解をお聞かせください。","respondent":"篠田品川区清掃事務所長","answer":"この先のことを考えていったときに、さらにコストをかけてまでやる必要はないのではないかという考え方も当然世の中にあるでしょうし、逆に、地球の将来を考えれば、もっとお金をかけてでもやっていく必要があるのだろうということで、そちらは結局、最終的に。","voiceIndex":78,"id":"exchange-030"},{"speaker":"須貝委員","kind":"確認","question":"それには、やはり申し訳ないのですけれども、企業が物を作っていれば製造責任というのがあるじゃないですか。それからプラスチック製ごみのマテリアルリサイクル、そして自転車のリユースもあるのですが、我々はこういうふうにお話を聞いたりして、また品川区の広報を見て、確認も何度かしているのですけれども、一般の方は、恐らくそういう情報量もかなり少ないと思うのです。","respondent":"篠田品川区清掃事務所長","answer":"ホームページでもそういった形で選べるようになっているというところではあるのですけれども、全ての言語に対応しているわけではないので、その辺はどういった形でご案内できるかというのは今後の課題なのだろうと認識しておるところです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"それは分かるのですけれども、やはり大半の方が、資源化センターの現状を見たら、これはもう何とかしなくてはいけないと思ったもので、確かに要望があればということなのですけれども、ただ、そこは皆さん出すだけなので、要望はないのです。だけど、現実論、後々ああいうところで苦労されるなら、何かやはり啓発する意味でも考えたほうがいいのではないかと思ったもので、意見を言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-032"},{"speaker":"せお委員","kind":"質問","question":"すみません。１点だけ。粗大ごみのリサイクルなのですけれども、例えば木製粗大ごみのリサイクルだと、どの工程で品川区から離れて、どういう事業者にどこで渡されるのかというのを、まず教えていただいていいですか。","respondent":"篠田品川区清掃事務所長","answer":"それで、金属などを分けた上で、木の部分だけをリサイクル事業者にお渡しするという形になっております。","voiceIndex":84,"id":"exchange-033"},{"speaker":"せお委員","kind":"質問","question":"その事業者なのですけれども、どういった、区内の事業所などなのですか。すみません。","respondent":"篠田品川区清掃事務所長","answer":"この事業者は、基本的にはパーティクルボードを専門に扱っている製造メーカーです。ですので、材料として、実は公園などの倒木といったものも含めて様々な形で木を収集しているという中で、私どものほうでは、粗大ごみから出た家具などの木材を提供しているということになります。","voiceIndex":86,"id":"exchange-034"},{"speaker":"せお委員","kind":"質問・要望","question":"そうすることで、この目的に加えて区内産業の活性化や、区民の就労場の創設などといったところにもつながるのかなと思ったので質問したのですけれども、その辺も要望でとどめするのですけれども、先ほどのまつざわ委員からの質問にもあったように、そういったところを、自転車も統一したらいいのかなと思ったので、ぜひそこは検討していただきたいと思って要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6927#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":33309,"voices":93}},{"id":"r06-20241128-10","meetingId":"r06-cm11","date":"2024年11月28日","dateIso":"2024-11-28","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6929#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1203,"voices":8}},{"id":"r06-20241204-10","meetingId":"r06-cm12","date":"2024年12月4日","dateIso":"2024-12-04","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"前例打破していただいて、より開かれた議会を目指し、審議の途中でも自席から撮影を許可すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"令和６年陳情第５５号、品川区議会全会派合同で小規模事業者の困窮実態のヒアリング会を求める陳情","agenda":"令和６年陳情第５５号、品川区議会全会派合同で小規模事業者の困窮実態のヒアリング会を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"陳情にありますように、対策を講じるにはまず、実態の把握と、本当にそのとおりだと思います。私たち共産党としては、議会として、こうした方々と懇談して実態を把握することには大きな意義があると思いますし、やるべきだと思っていますけれども、いかがでしょうか、皆さんのご意見を聞かせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"そうでなければ我々区議会議員の意味がないので。その中で、コロナによるゼロゼロ融資返済、もう始まって１年以上たちますけれど、仕入価格の高騰、インボイス制度、エネルギー価格高騰、円安などによる、そういう問題があって、これも消費者物価が上がったり、という実態ですから、これによる小規模事業者、個人事業主の抱える問題というのは本当に深刻であると。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"須貝委員の意見、ありがとうあります。私は、そうですね、把握するというのは、それは皆さんなりに把握しているのは間違いないことなのですが、その上で、やはりこういったヒアリング会を持つということの意味というのは須貝委員も恐らく否定しないと思うのです。それと、本日の後の報告にもあるのですが、区民と議会の交流会議というのがあるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、ぜひ、先ほど、どうですか、皆さんのご意見はいかがですか、共産党はこういうふうに考えますけれども、と言ったのですが、投げかけさせていただきました。最後の態度表明のときに意見を伺っても、それに対してもう議論できないのですよ、採決の前の態度表明なので。なので、ぜひ今の時点で、私はお互いに意見を出していただきたいし、それが議会のあるべき姿だと思うのです。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"西村委員","kind":"提案","question":"我々の会派からも、物価高などへの支援の強化を要望しています。既に個別具体的な対応をしている中で、陳情者が提案するような合同ヒアリング会を追加で行うためには、参加する小規模事業者に偏りが生じないような客観性、中立性の確保を考慮する必要があり、直ちに実施することは困難だと考えています。以上のことから、本件は不採択とさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"やはり、陳情の内容にも書いてありますけれども、それぞれの事情の中で、会派としていろいろなご意見を伺うに当たっては、我々の考え方とか立ち位置ですとか、方向性だとか、施策の在り方とか、そういうこともありますので、この合同でというような形よりは、やはり今までどおりのやり方でやるほうが、より建設的というか、内容になってくるのではないかなと考えていますので、本日結論を出すで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"松永委員","kind":"質問・要望","question":"陳情第５５号について、本日結論を出す。会派といたしましては、不採択とします。各会派ごとにヒアリングも行っており、そして何よりも、議員は、先ほど須貝委員もおっしゃいましたけれども、地域を回って住民の声を聞きながら要望や陳情、いわゆる住民の声を実現していくということが仕事です。そうしたことも含めまして、今回のこの陳情に関しましては、不採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。区民の暮らしと営業を守るというのが、言うまでもなく区政と区議会の重要な任務でありまして、その施策を進めるために有効なのが、この実態把握、というか実態把握は必要ですよね。ヒアリングは大変重要で有効な機会だと思います。ましてや、苦境に追い込まれている当事者からの要望には応える議会でありたいなと思います。採択して実施すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、不採択でお願いしたいと思います。今回、物価高騰ということが一番、念頭にあると思いますが、円高にすれば企業物価は下がる。ある程度は下がります。だけれど、それが結局できない。もっと実効性のある支援、それを国に早急に求めて、進んでいくのが本来だと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"}]},{"id":"topic-03","title":"令和６年第４回定例会","agenda":"令和６年第４回定例会","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"ご説明申し上げます。当会派の木村議員が、現在も歩行が難しく、車椅子を利用している状況です。つきましては、前回と同様に、車椅子で本会議に出席すること、それから、採決時の起立が難しいため、賛成は挙手によるものとしていただきたいということ、以上２点をご了承いただきたく存じます。ご検討よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"}]},{"id":"topic-04","title":"令和７年第１回定例会","agenda":"令和７年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この民生費の日程は、この３つの特別会計を独立させて、２日に分けた日程を考え、立てるべきではないかというふうに私たちは考えているのですが、皆さんいかがでしょうか、ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-012"}]},{"id":"topic-05","title":"区民と議会の交流会議からの報告事項","agenda":"区民と議会の交流会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"提案","question":"ちなみに提案事項を事前に学校からお聞きして、こちらとしてもしっかり準備をして、当日に臨みたいと考えています。委員会ごとの開催は準備も大変だと思いますが、区民の皆様が議員と直接語り合える貴重な機会としていきたいと思いますので、参加された区民の皆様と有意義な時間を共有できるよう、交流会をしてまいりたいと思いますので、引き続き、終了まで皆様のご協力をどうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問","question":"ですので、交流会議の中で一応集約はしますが、ここでどういうふうに上げますよという具体的な上げ方まではしていませんが、各議員が、参加した交流会議のメンバーが議会質問で上げていくというようなスタイルを取っておりますので、今回もそのようにしていきたいと考えているところです。","respondent":"あくつ副議長","answer":"要するに、議会に対して声を上げたけれども何の進展もないというふうに彼らが思ってしまうと、少しそこは非常に誤解を招くなということが、今あったので、その中で受け止めた議員が、それぞれに対応するということで、先ほど理解しました。","voiceIndex":46,"id":"exchange-014"}]},{"id":"topic-06","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"収支報告書の作成支援ツールの件ですが、これは今までやってきた議員研修会という扱いなのか、どういう位置づけなのかというのを少しお伺いしたいと思います。","respondent":"渡辺議長","answer":"説明を聞いて終わりなのか、あるいは、関心が高まれば、次の展開、試行もあるでしょうし、どういうことが考えられるかというのをまた、議会運営委員会をはじめ、相談していくというようなあらましです。","voiceIndex":55,"id":"exchange-015"},{"speaker":"安藤委員","kind":"提案","question":"翌日には政調会長名で、１１月２９日締切りということで、意見を求めるメールが届きまして、共産党としても返事を出したところです。今後の進め方についての考え方を伺いたいのですけれども、２０日の場でも、この意見交換会の続きは一体何なのですかという質問も出されましたし、あとは、提案は全員協議会で出してから議会運営委員会にかけるべきではないかという意見も出されました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"参加できない方もおられたのでメールでのご意見をいただいたというのが、今、安藤委員がおっしゃったとおりでありますけれども、その後２９日の締切りから、反映する案文作りでしたり調整を今、しております真っただ中でありますので、本日はご報告する案件がまとまっておりませんが、今後の議会運営委員会でご報告、並びに協議のお願いを、今後の議会運営委員会でお願いしたいというふうに思っております。","respondent":"渡辺議長","answer":"全員協議会の見解ですが、まさしく議会運営に関することが議会運営委員会で議論されていると承知しています。その議会運営委員会の求めが、正副委員長はじめ皆さんからあれば、検討に入るものと考えておりますので、そういう理解をしております。","voiceIndex":64,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、一度ああいうオープンな場を設けていただいたというのは、オープンでもないですけれど、設けていただいたのはよかったなと、いいことだなと思うのですが、やはり意見を、案を自民党・無所属の会から、案がある程度固まった時点で、全員協議会にぜひかけていただきたいと思うのですけれど、再度その要望をしたいのですが、自民党さん、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-018"},{"speaker":"西村委員","kind":"意見","question":"今、議長がおっしゃられたとおりであると思うのですけれども、様々なご意見をということで今回、意見交換会をさせていただいたり、また、参加できない方にも配慮をしたいと思いましたので、メールでのご意見もいただいております。ですので、現状、進め方について具体的なところはまだ調整の真っただ中でありますので、また改めて、今後の議会運営委員会でご報告並びに協議をお願いしたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6931#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":15879,"voices":70}},{"id":"r06-20241225-6","meetingId":"r06-cm12","date":"2024年12月25日","dateIso":"2024-12-25","committee":"区民委員会","time":"午前１０時０５分～午前１０時３８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"件数などについては、今ご説明があったので、分かりました。９月に補正した後の実際の受付の中身ですけれども、９月補正では、業務改善が図れる設備への更新を対象にするということに新しくなりましたが、その中で、実際にどのような設備の申請があったのでしょうかということをお伺いするのと、新札対応券売機の申請というのはどれぐらい、何％ぐらいだったのか、もし分かれば教えてください。","respondent":"小林地域産業振興課長","answer":"３番目としまして、オンラインと紙の比率ですけれども、今回オンラインのほうが、我々もこちらでお願いしますということでご説明しておりまして、現時点での数字ですけれども、８７％はオンラインからの申請ということになってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、財源についてですけれども、今回、国からの補助金で、基本的にこの補正予算は全部賄われていると聞いているのですが、前回は１億６００万円、９月補正のときは全て一般財源との説明でしたが、例えば前回の分についても遡って補助金が充てられるということはあるのでしょうか。それを伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"財源ですけれども、前回９月補正のときは一般財源という形でございましたが、この約２億円につきましては、国から来ている交付金、都支出金ということになりますけれども、交付金が充てられることになりますが、今回、遡ってということではなくて、この約２億円につきまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、今回こういった補助金が国から出るに当たって、補正も組むということに当たって、地域振興部としては、今回の事業以外に、例として去年の事業を挙げましたけれども、ほかに何かこういうのも補正が必要なのではないかとか、検討したことはあったのでしょうか、それともなかったのか、検討したとしたらどんなことを検討していて、なぜそれが実現しなかったのか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"その意味では、我々が当初の想定で見込んだよりも、件数としては多くなっているものですけれども、これは、地域の方にとってもニーズがあった施策なのかなと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"検討したのか、していないのか、よく分からなかったのですが、その辺はどうなのでしょうか。","respondent":"小林地域産業振興課長","answer":"今申し上げたとおり、全業種である程度対象という中で、我々としては、今、ニーズが出ているといいますか、申請のスピードもかなり上がってきているこの対策の助成金というのが一番有効で、機動的に打てる施策だということで、今回の経済対策ということで実施したものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり大変な状況なので、もちろん電気・ガス代の高騰というのは大きな影響を及ぼしていますが、それにとどまらない大変な状況でありますので、年明けにはまた新年度予算の審議もありますし、それに伴って最終補正などもありますので、幅広く業種も見てもらって、必要なものもまだまだあると思います。ぜひ、さらに地域経済の実態に即して、さらなる対策をお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"今の審議を聞いていて、根本的に電気・ガス代の高騰があって、今年は業務改善設備更新助成金も増えたということで、非常に予想外の件数が申請で集まったということですが、これは特にアナウンスとしては去年と同じ感じなのでしょうか。それとも、今年になってまた浸透してきたといった感じでしょうか。","respondent":"小林地域産業振興課長","answer":"今回申請をされた方に、事後的に聞ける範囲でですが、お聞きしたところ、品川区からのアナウンスのほかに、同僚の方というか、企業同士でこういう補助金があるよという口コミといいますか、そういうものも多かったと聞いておりますので、そういう意味での相乗効果といいますか。","voiceIndex":15,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問・要望","question":"十分期間が取れたので、認知していただけたというのと、口コミが多いというのも、お互い皆さん、すごく困っている飲食店とか企業とか、個人事業主が多いのかなと思います。非常にこれで助かっている方はいっぱいいらっしゃると思いますので、１月３１日までしっかりとスピーディーに、今後の助成金の交付のほうもしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"件数も増えていることと、資材高騰と、あと、不足の資材の遅れで、万が一納入が間に合わなくなったと事業主から、そういった事案があった場合の対応について、改めてお聞きできればと思います。","respondent":"小林地域産業振興課長","answer":"昨年もこの点は問題になったというか、我々も課題として認識していたところでございまして、事前に申請の段階でご相談をしておりましたので、結果的に期限を超えて、間に合わないという例はなかったと、我々としては、そこは迅速に対応できたのかなと考えていますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"昨年は１件もなかったということで、柔軟な対応を引き続きお願いしたいと思うのですけれども、年々、資材の高騰もずっと引き続き起こっている状況でもありますし、万が一、今回どうしても相談して、納入の時期がこのぐらいになるだろうと分かっていたにもかかわらず、不足してしまって遅れてしまったということがあった場合に、今注文しているものもそうですけれども。","respondent":"小林地域産業振興課長","answer":"基本的には補正予算という形なので、我々としては年度内にというところはありますけれども、新年度の予算はこれから編成という形になりますが、こういった対象設備に関して、また具体的にどういう支援ができるかということも含めて、今、新年度予算編成をやっておりますので。","voiceIndex":21,"id":"exchange-009"},{"speaker":"せお委員","kind":"確認","question":"それと、レンタルの設備というのは対象になっていないと思うのですけれども、そこはなるのかというところの確認と、あと、１１月２５日から受付を開始したということで、そういったところのお声とか、レンタルについてのお話とか、いただいていることがあれば教えてください。","respondent":"小林地域産業振興課長","answer":"年度内に支払いが完了する、設備の取得まで完了するというところで、我々は助成金として支出するということで、この点は対象としていないということで、そのことは、事業者の方に今回助成金のご説明をする際に、ご質問でそういうのがあるのではないかということで。","voiceIndex":25,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"私たちの会派も、地域からそういったお声をいただいていまして、やはり大型の設備だと、リースとかが多い現状もあるということで、その辺の検討も今後していただけたらと思いますので、よろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今回の助成は前回同様、いわゆる設備です。１２月、１月というのは、まさにガソリンの補助金がカットされるときで、非常に区民の方だったり事業者の方たちが、燃料の高騰というのを非常に気にしている中で、こういうときだからこそ、区がそこに対して支援をしてあげるというのが、区が助ける姿勢としても評価してもらえると思うのだけれども、その辺の検討というのがあったのか教えてください。","respondent":"小林地域産業振興課長","answer":"こちらにつきましては内閣府から、具体的にこの事業をやりなさいという形ではないのですけれども、一つ提示されているのは、推奨事業メニューという考え方がございまして、その中で大きく言うと、事業者支援の中で幾つか例示があるのですが、その中に。","voiceIndex":29,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かるのです。けれども、９月も今回も補正です。だから、そういった意味では、社会状況だったり、いろいろな政治の変化とかも判断しながら、こういう補正予算をぜひ今後、構成していっていただいて、本当に区民にとっていい施策を、さらに進めていただきたい。これは要望で終わりますけれども、ぜひそういった視点を持っていただいて、取り組んでいただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤原委員","kind":"確認","question":"一つだけ確認ですが、令和７年１月３１日までは、件数が多くなったとしても、この金額が多くなったとしても、必ずこれはやるのですよね。確認です。というのは、東京都の施策で、キャッシュレス決済への１０％還元というのが、急ではないかもしれないけれども、一般的な消費者は分からなくて、まだもう少しあると思っていたのが、昨日急に終わってしまったではないですか。","respondent":"小林地域産業振興課長","answer":"残りの営業日も考えまして、今回この４５０件というのが多少増えたとしても、最後の１月３１日の締切りが近づいたときに若干増えたとしても、４５０件に収まるであろうというところで我々は見ておりますけれども、ただ、もちろんそういう中で。","voiceIndex":33,"id":"exchange-014"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"賛成しますが、少しだけ意見を言わせてください。ただ、先ほど石田しんご委員がおっしゃったように、区としての政策でいうと、こういうことは本予算できちんと考えていただきたい内容かと思います。そうすると、区民の生活を第一に考える品川区、そして品川区議会としては、最初の本予算できちんとした対策をぜひ組んでいただきたいということを要望として付け加えまして、賛成意見といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6901#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":10967,"voices":46}},{"id":"r06-20241225-7","meetingId":"r06-cm12","date":"2024年12月25日","dateIso":"2024-12-25","committee":"厚生委員会","time":"午前１０時０６分～午前１０時３３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところでお聞きしたかったのが、この資料の１３ページのところに、郵送料とかはしようがないと思いますし、システム運用経費というのも、これは詳しくどういう状況なのかは分からないのですけれども、コールセンターのところなのですが、これはいつもどれくらい問合せがあるのか、それから何人体制でどれくらいの期間、コールセンターを設けるのか、あと、どこに委託するのか。","respondent":"豊嶋生活福祉課長","answer":"ただ、転入者については一切情報がございませんので、その方たちも見込んで、大体３万５,０００世帯ぐらいは一括で給付できるのではないかと見込んでいるところです。事務経費につきましてです。コールセンターは１０回線を予定しております。例年１０回線です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"コールセンターは、いつ、どれぐらいの期間、設けるのか。１０回線ということなので、１０人体制でということですか。本当にお疲れさまですということなのですけれども、あとこれは確認なのですが、これは生活保護の方にも出されて、収入認定はされないということで、これまでもそうだったと思いますけれども、そこのところも改めて確認させていただけたらと思います。","respondent":"豊嶋生活福祉課長","answer":"閑散期といいますか、大体いつもコールセンター設置時期から給付が始まる、要はコールセンターを設置してから１か月から２か月ぐらいがピークで、給付が完了したあたりからは一気に電話が減るというのが例年の流れです。件数については、すみません、今手元に資料がございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"若林委員","kind":"質問","question":"昨年、ほぼ同様の事業をされていると思いますが、あのとき、家計急変世帯の対応も、委員会のときにはやるかやらないか不明確で、最終的にやった……、そこら辺、家計急変世帯について、今回の支給についての対応、お考えをお聞きしたいのと、さっき、職員の方も土日返上ということで、去年も閣議決定以後、いつ支給されるのだという問合せが、コールセンターが開かれる前から。","respondent":"豊嶋生活福祉課長","answer":"できればコールセンターのほうで受けていただくのですけれども、コールセンターのほうでも受け切れないものは、どうしても職員のほうで受けて、おわび等も含めて、誠心誠意対応することで今までもやっておりまして、今回もそのような形になろうかと思いますが。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"それともう一つ、去年も１２月２７日に厚生委員会をこういう形でしているのです。前回は厚生委員会の中で福祉タクシー券というのが出されていたので、そういうところがないというのはどういうことなのか、そういうゆとりはないのか、そこら辺のところも伺えたらと思います。","respondent":"豊嶋生活福祉課長","answer":"家計急変世帯につきましては、今回、やる予定はございません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"それとも、そういう自由な裁量もあって、均等割とかというのも、国から補助というところで説明は伺ったのですけれども、そこら辺、この交付金のスキームというか、自由度というか、そういうところというのはどういう状況になっているのかなと思って聞いたのですが、そこら辺はどうでしょうか。","respondent":"豊嶋生活福祉課長","answer":"この給付金については、国が示しているもの以外に、推奨メニューというメニューがございまして、その辺りを使って、１０分の１０でやれるようにということで区で整えているものです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"それを目いっぱい使って、今回は均等割のみ課税世帯まで対象にするということで、目いっぱい使ってこういう状況だということで捉えていいということですか。","respondent":"豊嶋生活福祉課長","answer":"そのとおりです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました、それは。そういう中で、消費税の減税だったりとか、最低賃金を中小企業も支援して１,５００円にしていくだったりとか、そういう対策というのは本来必要だなと思っているところです。そういうことはここで議論するというものではないので、意見だけ述べします。こういう形で、もちろん３万円が出されるということに対しては、区民にとってはプラスなので、行うべきだと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"今回、閣議決定ということで、総合経済対策、国の事業だと思うのですけれども、そのスキームということで、関連して確認で聞きたいのですが、歳入が都支出金ということになっているのですけれども、国、東京都、特別区、こういう順で降りてくるということでよろしいのか。東京都の役割がどういうものなのか、確認として伺いたいのですけれども。","respondent":"豊嶋生活福祉課長","answer":"都支出金ですので、東京都を経由してこちらのほうにやってくるものです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"すみません、１点だけ。答弁があったら言ってください。なくても構いません。普通にいきましょうよ。そういうことを何でもかんでもそういうふうにしてやるから、十人十色の意見におわびをするようになってしまうのと思うのだよな。だから、こういうことはあまり、私はそういう感覚ではなく、やっていただきたいなと思うのだよな。答弁があれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"意見","question":"賛成です。加えてですけれども、家計急変世帯については、やはり今困っているという状況があるので、ぜひ家計急変世帯も対象にする方向で、今後に向けてということですが、ご検討いただけたらと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6899#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":8702,"voices":41}},{"id":"r06-20241225-9","meetingId":"r06-cm12","date":"2024年12月25日","dateIso":"2024-12-25","committee":"文教委員会","time":"午前１０時０５分～午前１０時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１０８号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"この前、議長と副議長の会合に出席したときに、今回の給付の取扱いについて、城南５区の方にどのようにされるのですかと聞いたら、専決処分にして、要するに議会を開かないとか、来年にするとか、各区ばらばらでした。１点お伺いします。財調基金を取り崩すということになっているのでしょうか。この辺りは、なぜ１０分の１０、国が出ないのかというところのご説明をお願いしたいです。","respondent":"飛田子育て応援課長","answer":"ひとり親世帯の給付金については国からの推奨メニューであり、予算書の作成段階ではまだ分からなかったので、昨年の実績を基に算定していました。財政のほうの話では、今後は１０分の１０で見込めるのではないかということで伺っております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"国が推奨したメニューに、品川区が果敢に手を挙げて、支給対象を拡大したことに対して、国が出さないというのもおかしな話だなと思ったのですけれども、今後は確定ではないが１０分の１０を見込めるということで、安心いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"確認なのですけれども、今回の対象者が１８歳以下の児童のいるご家庭で、ということですが、この児童というのは、ゼロ歳児から１８歳以下までの全ての子どもということでいいのでしょうかということと、そもそも、今お話もありましたが、国の推奨メニューの中にひとり親世帯臨時特別給付金があるということなのですけれども、区として、この部分は独自で行うということなのですが、改めて。","respondent":"飛田子育て応援課長","answer":"現在１８歳また、来年の３月３１日までに１８歳になる方が対象となります。ひとり親世帯臨時特別給付金については、ひとり親もなかなか生活がいろいろ苦しいということで、区独自で支援策を講じるため、このタイミングで提案をさせていただきました。","voiceIndex":10,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ひとり親のご家庭のご苦労というのは自ら経験していないのですけれども、推測で大変だなというのは受け止めております。確かに２万円が入ることで助かったということはあるのだろうと思いますけれども、余裕のある世帯にまで１人当たり２万円を渡すということについて、どのように判断されて、所得制限を外すことにしたのか、そこをお聞かせいただきたいと思います。","respondent":"飛田子育て応援課長","answer":"今回、物価高騰に直面して、特に影響を受けやすいひとり親世帯も、また、ワンオペ等で様々な苦労をしている方が多く存在いたしますので、そういうところを含めまして、より多くの方を支援するために、所得制限なしということで、区独自の給付の対象とさせていただきました。","voiceIndex":12,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"事前の周知・広報もあると思いますが、対象者の方だけではなく、広く区民の理解をいただけるようにしっかりご説明いただいた上での対応が必要かなと思われますので、そこは要望としてお伝えをさせていただければと思います。国からの予算が足りないからということで差額が出ているのですが、その分もここに入っているということなのでしょうか。最後に確認をします。","respondent":"飛田子育て応援課長","answer":"コールセンター等の委託費ですが、５３９万円となっております。システム運用経費も８００万円ほど、併せて行っております。郵送料等がありますので、そういうのを含めて国からの費用の中で、１０分の１０の中で、その中に入れ込むという計算で上げております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西村委員","kind":"質問","question":"支給する金額なのですけれども、２万円と決まった根拠や考え方があれば、伺いたいと考えていますのが１点と、裏面のほうで今後のスケジュールがありますけれども、申請不要者の方と要申請者の方のスケジュールが異なってくるので、要申請者の方がどのような方だったのかというのをもう一度教えていただいてよろしいですか。","respondent":"飛田子育て応援課長","answer":"それと、申請ですが、まず申請の不要な方については、住民税非課税世帯物価高騰対策支援金ということで、生活福祉課でもやっておりますので、そこのデータを基に、その家庭の中でお子さんがいる家庭を抽出しまして、対応します。","voiceIndex":17,"id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"プッシュ型で行われるといいなと思うところはあるのですけれども、申請が必要な方に行き届くように、今後何か対策をお考えでしたら最後に聞かせてください。","respondent":"飛田子育て応援課長","answer":"申請される方は、今、児童手当が所得制限なしで、必ずこちらに申請に来ますので、新しく生まれた方については、またそのときに窓口でお声がけさせていただきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、繰り返しになってしまうかもしれないですけれども、一般財源の３,５００万円は、１の特別給付金の均等割課税世帯への１,１００万円、あとは、ひとり親世帯臨時特別給付金４,７９１万円があるのですけれども、この３,５００万円はどちらにどう行っているのか、２のほうだけなのか、２のほうだけだと足りないと思うのですけれども、すみません教えてください。","respondent":"飛田子育て応援課長","answer":"そのほか、ひとり親世帯につきましては、昨年度の実績で上げさせていただきましたが、財政課の話だと、今後１０分の１０で見込めるということで、こちらも全額、国の歳入でもらえる予定となっております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"僕の理解が悪いのかな。国のほうに３,５００万円を充てる予定でということですか。ごめんなさい。","respondent":"飛田子育て応援課長","answer":"２のほうに充てる予定です。","voiceIndex":24,"id":"exchange-009"},{"speaker":"せらく委員","kind":"確認","question":"今、給付金が２種類が上がっているのですけれども、どちらとも該当する方は、１も２もというように給付を受けることができるのか、確認させてください。","respondent":"飛田子育て応援課長","answer":"国のほうは非課税世帯。非課税世帯に含まれて、２万円もらう方はそのままで、もらえなかったひとり親家庭に対して、児童１人当たり２万円を、区独自で上乗せするということで、二重払いにはなりません。","voiceIndex":27,"id":"exchange-010"},{"speaker":"せらく委員","kind":"質問","question":"それで、金額のところで伺っておきたいのですけれども、１のほうは単純に計算すると、先ほどおっしゃっていただいたように、６,８００万円の給付で、事業経費等で８,２００万円なので、差額が１,０００万円以上あって、その中でコールセンターが五百数十万円と、システム８００万円というところで、２番でいうと、単純計算すると４,２００万円の給付で、事業経費等が４,７００万円で。","respondent":"飛田子育て応援課長","answer":"２のほうが対象人数が少ないということで、例えば、１の事業だと約３,４００名に対して、２のほうは２,１００名、給付の人数も少ないところで、予算としても少ないということになります。","voiceIndex":29,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問","question":"人数は１,３００人ぐらいの差があるというところで、事業経費が倍ぐらいかかっているのが気になっていたところなのですけれども、単純に人数によってという認識でよろしいですか。","respondent":"飛田子育て応援課長","answer":"システムの運営費ですが、まず、非課税世帯と均等割のほうのシステム運用費が８００万円、ひとり親のほうのシステム運用費は５５０万円計上しているところで、その辺で値段がシステムのところでも変わってくるというところで、また差額が出てくるというふうになります。","voiceIndex":31,"id":"exchange-012"},{"speaker":"山本副委員長","kind":"確認","question":"私からも１点確認させてください。","respondent":"飛田子育て応援課長","answer":"こちらは前もって、重複する家庭は除いている人数となります。","voiceIndex":34,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6893#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":6411,"voices":48}},{"id":"r06-20241225-5","meetingId":"r06-cm12","date":"2024年12月25日","dateIso":"2024-12-25","committee":"総務委員会","time":"午前１０時５０分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０８号議案、令和６年度品川区一般会計補正予算","agenda":"第１０８号議案、令和６年度品川区一般会計補正予算","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど各委員会でも審議されたということで、国から補助金として入ってきて、こうした物価高への対応が取られるというところなのですけれども、そもそもこの補助金というのは、品川区に来る総額が決まっていて、その中でこういうメニューでとなっているのか、それとも、メニューにあるものをある程度自由に、補助金として取り入れることができるものなのか、伺いたいと思います。","respondent":"加島財政課長","answer":"補助金自体ですけれども、今回、区独自で実施する部分の補助金については、３億６,０００万円の予算編成を行っております。こちらは、令和５年１２月、臨時補正でご提示いたしました国の交付金の額とほぼ同額となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、国から来る補助金として、今回物価高やエネルギーという名目で出ている補助金としては、区としてはいっぱいいっぱい使っているということでいいのか、それだけ確認させてください。","respondent":"加島財政課長","answer":"国からの補助金につきましては、これから連絡が来るものですけれども、限度額いっぱいまで使わせていただきたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それと、コールセンターなのですけれども、子育てのほうと住民税非課税世帯のほうとで分かれているのですが、これは、子育てのところと違うのかなと思うのですけれども、物価高への対策というところでは一緒なので、効率化というところで、一緒にできないものなのか。それで、それぞれの体制というのが、どれぐらいの人数で、期間としてはいつからいつまでなのかが分かれば伺いたいのですが。","respondent":"加島財政課長","answer":"コールセンターが立ち上がる時期なのですけれども、申し訳ありません、具体の資料については今持っていないのですが、子育て世帯のほうが令和７年３月上旬。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"今の議論からもう一度確認したいのですが、繰入金、これは国から今回は１０分の１０支給されるという形での前提になっているという理解でよろしいですかということ。石田ちひろ委員からも質問がありましたけれども、充当事業という前提なのですが、これはいろいろあると思うのです。では、その品川区の裁量の中で、どういう選定の仕方をしているのかということをご説明いただきたいと思います。","respondent":"加島財政課長","answer":"その趣旨を中心に考えたときに、今回、国の基本メニューといいますか、全体的に給付を行うところは非課税世帯への支援だったのですけれども、令和５年１２月の時点では均等割のみ課税世帯に給付しております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"多少、品川区の現状を踏まえていろいろメニューを決めたということで理解しました。もう１点確認したいのが、子育て世帯に関しても非課税対象になっていて、住民税非課税世帯の給付金とダブっている方がいるのではないかなと思うのですけれども、そんなことはないのですか。こっちが出たらこっちは駄目とかという区別はきちんとされているのでしょうか。","respondent":"加島財政課長","answer":"説明がいろいろ重なってしまって申し訳ございませんでした。国のほうは、住民税非課税世帯の世帯主に３万円、それからそのお子様１人当たりに２万円というところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"ひとり親世帯に対しての２万円というのを品川区がいろいろ考えてということですか。要は、品川区独自でいろいろ現状に合わせて考えた、いずれにしても国から１０分の１０という形で来るよということの中で、品川区がある程度の状況に合わせて支給する先を決められたという理解でよろしいでしょうか。","respondent":"加島財政課長","answer":"背景といたしまして読み取っておりますのは、令和５年度時点になりますけれども、国の子どもの貧困率ですね、日本は今、ひとり親世帯では４４.５％がまだ貧困だと言われている中で、ひとり親世帯についても支給を行っていく必要があると考えました。","voiceIndex":16,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"今、財政課長からいろいろお話を聞きましたけれども、本来、物価高騰対策ということならば、国のほうでこういうものに使いなさいというのはありますが、これはこれで子育て応援費ということでいいのですが、本来なら物価高騰対策と言うならば、やはり年金暮らしの高齢者や、個人事業主、非正規雇用者、年収４００万円以下の方に対する応援もするべきではないかなと私は思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"すみません、私も所管がいないので要望になってしまいますけれども、まずは、補助金をすぐにこうやってひもづけていただくこの品川区の取組には本当に感謝しております。先ほど須貝委員もおっしゃいましたが、産業経済費の中で、この助成はたしか区が独自でもともとやっているものですよね。それでお話を聞くと申込みが多数だということは、相当ニーズがあるのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり物価高騰に苦しんでいる方々がいるわけなので、そうすると、やはり恒久的な減税だったり、中小企業を国が直接支援して賃金を大幅に上げていくとか、そういう大本の対応が必要で、そうやってやってもらえれば、自治体職員の皆さんも出るたびに対応しないといけないという手間もなくなってくるかなと思うのですけれども、やはりそういった大本の対応を国に、消費税減税だったり、中小企業への直接支援。","respondent":"加島財政課長","answer":"恒久的な減税対策というところでご意見をいただきましたけれども、国のほうでこの間、税制の大綱についても話がされていたところですので、品川区といたしましては、国の考え方の下、区独自でこのような補助金を使ってできることがあれば。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国もこういう経済対策と言っているのですけれども、国が出している今回の国民の安心・安全と持続的な成長に向けた総合経済対策をちらっと読ませていただいても、ＧＤＰは６００兆円、設備投資は１００兆円をそれぞれ超えて、賃金も３３年ぶりに高い賃上げが実現したと。ですので、そこはぜひ区としても積極的に、恒久的な減税、中小企業への支援を求めていっていただきたいなと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"新妻副委員長","kind":"確認","question":"ご説明ありがとうございました。これは今回だけでなく、これまでもこれぐらいのスケジュール感だったかと思うのですが、行政の仕組み的にはここを短くすることは難しいのでしょうか。もっと早く支給を開始できないかという視点なのですけれども、そういうのは行政の仕組みとしては難しいのかどうかというところを確認させていただければと思います。","respondent":"加島財政課長","answer":"その後、その中からお子様がいらっしゃる世帯のデータを抽出いたしますので、どうしてもデータの抽出が２段階に分かれてしまう関係上、子どもの給付のほうが後に続く形となってしまうのですけれども、先ほども申し上げたとおり、所管のほうでは一刻も早い給付をというところで。","voiceIndex":27,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問","question":"今後、例えばマイナンバーカードがさらに普及し、公金口座のひもづけ等が進んでいくとなると、マイナンバーカードの活用ということも大いにあるかと思うのですが、そういうことを踏まえての区のデータ構築というところは、進めていただいていると思うのですが、マイナンバーカードの活用というところでは、今回のところでは何か検討されていることがあったのか、また。","respondent":"加島財政課長","answer":"システム構築の具体的な内容まで聞き取っているところではないのですけれども、迅速な給付が行えるように、デジタル推進課とも協力しながら進めてまいりたいと考えております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"でも、区民側からしたときに、これは国からのお金ですとかというのは区別がつかないのです。なので、今後、国の動向もあるでしょうが、やはり全体的な経済状況がどうなのか、困っている人がどこにいるのかというのをもう少し広く状況の調査をするなり、お金の使い方を考えるなりということを、来年度の予算は期待したいと思うのですけれども、考え方はいかがですか。","respondent":"加島財政課長","answer":"なので、決して子育て世帯だけに着目したものではなく、全体をバランスよく見て、今回、横出しの給付を決めたと考えています。それから、当初予算編成につきましては、申し訳ございません、今編成中となっておりますので、こちらについては今お答えすることができません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"これだけ不景気になってくると、やはりどうしても比較論になってきて、あっちのうちはこうで何でうちはこうなのと当然なってくる。やはり住民の皆さんが納得するやり方をぜひとってほしいなという強い思いがあります。なので、来年度楽しみにしたいと思っていますけれども、やはり不平等が感じられないような、そういう税金の使い方をぜひお願いしたいなと思って、終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成ですけれども、先ほども言いましたが、本当に区民の暮らし、今、深刻な状況になっています。お米も大変な状況でしたけれども、新米がまたさらに値上げされるというふうになっていますし、食費を減らしたり、この寒いさなかに電気代を節約したりと、そういう状況になっていますので、こういった国の対応とともに、区としての対応もぜひ、国に求めるということも含めてお願いしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"賛成ですが、今も言いましたので、重複してしまいますけれども、やはり全体を見てほしいなと思います。どの世帯の方々がとか、どういう人たちが大変なのか。今、そういうところに来ています。だけど、お金をばらまいて、出生率が高くなるかというとそうではないわけであって、だから、区民の皆さんの中で納得がいくような予算の使い方をぜひしていただきたいと強く要望して、賛成としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6903#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":10919,"voices":44}},{"id":"r06-20241225-10","meetingId":"r06-cm12","date":"2024年12月25日","dateIso":"2024-12-25","committee":"議会運営委員会","time":"午後 １時１５分～午後 １時１６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6897#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":900,"voices":8}}]);
